	["A twisting cave of snakes, raptors and druids gone bad, with a short escort at the end. Eight bosses."] = "Eine verwinkelte Höhle voller Schlangen, Raptoren und abtrünniger Druiden, mit einer kurzen Eskorte am Ende. Acht Bosse.",
	["A two-handed weapon and Seal of Command from level 20. Simple to play: you hit hard and can heal yourself between fights."] = "Eine Zweihandwaffe und Siegel des Befehls ab Stufe 20. Einfach zu spielen: du schlägst hart zu und kannst dich zwischen Kämpfen selbst heilen.",
	["A vendor who repairs restores worn gear for a fee."] = "Ein Händler, der repariert, richtet abgenutzte Ausrüstung gegen eine Gebühr.",
	["Abilities"] = "Fähigkeiten",
	["About %d minutes on foot"] = "Etwa %d Minuten zu Fuß",
	["About a minute on foot"] = "Etwa eine Minute zu Fuß",
	["About this place"] = "Über diesen Ort",
	["Action Bar 2"] = "Aktionsleiste 2",
	["Add"] = "Zusatzgegner",
	["Add Serpent Sting, then press Arcane Shot every time it is ready."] = "Setz Schlangenbiss und drück dann Arkaner Schuss, sobald er bereit ist.",
	["Add Wrack to the enemy. It makes your other damage over time spells hurt more."] = "Setz Wrack auf den Gegner. Deine anderen Schadenszauber über Zeit treffen dann härter.",
	["Adventure"] = "Abenteuer",
	["Advice cards"] = "Tippkarten",
	["After Barthilas, near the end of the Undead part."] = "Nach Barthilas, nahe dem Ende des untoten Teils.",
	["After Grox. His death opens the big gate behind him."] = "Nach Grox. Sein Tod öffnet das große Tor hinter ihm.",
	["After a big hit on you, you heal yourself for a while."] = "Nach einem harten Treffer auf dich heilst du dich eine Weile.",
	["After a critical Holy Shock or Flash of Light, your next Holy Light casts faster."] = "Nach einem kritischen Heiligen Schock oder Lichtblitz wirkst du dein nächstes Heiliges Licht schneller.",
	["After a critical strike you swing faster for a few hits."] = "Nach einem kritischen Treffer schlägst du für ein paar Treffer schneller zu.",
	["After a critical strike, you deal more damage for a while."] = "Nach einem kritischen Treffer verursachst du eine Weile mehr Schaden.",
	["After a fight, cast Rejuvenation on yourself (and Regrowth from level 12), then move on."] = "Wirk nach einem Kampf Verjüngung auf dich (und ab Stufe 12 Nachwachsen) und zieh dann weiter.",
	["After a kill, your next attack is far more likely to crit."] = "Nach einem Kill trifft dein nächster Angriff viel wahrscheinlicher kritisch.",
	["After one visit Trailhead lists them here with prices."] = "Nach einem Besuch listet Trailhead sie hier mit Preisen auf.",
	["After that"] = "Danach",
	["After the first boss."] = "Nach dem ersten Boss.",
	["After the first bosses."] = "Nach den ersten Bossen.",
	["After you are hit, you often deal more damage for a while."] = "Nachdem du getroffen wurdest, verursachst du oft eine Weile mehr Schaden.",
	["After you are hit, you sometimes block more for a while."] = "Nachdem du getroffen wurdest, blockst du manchmal eine Weile mehr.",
	["Aggro"] = "Aggro",
	["Agility"] = "Beweglichkeit",
	["Agility first, then Stamina and Intellect. Use the hardest-hitting bow, gun or crossbow you can find."] = "Zuerst Beweglichkeit, dann Ausdauer und Intelligenz. Nimm den Bogen, das Gewehr oder die Armbrust mit dem meisten Schaden, die du finden kannst.",
	["Agility first, then Stamina. Two one-handed weapons, and leather armor."] = "Zuerst Beweglichkeit, dann Ausdauer. Zwei Einhandwaffen und Lederrüstung.",
	["Alive"] = "Lebendig",
	["Alive, with Resurrection Sickness"] = "Lebendig, mit Wiederbelebungsnachwirkungen",
	["All %d of your points are spent. You have had one for every level since %d, so the next comes at level %d."] = "Alle %d Punkte sind verteilt. Du hast seit Stufe %d pro Stufe einen bekommen, der nächste kommt also mit Stufe %d.",
	["All your Shadow damage goes up."] = "Dein gesamter Schattenschaden steigt.",
	["All your Shadow spells do more damage and drain more life."] = "Alle deine Schattenzauber verursachen mehr Schaden und entziehen mehr Leben.",
	["All your healing spells heal more."] = "Alle deine Heilzauber heilen mehr.",
	["All your talent points are spent."] = "Alle deine Talentpunkte sind verteilt.",
	["All zones"] = "Alle Zonen",
	["Alliance players can enter, but it is a long, risky walk, and its quests are for the Horde."] = "Allianzspieler können rein, aber der Weg ist lang und riskant, und die Quests dort sind für die Horde.",
	["Almost"] = "Fast",
	["Along the main path, in his own room with no helpers."] = "Am Hauptweg, in seinem eigenen Raum ohne Helfer.",
	["Amberstill Ranch, Dun Morogh"] = "Amberstill-Ranch, Dun Morogh",
	["Ammunition for your bow or gun, and food for your pet."] = "Munition für deinen Bogen oder dein Gewehr und Futter für dein Tier.",
	["An armored fighter with healing and blessings."] = "Ein gepanzerter Kämpfer mit Heilung und Segen.",
	["An enemy's attention. Tanks try to hold it."] = "Die Aufmerksamkeit eines Gegners. Tanks versuchen, sie zu halten.",
	["An extra Frost hit to use while an enemy is chilled."] = "Ein zusätzlicher Frosttreffer für Gegner, die unterkühlt sind.",
	["An extra enemy that joins a fight."] = "Ein zusätzlicher Gegner, der in einen Kampf eingreift.",
	["An instant heal for a friend who has your Rejuvenation or Regrowth on them."] = "Eine Sofortheilung für einen Freund, auf dem deine Verjüngung oder dein Nachwachsen liegt.",
	["An instant heal for anyone who has your Rejuvenation or Regrowth on them."] = "Eine Sofortheilung für jeden, auf dem deine Verjüngung oder dein Nachwachsen liegt.",
	["An ogre fortress in Riverglades, run by the Twilight cult. The route winds up a hill. We know only part of it."] = "Eine Ogerfestung in den Flusslanden, geführt vom Kult des Schattenhammers. Der Weg windet sich einen Hügel hinauf. Wir kennen nur einen Teil davon.",
	["An old quilboar city of bone and thorn, with undead at its heart. Six bosses."] = "Eine alte Stacheleberstadt aus Knochen und Dornen, mit Untoten in ihrem Herzen. Sechs Bosse.",
	["And %d more."] = "Und %d weitere.",
	["Any monster or enemy creature."] = "Jedes Monster oder feindliche Wesen.",
	["Any vendor with an anvil sign can repair it for a few coins."] = "Jeder Händler mit Amboss-Symbol kann es für ein paar Münzen reparieren.",
	["Appears after you buy Dark Iron Ale mugs and hand them to Private Rocknot."] = "Erscheint, nachdem du Krüge Dark Iron Ale kaufst und sie Private Rocknot gibst.",
	["Appears in the Pit of Sacrifice after the Prophet dies. Guides say to pull it with Dreamscythe, one dragon at a time."] = "Erscheint im Pit of Sacrifice, wenn der Prophet stirbt. Guides raten, ihn mit Dreamscythe zu pullen, einen Drachen nach dem anderen.",
	["Appears in the Pit of Sacrifice with Weaver."] = "Erscheint im Pit of Sacrifice zusammen mit Weaver.",
	["Appears in the flooded tomb when the last guardian dies."] = "Erscheint im überfluteten Grab, wenn der letzte Wächter stirbt.",
	["Appears only if you walk the Belnistrasz escort quest to its end."] = "Erscheint nur, wenn du die Eskortquest von Belnistrasz bis zum Ende machst.",
	["Appears when Weaver and Dreamscythe are dead."] = "Erscheint, wenn Weaver und Dreamscythe tot sind.",
	["Appears when the three beer kegs in the bar are smashed."] = "Erscheint, wenn die drei Bierfässer in der Bar zerschlagen sind.",
	["Appears with Hazzas."] = "Erscheint mit Hazzas.",
	["Arcane Shot is ready again sooner, so you press it more often."] = "Arkaner Schuss ist früher wieder bereit, also drückst du ihn öfter.",
	["Area of effect: hits many enemies at once."] = "Flächeneffekt: trifft viele Gegner auf einmal.",
	["Armor"] = "Rüstung",
	["Armory wing, levels 36 to 44. The Scarlet Key opens its door. The key is in the Library wing."] = "Waffenkammerflügel, Stufe 36 bis 44. Der Scharlachrote Schlüssel öffnet die Tür. Der Schlüssel liegt im Flügel Bibliothek.",
	["As of your last visit to the trainer."] = "Stand deines letzten Besuchs beim Lehrer.",
	["Ask an innkeeper to make their inn your home."] = "Bitte einen Gastwirt, sein Gasthaus zu deinem Zuhause zu machen.",
	["Ask your group for the plan."] = "Frag deine Gruppe nach dem Plan.",
	["Ask your raid leader for the plan before each boss."] = "Frag deinen Schlachtzugsleiter vor jedem Boss nach dem Plan.",
	["Ask your raid leader for the plan. Cure curses if you can."] = "Frag deinen Schlachtzugsleiter nach dem Plan. Heb Flüche auf, wenn du kannst.",
	["Ask your raid leader for the plan. Players take control of him."] = "Frag deinen Schlachtzugsleiter nach dem Plan. Spieler übernehmen die Kontrolle über ihn.",
	["At full durability"] = "Volle Haltbarkeit",
	["At level %d your trainer has %s for you, %s in all."] = "Auf Stufe %d hat dein Lehrer %s für dich, insgesamt %s.",
	["At level %d: %d levels to go"] = "Auf Stufe %d: noch %d Stufen",
	["At the Site of the Guardian. Click the panel by the right column to start."] = "An der Stätte des Wächters. Klick auf die Tafel bei der rechten Säule, um zu starten.",
	["At the back of the Iron Hall."] = "Ganz hinten in der Iron Hall.",
	["At the back of the Spider Wing."] = "Ganz hinten im Spinnenviertel.",
	["At the big cannon in the Living part."] = "An der großen Kanone im lebendigen Teil.",
	["At the bottom of the ramp, before the last boss."] = "Unten an der Rampe, vor dem letzten Boss.",
	["At the door to the wizard's room."] = "An der Tür zum Raum des Zauberers.",
	["At the end of the Armory wing."] = "Am Ende des Flügels Waffenkammer.",
	["At the end of the Construct Wing."] = "Am Ende des Konstruktviertels.",
	["At the end of the Library wing."] = "Am Ende des Flügels Bibliothek.",
	["At the end of the Plague Wing."] = "Am Ende des Seuchenviertels.",
	["At the end of the orange side, in Poison Falls."] = "Am Ende der orangen Seite, in den Poison Falls.",
	["At the fireplace of the burned house. Five waves of undead come first."] = "Am Kamin des abgebrannten Hauses. Zuerst kommen fünf Wellen Untote.",
	["At the lowest point of the hall loop."] = "Am tiefsten Punkt der Hallenschleife.",
	["At the start of the Undead part, in the crypts."] = "Am Anfang des untoten Teils, in den Krypten.",
	["At the start, take the first side tunnel on the left. Blastmaster Emi Shortfuse waits at the end."] = "Nimm am Anfang den ersten Seitentunnel links. Blastmaster Emi Shortfuse wartet am Ende.",
	["At the top of a staircase on the left path, in a room with a pool."] = "Oben an einer Treppe auf dem linken Weg, in einem Raum mit einem Becken.",
	["At the top of the spiral ramp in Earth Song Falls."] = "Oben an der Wendelrampe in den Earth Song Falls.",
	["At the very end of the dungeon, on the raised ledge."] = "Ganz am Ende des Dungeons, auf dem erhöhten Vorsprung.",
	["At the west end of the Dark Iron Highway."] = "Am Westende des Dark Iron Highway.",
	["At two points in the fight it makes smaller stone helpers. Kill them."] = "An zwei Stellen im Kampf erschafft er kleinere Steinhelfer. Töte sie.",
	["At vendors"] = "Bei Händlern",
	["Auction"] = "Auktion",
	["Auction house"] = "Auktionshaus",
	["Back"] = "Zurück",
	["Bags"] = "Taschen",
	["Bandages"] = "Verbände",
	["Bank"] = "Bank",
	["Barrow Deeps"] = "",
	["Bars and bags"] = "Leisten und Taschen",
	["Bartering: cheaper prices at vendors"] = "Feilschen: günstigere Preise bei Händlern",
	["Bash (level 14) stuns an enemy for a moment. Use it to stop a hard hit."] = "Hieb (Stufe 14) betäubt einen Gegner kurz. Nutze ihn, um einen harten Treffer zu verhindern.",
	["Bash stuns for longer and is ready again sooner."] = "Hieb betäubt länger und ist früher wieder bereit.",
	["Beat the three at the seal first. If he seems to die early, keep hitting him: he is faking."] = "Besiege zuerst die drei am Siegel. Wenn er zu früh zu sterben scheint, schlag weiter zu: er täuscht nur.",
	["Behind the bar. Attacking him turns the whole bar hostile."] = "Hinter der Theke. Greifst du ihn an, wird die ganze Bar feindlich.",
	["Behind the door that the gnome Weegli blasts open."] = "Hinter der Tür, die der Gnom Weegli aufsprengt.",
	["Being hit is less likely to interrupt your Drain spells and Wrack."] = "Treffer unterbrechen deine Entzugszauber und Wrack seltener.",
	["Being hit is less likely to slow down your healing spells."] = "Treffer verlangsamen deine Heilzauber seltener.",
	["Below the Spiral of Thorns, where he patrols."] = "Unterhalb der Spiral of Thorns, wo er patrouilliert.",
	["Beside game windows"] = "Neben Spielfenstern",
	["Between fights, sit down and drink so your Mana comes back."] = "Setz dich zwischen Kämpfen hin und trink, damit dein Mana zurückkommt.",
	["Beyond him, turn right and climb to a view of the city. The path splits."] = "Hinter ihm biegst du rechts ab und steigst zu einem Blick über die Stadt. Der Weg teilt sich.",
	["Beyond the first boss."] = "Hinter dem ersten Boss.",
	["Bind on equip: yours alone once you put it on."] = "Beim Anlegen gebunden: gehört nur dir, sobald du es anlegst.",
	["Bind on pickup: it is yours alone once you take it."] = "Beim Aufheben gebunden: gehört nur dir, sobald du es aufhebst.",
	["Blessing of Protection is ready sooner, and Blessing of Freedom lasts longer."] = "Segen des Schutzes ist früher bereit und Segen der Freiheit hält länger.",
	["Blocking, and being critically hit, sometimes gives you a free extra attack."] = "Blocken und kritisch getroffen werden gibt dir manchmal einen kostenlosen Zusatzangriff.",
	["Bloodhoof Village, Mulgore"] = "Dorf der Bluthufe, Mulgore",
	["Bloodrage gives you more Rage."] = "Blutrausch gibt dir mehr Wut.",
	["Boats"] = "Schiffe",
	["Boats and zeppelins cross the water. Ask a guard where to board."] = "Schiffe und Zeppeline fahren übers Wasser. Frag eine Wache, wo du einsteigst.",
	["Boats and zeppelins link the continents from the big cities and ports. Ask a city guard which one goes to %s."] = "Schiffe und Zeppeline verbinden die Kontinente von den großen Städten und Häfen aus. Frag eine Stadtwache, welches nach %s fährt.",
	["Bonus left"] = "Restbonus",
	["Bountiful Harvest: more rare materials"] = "Reiche Ernte: mehr seltene Materialien",
	["Break her mind control."] = "Brich ihre Gedankenkontrolle.",
	["Break his mind control."] = "Brich seine Gedankenkontrolle.",
	["Break mind control quickly."] = "Brich Gedankenkontrolle schnell.",
	["Break people out of the webs fast."] = "Befrei Leute schnell aus den Netzen.",
	["Break roots if you can. Stay out of the green pools."] = "Lös Wurzeln, wenn du kannst. Bleib aus den grünen Pfützen raus.",
	["Brill, Tirisfal Glades"] = "Brill, Tirisfal",
	["Bring a way to breathe underwater if you have one."] = "Nimm etwas zum Unterwasseratmen mit, wenn du hast.",
	["Bring a way to cure disease and poison."] = "Nimm etwas gegen Krankheit und Gift mit.",
	["Bring back"] = "Zurückholen",
	["Bring back the advice you closed on the Home page."] = "Hol die Tipps zurück, die du auf der Startseite geschlossen hast.",
	["Bring fear protection."] = "Nimm Schutz vor Furcht mit.",
	["Bring fire and shadow resistance gear if you have some."] = "Nimm Ausrüstung mit Feuer- und Schattenwiderstand mit, wenn du welche hast.",
	["Bring fire resistance gear if your guild has some."] = "Nimm Feuerwiderstandsausrüstung mit, wenn deine Gilde welche hat.",
	["Bring nature resistance gear."] = "Nimm Naturwiderstandsausrüstung mit.",
	["Bring the key. The door is locked."] = "Bring den Schlüssel mit. Die Tür ist verschlossen.",
	["Buff"] = "Stärkungszauber",
	["Build complete"] = "Skillung fertig",
	["Builds"] = "Skillungen",
	["Builds are written from the game's own talent texts. Your class has none yet."] = "Skillungen werden aus den Talenttexten des Spiels geschrieben. Für deine Klasse gibt es noch keine.",
	["Buy the abilities you use, sell what you do not need, and put the rest aside."] = "Kauf die Fähigkeiten, die du nutzt, verkauf, was du nicht brauchst, und leg den Rest beiseite.",
	["By the game's own tables, at level %d your trainer should have %s."] = "Laut den Tabellen des Spiels sollte dein Lehrer auf Stufe %d %s haben.",
	["Call Pet, put Hunter's Mark on the enemy, then shoot with Auto Shot."] = "Ruf dein Tier mit Tier rufen, setz Mal des Jägers auf den Gegner und schieß dann mit Automatischer Schuss.",
	["Called out by a mail quest in the Living part."] = "Wird durch eine Postquest im lebendigen Teil gerufen.",
	["Called out for a quest in the Living part."] = "Wird für eine Quest im lebendigen Teil gerufen.",
	["Called out near Ras Frostwhisper with a quest item (a brazier)."] = "Wird nahe Ras Frostwhisper mit einem Questgegenstand (einem Kohlebecken) gerufen.",
	["Called out on the patio with a quest item (Blood of Innocents)."] = "Wird auf der Terrasse mit einem Questgegenstand (Blood of Innocents) gerufen.",
	["Camera"] = "Kamera",
	["Camping"] = "Lagern",
	["Candles for group buffs later, and a feather for Levitate."] = "Kerzen für spätere Gruppen-Stärkungszauber und eine Feder für Levitieren.",
	["Cast Blessing of Wisdom (level 14) on party members who use Mana, and on yourself."] = "Wirk Segen der Weisheit (Stufe 14) auf Gruppenmitglieder, die Mana nutzen, und auf dich.",
	["Cast Corruption and Bane of Agony on the enemy, then Shadow Bolt until it falls."] = "Wirk Verderbnis und Omen der Pein auf den Gegner, dann Schattenblitz, bis er fällt.",
	["Cast Healing Wave on whoever has the lowest health bar. Heal early."] = "Wirk Welle der Heilung auf den mit der niedrigsten Gesundheitsleiste. Heil früh.",
	["Cast Ice Barrier on yourself before a hard fight."] = "Wirk vor einem harten Kampf Eisbarriere auf dich.",
	["Cast Mark of the Wild on everyone before the first fight."] = "Wirk vor dem ersten Kampf Mal der Wildnis auf alle.",
	["Cast Seal of Righteousness before the fight, then hit the enemy with your weapon."] = "Wirk vor dem Kampf Siegel der Rechtschaffenheit und schlag den Gegner dann mit deiner Waffe.",
	["Casts damaging spells and calls demons to help."] = "Wirkt Schadenszauber und ruft Dämonen zu Hilfe.",
	["Casts strong spells from a distance. Makes food and water."] = "Wirkt aus der Ferne starke Zauber. Stellt Essen und Wasser her.",
	["Cat Form (level 20): Claw, or Shred from behind, builds points. Ferocious Bite (level 24) spends them."] = "Katzengestalt (Stufe 20): Klaue, oder Schreddern von hinten, baut Punkte auf. Wilder Biss (Stufe 24) verbraucht sie.",
	["Cathedral wing, levels 38 to 46, the strongest. It also needs the Scarlet Key to reach its portal."] = "Kathedralenflügel, Stufe 38 bis 46, der stärkste. Auch hier braucht man den Scharlachroten Schlüssel, um sein Portal zu erreichen.",
	["Challenges you finish earn them. Your whole account shares them."] = "Du bekommst sie für abgeschlossene Herausforderungen. Dein ganzer Account teilt sie.",
	["Change into Bear Form, then use Maul and Growl to keep the enemy on you."] = "Wechsle in Bärengestalt und nutze dann Zermalmen und Knurren, um den Gegner bei dir zu halten.",
	["Change into Bear Form. Start each fight with Growl, so the enemy attacks you."] = "Wechsle in Bärengestalt. Beginne jeden Kampf mit Knurren, damit der Gegner dich angreift.",
	["Changes shape: bear to take hits, cat to fight, or heals."] = "Wechselt die Gestalt: Bär zum Einstecken, Katze zum Kämpfen, oder Heilung.",
	["Changing form costs less Mana, so you can change often."] = "Gestaltwechsel kostet weniger Mana, also kannst du oft wechseln.",
	["Changing form costs less Mana."] = "Gestaltwechsel kostet weniger Mana.",
	["Changing into Bear Form can give you Rage to start a fight with."] = "In Bärengestalt zu wechseln kann dir Wut zum Start eines Kampfes geben.",
	["Character"] = "Charakter",
	["Character window, then the Reputation tab"] = "Charakterfenster, dann der Reiter Ruf",
	["Charcoal and orange, sharp and bold"] = "Anthrazit und Orange, klar und kräftig",
	["Charge gives more Rage, so every fight starts with a hit ready."] = "Sturmangriff gibt mehr Wut, so hast du zu Beginn jedes Kampfes gleich einen Angriff bereit.",
	["Charge in, put Rend on the enemy, then spend Rage on Heroic Strike."] = "Stürm heran, belege den Gegner mit Verwunden und gib dann deine Wut für Heldenhafter Stoß aus.",
	["Chat channels"] = "Chat-Channels",
	["Chat commands"] = "Chatbefehle",
	["Check complete"] = "Prüfung fertig",
	["Chest"] = "Brust",
	["Chill effects last longer and slow enemies more, so they reach you later."] = "Kälteeffekte halten länger und verlangsamen Gegner stärker, so erreichen sie dich später.",
	["Choose which key does what. Trailhead does not change keys."] = "Leg fest, welche Taste was macht. Trailhead ändert keine Tasten.",
	["Class"] = "Klasse",
	["Class trainer"] = "Klassenlehrer",
	["Class trainers teach new spells and new ranks of old ones. Visit yours every couple of levels."] = "Klassenlehrer bringen dir neue Zauber und neue Ränge alter Zauber bei. Besuch deinen alle paar Stufen.",
	["Classic or Enhanced: two ready-made sets of settings for how the game looks and plays. Read the buttons there before you pick."] = "Classic oder Enhanced: zwei fertige Sätze von Einstellungen dafür, wie das Spiel aussieht und sich spielt. Lies die Schaltflächen dort, bevor du wählst.",
	["Claw, Rake, Shred, Maul and Swipe hit harder, and it opens Lacerate."] = "Klaue, Krallenhieb, Schreddern, Zermalmen und Prankenhieb treffen härter, und es schaltet Aufschlitzen frei.",
	["Cleanse and Purify cost less Mana, and Exorcism and Holy Wrath are ready sooner."] = "Reinigung des Glaubens und Läutern kosten weniger Mana, und Exorzismus und Heiliger Zorn sind früher wieder bereit.",
	["Clear every guard before you pull a boss. They join the fight."] = "Besiege alle Wachen, bevor du einen Boss angreifst. Sie greifen sonst in den Kampf ein.",
	["Clear his helpers before you start on him. The tank holds them while others kill them."] = "Besiege seine Helfer, bevor du ihn angreifst. Der Tank hält sie, während die anderen sie töten.",
	["Clear the area first. Interrupt her spells and kill her totems."] = "Säubere zuerst die Umgebung. Unterbrich ihre Zauber und zerstöre ihre Totems.",
	["Clear the dragonkin first or they join the fight. He puts the player he is most angry at to sleep."] = "Besiege zuerst die Drachkin, sonst greifen sie in den Kampf ein. Er schickt den Spieler schlafen, auf den er am wütendsten ist.",
	["Clear the goblins around him first, then pull him on his own."] = "Besiege zuerst die Goblins um ihn herum und zieh ihn dann allein.",
	["Clear the goblins in the room first. When the machine dies, Sneed jumps out and can disarm someone."] = "Besiege zuerst die Goblins im Raum. Wenn die Maschine zerstört ist, springt Sneed heraus und kann jemanden entwaffnen.",
	["Clear the guards first. His veil cuts the healing you get, so interrupt it."] = "Besiege zuerst die Wachen. Sein Schleier verringert die Heilung, die du bekommst, also unterbrich ihn.",
	["Clear the guards first. Interrupt his fear."] = "Besiege zuerst die Wachen. Unterbrich seinen Furchtzauber.",
	["Clear the murlocs in his room first, then pull him alone."] = "Besiege zuerst die Murlocs in seinem Raum und zieh ihn dann allein.",
	["Clear the room first. His fear scatters the group and pulls the rest."] = "Säubere zuerst den Raum. Sein Furchtzauber zerstreut die Gruppe und lockt den Rest an.",
	["Clear the whole hold first. He drains mana."] = "Säubere zuerst den ganzen Frachtraum. Er entzieht Mana.",
	["Clear the whole room before you pull."] = "Säubere den ganzen Raum, bevor du ihn angreifst.",
	["Click a player's name in chat to whisper them. Shift-click an item to put it in a chat message."] = "Klick im Chat auf den Namen eines Spielers, um ihm zuzuflüstern. Klick mit gedrückter Umschalttaste auf einen Gegenstand, um ihn in eine Chatnachricht zu setzen.",
	["Click the shrines in the right order or you get cursed. Do not jump into the pit."] = "Klick die Schreine in der richtigen Reihenfolge an, sonst wirst du verflucht. Spring nicht in die Grube.",
	["Click: open or close\nRight-click: settings\nDrag: move this button"] = "Klick: öffnen oder schließen\nRechtsklick: Einstellungen\nZiehen: diese Schaltfläche verschieben",
	["Climb out of the sewers into the streets of Dalaran."] = "Klettere aus der Kanalisation hinauf in die Straßen von Dalaran.",
	["Close the window when a fight starts and bring it back afterwards."] = "Das Fenster schließen, wenn ein Kampf beginnt, und danach wieder öffnen.",
	["Comes out of the pool when someone hits the gong with the Mallet of Zul'Farrak."] = "Kommt aus dem Becken, wenn jemand mit dem Mallet of Zul'Farrak auf den Gong schlägt.",
	["Comes with the last wave of the stairs event."] = "Kommt mit der letzten Welle des Treppenereignisses.",
	["Coming up"] = "Demnächst",
	["Commands:"] = "Befehle:",
	["Condition"] = "Zustand",
	["Cone of Cold, an area blast in front of you, hits harder."] = "Kältekegel, ein Flächenangriff vor dir, trifft härter.",
	["Consecration, Exorcism and Holy Wrath cost less Mana."] = "Weihe, Exorzismus und Heiliger Zorn kosten weniger Mana.",
	["Corruption casts faster and hurts more."] = "Verderbnis wird schneller gewirkt und richtet mehr Schaden an.",
	["Cost: about %s."] = "Kosten: etwa %s.",
	["Crafting"] = "Handwerk",
	["Critical strikes give you extra Rage, so you can use your attacks more."] = "Kritische Treffer geben dir zusätzliche Wut, so kannst du deine Angriffe öfter einsetzen.",
	["Cross the bridge to the north."] = "Überquere die Brücke im Norden.",
	["Cross the courtyard and go in through the doors to the twisting halls of the main keep."] = "Überquere den Hof und geh durch die Türen in die verwinkelten Hallen der Hauptburg.",
	["Cross the marsh to Stalker's Thicket, a field of tall grass full of raptors."] = "Durchquere den Sumpf bis zum Pirscherdickicht, einem Feld aus hohem Gras voller Raptoren.",
	["Cross the sea to %s"] = "Über das Meer nach %s",
	["Crowd control: keeps an enemy from fighting for a while."] = "Massenkontrolle: hält einen Gegner eine Weile vom Kämpfen ab.",
	["Crypts under the tower of Karazhan, carried over from an earlier season. We only know the boss list, not the route."] = "Gruften unter dem Turm von Karazhan, aus einer früheren Saison übernommen. Wir kennen nur die Bossliste, nicht den Weg.",
	["Cultists cast spells that hurt. Pull one group at a time."] = "Kultisten wirken schmerzhafte Zauber. Zieh immer nur eine Gruppe.",
	["Cure his curse on the group."] = "Entferne seinen Fluch von der Gruppe.",
	["Cure the disease called Ghoul Plague at once. It slows you."] = "Heile die Krankheit Ghulseuche sofort. Sie verlangsamt dich.",
	["Cure whatever he casts on the group."] = "Entferne alles, was er auf die Gruppe wirkt.",
	["Damage"] = "Schaden",
	["Damage over time and a Voidwalker to hold the enemy. You start a fight, then watch it fall. Slow and safe, with little to learn."] = "Schaden über Zeit und ein Leerwandler, der den Gegner hält. Du beginnst einen Kampf und siehst zu, wie der Gegner fällt. Langsam und sicher, mit wenig zu lernen.",
	["Damage per second. A player who deals damage."] = "Schaden pro Sekunde. Ein Spieler, der Schaden verursacht.",
	["Danger and PvP"] = "Gefahr und PvP",
	["Darnassus"] = "",
	["Date unknown"] = "Datum unbekannt",
	["Debuff"] = "Schwächungszauber",
	["Dedicated Study: raises your lowest profession"] = "Engagiertes Studium: steigert deinen niedrigsten Beruf",
	["Deep in the temple, after the dragon fights. No ritual or quest is needed."] = "Tief im Tempel, nach den Drachenkämpfen. Kein Ritual und keine Quest nötig.",
	["Deep inside Blackrock Depths, past the lava lake. Reach it through the Blackrock Mountain entrance in the Burning Steppes or Searing Gorge."] = "Tief in den Blackrocktiefen, hinter dem Lavasee. Du erreichst es über den Eingang zum Blackrock in der Brennenden Steppe oder der Sengenden Schlucht.",
	["Deeper in the Graveyard wing, near the end."] = "Tiefer im Flügel Friedhof, kurz vor dem Ende.",
	["Deeper in the Undead part."] = "Tiefer im Untotenteil.",
	["Deeper in the city. Exact place is not known."] = "Tiefer in der Stadt. Der genaue Ort ist nicht bekannt.",
	["Defeat a boss in a dungeon with a group"] = "Besiege mit einer Gruppe einen Boss in einem Dungeon",
	["Demon Armor protects you better."] = "Dämonenrüstung schützt dich besser.",
	["Did you know?"] = "Wusstest du schon?",
	["Diplomat: reputation grows faster"] = "Diplomat: Ruf steigt schneller",
	["Dire Maul is a ruined elf city in Feralas with three parts: East, West and North. All three are in this one dungeon."] = "Düsterbruch ist eine verfallene Elfenstadt in Feralas mit drei Teilen: Ost, West und Nord. Alle drei gehören zu diesem einen Dungeon.",
	["Dive into the pool beside the staircase to reach the flooded tomb."] = "Tauch in das Becken neben der Treppe, um zur überfluteten Gruft zu gelangen.",
	["Divine Favor makes your next heal a critical heal. Save it for an emergency."] = "Göttliche Gunst macht deine nächste Heilung zu einer kritischen Heilung. Heb sie dir für einen Notfall auf.",
	["Divine Shield and Divine Protection are ready sooner, and Forbearance wears off faster."] = "Gottesschild und Göttlicher Schutz sind früher wieder bereit, und Vorahnung klingt schneller ab.",
	["Do East first. It has the key for the others."] = "Mach zuerst Ost. Dort gibt es den Schlüssel für die anderen.",
	["Do not chain-pull. Wait for the ogre patrols to pass."] = "Zieh nicht eine Gruppe nach der anderen. Warte, bis die Ogerpatrouillen vorbei sind.",
	["Do not fight him in a doorway."] = "Kämpf nicht in einem Durchgang gegen ihn.",
	["Do not hit the friendly drinkers."] = "Greif die freundlichen Trinker nicht an.",
	["Do not jump or fall down. Monsters on lower paths run up to you."] = "Spring oder fall nicht hinunter. Monster auf tieferen Wegen laufen zu dir herauf.",
	["Do not kill them at the same time as each other."] = "Tötet sie nicht gleichzeitig.",
	["Do not stand in damage on the ground. Move out of it."] = "Bleib nicht in Schadensflächen am Boden stehen. Geh hinaus.",
	["Do not stand in front of him."] = "Steh nicht vor ihm.",
	["Do not stand in his fire."] = "Steh nicht in seinem Feuer.",
	["Do not stand near the player who burns."] = "Steh nicht in der Nähe des brennenden Spielers.",
	["Do not stand near the tank when he casts his fire spell."] = "Steh nicht nahe beim Tank, wenn er seinen Feuerzauber wirkt.",
	["Do not stay in his sight."] = "Bleib nicht in seinem Blickfeld.",
	["Do not tank near the edge. He knocks you back."] = "Tankt ihn nicht nahe am Rand. Er schleudert dich zurück.",
	["Do not wander off. The city is huge and easy to get lost in."] = "Lauf nicht weg. Die Stadt ist riesig, man verirrt sich leicht.",
	["Do the attunement quest before raid night."] = "Erledige die Zugangsquest vor dem Schlachtzugsabend.",
	["Do the quests first. Reports say they give the key."] = "Erledige zuerst die Quests. Berichten zufolge geben sie den Schlüssel.",
	["Done"] = "Fertig",
	["Down"] = "Besiegt",
	["Draft"] = "Entwurf",
	["Draft: every point is checked against the game's talent data, but we have not played this build through yet."] = "Entwurf: Jeder Punkt ist mit den Talentdaten des Spiels abgeglichen, aber wir haben diesen Build noch nicht durchgespielt.",
	["Drag each one from your spellbook to an empty bar slot."] = "Zieh jeden aus deinem Zauberbuch auf einen freien Platz der Leiste.",
	["Drag the title bar to move the window. This puts it back in the middle."] = "Zieh an der Titelleiste, um das Fenster zu verschieben. Hiermit kommt es zurück in die Mitte.",
	["Drag them from your spellbook to a bar."] = "Zieh sie aus deinem Zauberbuch auf eine Leiste.",
	["Dragon"] = "Drache",
	["Drain Life and Wrack hurt more for each other Affliction effect on the target."] = "Blutsauger und Wrack richten für jeden weiteren Gebrechen-Effekt auf dem Ziel mehr Schaden an.",
	["Drain Soul drains the enemy while you hold it. If the enemy dies from it, you get a Soul Shard."] = "Seelendieb entzieht dem Gegner Leben, solange du ihn kanalisierst. Stirbt der Gegner daran, erhältst du einen Seelensplitter.",
	["Dungeon"] = "Dungeon",
	["Dungeon for a group of five"] = "Dungeon für eine Gruppe aus fünf",
	["Dungeon guide"] = "Dungeonführer",
	["Dungeon healer"] = "Dungeonheiler",
	["Dungeon tank"] = "Dungeontank",
	["Dungeon, levels %d to %d"] = "Dungeon, Stufe %d bis %d",
	["Dungeon: %s"] = "Dungeon: %s",
	["Dungeons"] = "Dungeons",
	["Dungeons and the levels they are meant for. You are level %d."] = "Dungeons und die Stufen, für die sie gedacht sind. Du bist Stufe %d.",
	["Dungeons need a group of five and you travel to the entrance yourselves."] = "Dungeons brauchen eine Gruppe aus fünf, und ihr reist selbst zum Eingang.",
	["Dungeons need a group of five."] = "Dungeons brauchen eine Gruppe aus fünf.",
	["Dying"] = "Sterben",
	["Each PvP season has a journey with weekly tasks. They give Honor and Rank Points, and three of them in a season also give a Legacy Point."] = "Jede PvP-Saison hat eine Reise mit wöchentlichen Aufgaben. Sie geben Ehre und Rangpunkte, und drei davon geben pro Saison auch einen Vermächtnispunkt.",
	["Each Shadow spell makes the enemy take more Shadow damage from you."] = "Jeder Schattenzauber lässt den Gegner mehr Schattenschaden von dir erleiden.",
	["Each bag slot next to your backpack takes one more bag. Monsters drop them, tailors make them, and the auction house sells them."] = "Jeder Taschenplatz neben deinem Rucksack nimmt eine weitere Tasche auf. Monster lassen sie fallen, Schneider stellen sie her, und im Auktionshaus gibt es sie zu kaufen.",
	["Each gong ring brings spiders from both sides. The third ring calls the boss."] = "Jeder Gongschlag lockt Spinnen von beiden Seiten an. Der dritte ruft den Boss.",
	["Each raid resets once a week"] = "Jeder Schlachtzug wird einmal pro Woche zurückgesetzt",
	["Each raid resets once a week."] = "Jeder Schlachtzug wird einmal pro Woche zurückgesetzt.",
	["Each tick of Mind Flay hits harder than the one before it."] = "Jeder Tick von Gedankenschinden trifft härter als der vorige.",
	["Each week"] = "Jede Woche",
	["Each wing is a separate part. You can try them in any order."] = "Jeder Flügel ist ein eigener Teil. Du kannst sie in beliebiger Reihenfolge angehen.",
	["Early in the stronghold. Exact place is not known."] = "Früh in der Festung. Der genaue Ort ist nicht bekannt.",
	["Early on, finish quests, sell grey items, and spend only on abilities and food. Put the rest aside for riding."] = "Erledige anfangs Quests, verkaufe graue Gegenstände und gib Gold nur für Fähigkeiten und Essen aus. Leg den Rest fürs Reiten beiseite.",
	["Early reports say the quests are for the Alliance. We have not confirmed it."] = "Erste Berichte sagen, die Quests sind für die Allianz. Bestätigt haben wir das nicht.",
	["Earthcaller Halmgar is a rare boss on a plateau after Ramtusk. He does not always show up and is not needed."] = "Earthcaller Halmgar ist ein rarer Boss auf einem Plateau nach Ramtusk. Er taucht nicht immer auf und ist nicht nötig.",
	["East part first, the Warpwood Quarter. It has no key door. The game lists its bosses in the order below."] = "Zuerst der Ostteil, das Warpwood Quarter. Es hat keine Schlüsseltür. Das Spiel listet seine Bosse in der Reihenfolge unten.",
	["Eastvale Logging Camp, Elwynn Forest"] = "Holzfällerlager des Osttals, Wald von Elwynn",
	["Easy levelling"] = "Leichtes Leveln",
	["Easy to beat."] = "Leicht zu besiegen.",
	["Easy to pull by accident, and that often ends in a wipe. Stop and get ready first."] = "Leicht aus Versehen zu ziehen, und das endet oft mit dem Tod der ganzen Gruppe. Halte an und mach dich erst bereit.",
	["Edit Mode"] = "Bearbeitungsmodus",
	["Elite monsters walk the tunnel outside. Go in as a group."] = "Elitemonster laufen im Tunnel draußen herum. Geht als Gruppe hinein.",
	["Elite, rare"] = "Elite, rar",
	["Ember"] = "Glut",
	["Empty slots"] = "Leere Plätze",
	["Enemies that crit you take some of the pain themselves."] = "Gegner, die dich kritisch treffen, erleiden selbst einen Teil des Schadens.",
	["Enemy at your feet? Frost Nova freezes it. Back away before you cast, as damage can break the freeze."] = "Gegner direkt bei dir? Frostnova friert ihn ein. Geh zurück, bevor du zauberst, denn Schaden kann das Einfrieren beenden.",
	["Enemy territory"] = "Feindliches Gebiet",
	["Energy, which refills fast, and combo points."] = "Energie, die sich schnell auffüllt, und Combopunkte.",
	["Enter and go up to the patio where the first boss is summoned. The game lists the bosses in the order below; groups may vary it."] = "Geh hinein und hinauf zur Terrasse, wo der erste Boss beschworen wird. Das Spiel listet die Bosse in der Reihenfolge unten; Gruppen weichen manchmal davon ab.",
	["Enter the furbolg tunnel in northern Azshara. The portal is deep inside it."] = "Betritt den Furbolgtunnel im Norden von Azshara. Das Portal liegt tief darin.",
	["Entrance in %s"] = "Eingang in %s",
	["Evasion and Sprint are ready far more often."] = "Entrinnen und Sprinten sind viel öfter bereit.",
	["Every boss is down. Well done!"] = "Alle Bosse sind besiegt. Gut gemacht!",
	["Every character you play with Trailhead, saved each time you log out."] = "Jeder Charakter, den du mit Trailhead spielst, gespeichert bei jedem Ausloggen.",
	["Every class spell you know is on a bar. Nothing to do here."] = "Alle Klassenzauber, die du kennst, liegen auf einer Leiste. Hier gibt es nichts zu tun.",
	["Every enemy shows a level. The colour of its name tells you how a fight against it will go. Players of the other side can also be a danger."] = "Jeder Gegner zeigt eine Stufe. Die Farbe seines Namens zeigt dir, wie ein Kampf gegen ihn ausgehen wird. Auch Spieler der anderen Fraktion können gefährlich sein.",
	["Every kind of weapon has its own skill. It rises as you fight with that kind of weapon, up to a limit of 5 for each level you have. Every point under the limit takes a little off your chance to hit and to crit."] = "Jede Waffenart hat ihre eigene Fertigkeit. Sie steigt, wenn du mit dieser Waffenart kämpfst, bis zu einer Grenze von 5 pro Stufe. Jeder Punkt unter der Grenze senkt deine Trefferchance und deine Chance auf kritische Treffer ein wenig.",
	["Every point in this build is placed."] = "Jeder Punkt dieses Builds ist verteilt.",
	["Every trainer, vendor and mailbox you use is remembered. Find it again from the Find it tab."] = "Jeder Lehrer, Händler und Briefkasten, den du benutzt, wird gemerkt. Du findest ihn über den Reiter Finden wieder.",
	["Everything Trailhead knows about this"] = "Alles, was Trailhead darüber weiß",
	["Everything is at full durability"] = "Alles hat volle Haltbarkeit",
	["Everything you wear is at full durability. Nothing to repair."] = "Alles, was du trägst, hat volle Haltbarkeit. Nichts zu reparieren.",
	["Eviscerate costs much less Energy."] = "Ausweiden kostet viel weniger Energie.",
	["Eviscerate, your finishing move, hits harder."] = "Ausweiden, dein Finishing Move, trifft härter.",
	["Exalted"] = "Ehrfürchtig",
	["Execute (level 24) finishes an enemy that has 20% Health or less."] = "Hinrichten (Stufe 24) erledigt einen Gegner mit 20% Gesundheit oder weniger.",
	["Execute costs less Rage."] = "Hinrichten kostet weniger Wut.",
	["Extra vendor buttons"] = "Zusätzliche Händlerknöpfe",
	["Falling into the central pit hurts a lot. Use the stairs."] = "Ein Sturz in die Grube in der Mitte tut sehr weh. Nimm die Treppe.",
	["Far above you. It will kill you, so walk around it."] = "Weit über deiner Stufe. Er tötet dich, also geh um ihn herum.",
	["Faster attacks that also hit a second enemy."] = "Schnellere Angriffe, die auch einen zweiten Gegner treffen.",
	["Feet"] = "Füße",
	["Fewer of your attacks are dodged or parried."] = "Weniger deiner Angriffe werden ausgewichen oder pariert.",
	["Field Guide: camp features come back sooner"] = "Leitfaden: Lagerfunktionen sind früher wieder bereit",
	["Field Medicine: shorter bandage wait"] = "Feldmedizin: kürzere Wartezeit für Verbände",
	["Fight him in a corner."] = "Kämpf in einer Ecke gegen ihn.",
	["Fight him inside the pool so his knockback hurts less."] = "Kämpf im Becken gegen ihn, dann schmerzt sein Rückstoß weniger.",
	["Fight in Bear Form and keep enemies on you while your group hits them. You take a lot of damage and have the armor for it."] = "Kämpf in Bärengestalt und halte die Gegner bei dir, während deine Gruppe sie angreift. Du steckst viel Schaden ein und hast die Rüstung dafür.",
	["Fight in Bear Form to start, then Cat Form from level 20. You take hits well and can heal yourself between fights."] = "Kämpf anfangs in Bärengestalt, ab Stufe 20 dann in Katzengestalt. Du steckst Treffer gut weg und kannst dich zwischen Kämpfen selbst heilen.",
	["Fight up close with weapon hits, backed by Lightning Shield. Stormstrike at level 25 and a steady supply of Mana make the fights easy to follow."] = "Kämpf im Nahkampf mit Waffenhieben, unterstützt von Blitzschlagschild. Sturmschlag ab Stufe 25 und stets genug Mana machen die Kämpfe leicht überschaubar.",
	["Fight with a shield. Seal of Fury (level 10) gives you a small shield with each hit."] = "Kämpf mit einem Schild. Siegel des Furors (Stufe 10) gibt dir bei jedem Treffer einen kleinen Schutzschild.",
	["Fighting"] = "Kampf",
	["Fights"] = "Kämpfe",
	["Fill your mana before the wave fights."] = "Füll dein Mana vor den Wellenkämpfen auf.",
	["Find"] = "Finden",
	["Find a flight master"] = "Flugmeister finden",
	["Find a group"] = "Gruppe finden",
	["Find a profession trainer"] = "Berufslehrer finden",
	["Find a trainer, vendor, bank or inn"] = "Lehrer, Händler, Bank oder Gasthaus finden",
	["Find a vendor"] = "Händler finden",
	["Find a weapon master"] = "Waffenmeister finden",
	["Find an inn"] = "Gasthaus finden",
	["Find anything: trainer, bank, a zone, a dungeon..."] = "Alles finden: Lehrer, Bank, Gebiet, Dungeon...",
	["Find it"] = "Finden",
	["Find my trainer"] = "Meinen Lehrer finden",
	["Find nearby"] = "In der Nähe",
	["Find repair"] = "Reparatur finden",
	["Find the auction house"] = "Auktionshaus finden",
	["Find the riding trainer"] = "Reitlehrer finden",
	["Find trainer"] = "Lehrer finden",
	["Find your trainer"] = "Deinen Lehrer finden",
	["Finding the door"] = "Den Eingang finden",
	["Finger"] = "Finger",
	["Finish Legacy Challenges. Each one is worth one point, shared by every character on your account. There are 65 at launch: Classes 27, Professions 18, PvP 12, Dungeons 3, Raids 3, Adventure 2."] = "Schließe Vermächtnis-Herausforderungen ab. Jede ist einen Punkt wert, den alle Charaktere deines Accounts teilen. Zum Start gibt es 65: Klassen 27, Berufe 18, PvP 12, Dungeons 3, Schlachtzüge 3, Abenteuer 2.",
	["Finishing moves often give a combo point back."] = "Finishing Moves geben oft einen Combopunkt zurück.",
	["Fire Blast is a quick extra hit. Use it to finish an enemy that is nearly dead."] = "Feuerschlag ist ein schneller zusätzlicher Treffer. Erledige damit einen Gegner, der fast tot ist.",
	["First boss of the orange side, in a poison cave."] = "Erster Boss der orangen Seite, in einer Gifthöhle.",
	["First boss of the purple side, on the upper level."] = "Erster Boss der violetten Seite, auf der oberen Ebene.",
	["First steps"] = "Erste Schritte",
	["Flash Heal on a friend also heals you."] = "Blitzheilung auf einen Verbündeten heilt auch dich.",
	["Flash of Light and Holy Light are less likely to be slowed when you are hit."] = "Lichtblitz und Heiliges Licht werden seltener verzögert, wenn du getroffen wirst.",
	["Flight"] = "Flug",
	["Flight master"] = "Flugmeister",
	["Flight masters connect the towns you have already visited."] = "Flugmeister verbinden die Orte, die du schon besucht hast.",
	["Flight point: %s"] = "Flugpunkt: %s",
	["Flight points for your side, nearest first"] = "Flugpunkte deiner Fraktion, nächste zuerst",
	["Fly to %s"] = "Flieg nach %s",
	["Fly to flight masters you have met before, for a small fee."] = "Flieg gegen eine kleine Gebühr zu Flugmeistern, die du schon kennst.",
	["Follow the cave tunnel back up into the main hall."] = "Folge dem Höhlentunnel zurück hinauf in die Haupthalle.",
	["Follow the marker to %s"] = "Folge der Markierung zu %s",
	["Follow the paths down to Earth Song Falls, the waterfall cave at the bottom."] = "Folge den Wegen hinunter zu Earth Song Falls, der Wasserfallhöhle ganz unten.",
	["Follow the tunnel down to the cave with the pool and step into the way in. You arrive in a big central cave."] = "Folge dem Tunnel hinunter zur Höhle mit dem Becken und tritt in den Eingang. Du kommst in einer großen Höhle in der Mitte an.",
	["Follow the tunnel into a huge cave with wooden docks. Cross the docks to the pirate ship."] = "Folge dem Tunnel in eine riesige Höhle mit Holzstegen. Geh über die Stege zum Piratenschiff.",
	["Follow this build"] = "Diesem Build folgen",
	["Following"] = "Aktiv",
	["Food and drink"] = "Essen und Trinken",
	["Food, drink, bandages and what your abilities use up."] = "Essen, Trinken, Verbände und was deine Fähigkeiten verbrauchen.",
	["For Great Honor: more honor"] = "Große Ehre: mehr Ehre",
	["For my level"] = "Für meine Stufe",
	["For one player"] = "Für einen Spieler",
	["Forever's own progress for your whole account. Earn points, spend them on perks."] = "Forevers eigener Fortschritt für deinen ganzen Account. Verdiene Punkte und gib sie für Vorteile aus.",
	["Forever's systems"] = "Forevers Systeme",
	["Forget"] = "Vergessen",
	["Forget all"] = "Alle vergessen",
	["Found places"] = "Gefundene Orte",
	["Four wings behind one door: Graveyard, Library, Armory and Cathedral, each for higher levels (30 to 46 in all). Seven bosses in all."] = "Vier Flügel hinter einer Tür: Friedhof, Bibliothek, Waffenkammer und Kathedrale, jeder für höhere Stufen (insgesamt 30 bis 46). Insgesamt sieben Bosse.",
	["Frequent Flier: cheaper, faster flights"] = "Vielflieger: günstigere, schnellere Flüge",
	["Friendly"] = "Freundlich",
	["From level %d you can learn to ride. Your own race's riding trainer teaches it for %s, with a mount vendor beside them, and a mount makes you %d%% faster. At level %d a second lesson for %s makes that %d%%. Prices are as reported at launch."] = "Ab Stufe %d kannst du Reiten lernen. Der Reitlehrer deines Volkes bringt es dir für %s bei, gleich neben einem Reittierhändler, und ein Reittier macht dich %d%% schneller. Ab Stufe %d macht eine zweite Lektion für %s daraus %d%%. Preise wie zum Start berichtet.",
	["From level %d. See the Mount topic."] = "Ab Stufe %d. Siehe Thema Reittier.",
	["From the built-in list"] = "Aus der eingebauten Liste",
	["From the cave, climb a hill toward the main ruins. Light enemies come first."] = "Steig von der Höhle einen Hügel hinauf zu den Hauptruinen. Zuerst kommen leichte Gegner.",
	["From the dig site, go south through spiders to the Site of the Guardian."] = "Geh von der Ausgrabungsstätte nach Süden durch die Spinnen zur Stätte des Wächters.",
	["From the entrance slope, walk into the Lost Marsh."] = "Geh vom Hang am Eingang in den Verlorenen Marsch.",
	["From the entrance, clear the ghosts and take the west corridor."] = "Besiege vom Eingang aus die Geister und nimm den Westgang.",
	["From the entrance, follow the tunnels. The path is mostly one way."] = "Folge vom Eingang aus den Tunneln. Der Weg führt meist nur in eine Richtung.",
	["From the entrance, head into the city and take the left-hand paths first."] = "Geh vom Eingang in die Stadt und nimm zuerst die linken Wege.",
	["From the game's flight map"] = "Aus der Flugkarte des Spiels",
	["From your class trainer"] = "Von deinem Klassenlehrer",
	["Frost Nova is ready again sooner, so you can freeze enemies in place more often."] = "Frostnova ist früher wieder bereit, so kannst du Gegner öfter festfrieren.",
	["Frost damage slows him."] = "Frostschaden verlangsamt ihn.",
	["Frost spells cost less mana, so you can cast more before you drink."] = "Frostzauber kosten weniger Mana, so kannst du mehr zaubern, bevor du trinken musst.",
	["Frostbolt from range, with ice to slow enemies and Ice Barrier at level 40 to soak hits. A few Arcane talents at the end save mana."] = "Frostblitz aus der Ferne, mit Eis, das Gegner verlangsamt, und Eisbarriere ab Stufe 40, die Treffer abfängt. Ein paar Arkantalente am Ende sparen Mana.",
	["Frostbolt, your main spell, takes less time to cast."] = "Frostblitz, dein Hauptzauber, ist schneller gewirkt.",
	["Further along the main path of the bigger side."] = "Weiter auf dem Hauptweg der größeren Seite.",
	["Further along the orange side."] = "Weiter auf der orangen Seite.",
	["Further in, in the egg room."] = "Weiter drinnen, im Eierraum.",
	["Further in, in the glowing, dirty part of the old city."] = "Weiter drinnen, im leuchtenden, verschmutzten Teil der alten Stadt.",
	["Further in."] = "Weiter drinnen.",
	["Further in. Many groups skip him."] = "Weiter drinnen. Viele Gruppen lassen ihn aus.",
	["Further west, in a nook at the Magus Commerce Exchange."] = "Weiter westlich, in einer Nische beim Magus Commerce Exchange.",
	["Game Menu > Edit Mode"] = "Spielmenü > Bearbeitungsmodus",
	["Game Menu, Edit Mode: move the bars, the minimap and chat"] = "Spielmenü, Bearbeitungsmodus: Leisten, Minikarte und Chat verschieben",
	["Game check"] = "Spielprüfung",
	["Game check finished. Type /reload so the results are saved."] = "Spielprüfung fertig. Gib /reload ein, damit die Ergebnisse gespeichert werden.",
	["Game options that make a first character easier to play, one click each."] = "Spieloptionen, die einen ersten Charakter leichter spielbar machen, je ein Klick.",
	["Gameplay"] = "Gameplay",
	["Gear"] = "Ausrüstung",
	["Gear %d%%"] = "Ausrüstung %d%%",
	["Gear nearly broken."] = "Ausrüstung fast kaputt.",
	["General: talk to everyone in the area."] = "Allgemein: sprich mit allen im Gebiet.",
	["Ghost Wolf, your run-fast form, casts faster and works indoors."] = "Geisterwolf, deine Laufgestalt, wird schneller gewirkt und funktioniert auch in Gebäuden.",
	["Gives you a little protection against spells, and some mana back."] = "Gibt dir etwas Schutz vor Zaubern und etwas Mana zurück.",
	["Gives you more Armor, based on your Intellect."] = "Gibt dir mehr Rüstung, abhängig von deiner Intelligenz.",
	["Go back to the ramp and follow it up and around into a big cave with many crossing paths."] = "Geh zurück zur Rampe und folge ihr hinauf und herum in eine große Höhle mit vielen sich kreuzenden Wegen.",
	["Go back to the split and take the left path with purple crystals."] = "Geh zurück zur Abzweigung und nimm den linken Weg mit den violetten Kristallen.",
	["Go down the stairs heading east into the first area."] = "Geh die Treppe nach Osten hinunter in den ersten Bereich.",
	["Go down to the Barov Family Vault with its six rooms."] = "Geh hinunter zum Barov Family Vault mit seinen sechs Räumen.",
	["Go forward into the graveyard and on to a burned house with a fireplace."] = "Geh weiter auf den Friedhof und bis zu einem abgebrannten Haus mit Kamin.",
	["Go in and fight the first bug packs."] = "Geh hinein und bekämpfe die ersten Insektengruppen.",
	["Go in from the Blackrock Depths side and follow the lava tunnel to the first boss."] = "Geh von der Seite der Blackrocktiefen hinein und folge dem Lavatunnel zum ersten Boss.",
	["Go in through the cave and follow the winding path uphill between rough buildings."] = "Geh durch die Höhle hinein und folge dem gewundenen Weg bergauf zwischen groben Bauten.",
	["Go in through the portal and enter the temple's first level."] = "Geh durch das Portal und betritt die erste Ebene des Tempels.",
	["Go into Blackrock Mountain, climb down the big chain, go through Forgewright's Tomb and down another chain, then through the Grinding Quarry. Go left to the Masonry. The portal is in the far corner."] = "Geh in den Blackrock, klettere die große Kette hinunter, geh durch Forgewright's Tomb und eine weitere Kette hinunter, dann durch den Grinding Quarry. Geh links zur Masonry. Das Portal ist in der hintersten Ecke.",
	["Go on to the Dark Iron Highway. The gates need a Shadowforge Key or a rogue with lockpicking."] = "Geh weiter zum Dark Iron Highway. Für die Tore braucht ihr einen Shadowforge Key oder einen Schurken mit Schlossknacken.",
	["Go on to the Lost Dig Site where the orcs work. Do not pull too many at once."] = "Geh weiter zur Vergessenen Ausgrabungsstätte, wo die Orcs arbeiten. Zieh nicht zu viele auf einmal.",
	["Go straight ahead from the entrance. The jail is shaped like a T: you can clear the left and right wings in any order."] = "Geh vom Eingang geradeaus. Das Gefängnis hat die Form eines T: Du kannst den linken und rechten Flügel in beliebiger Reihenfolge säubern.",
	["Go through Upper Blackrock Spire to the raid door. You need an attunement quest to enter."] = "Geh durch die Obere Blackrockspitze zur Schlachtzugstür. Zum Betreten brauchst du eine Zugangsquest.",
	["Go through the main gate into the living part. Fight across the market and the streets."] = "Geh durch das Haupttor in den belebten Teil. Kämpf dich über den Markt und durch die Straßen.",
	["Go to the Cleft of Shadow, the cave in the middle of Orgrimmar, and follow the path down. The way in is at the bottom."] = "Geh zur Kluft der Schatten, der Höhle mitten in Orgrimmar, und folge dem Weg hinunter. Der Eingang ist ganz unten.",
	["Go to the flight master in %s"] = "Geh zum Flugmeister in %s",
	["Go up the stairs to the ring round the top. Six troll mini bosses stand on platforms around it. All six must die before the Prophet can be reached."] = "Geh die Treppe hinauf zum Ring ganz oben. Sechs Troll-Minibosse stehen auf Plattformen darum herum. Alle sechs müssen sterben, bevor ihr den Propheten erreichen könnt.",
	["Gold and more"] = "Gold und mehr",
	["Gold on all of them: %s"] = "Gold aller Charaktere: %s",
	["Gold pays for new abilities, repairs, riding and gear. You earn it from quests, from selling things and from what enemies drop."] = "Mit Gold bezahlst du neue Fähigkeiten, Reparaturen, Reiten und Ausrüstung. Du verdienst es mit Quests, durch Verkäufe und durch das, was Gegner fallen lassen.",
	["Gold: much tougher, best with a group. Silver: rare, better loot."] = "Gold: viel stärker, am besten mit einer Gruppe. Silber: rar, bessere Beute.",
	["Good at"] = "Gut in",
	["Good places to start"] = "Gute Orte für den Anfang",
	["Gourmand: food effects last longer"] = "Gourmand: Essenseffekte halten länger",
	["Graveyard wing, levels 30 to 38. Its portal is the one on the far left as you walk in. No key needed."] = "Flügel Friedhof, Stufe 30 bis 38. Sein Portal ist beim Hineingehen ganz links. Kein Schlüssel nötig.",
	["Green or grey"] = "Grün oder grau",
	["Grey items are junk and safe to sell to any vendor. Bags fill up fast, so sell often."] = "Graue Gegenstände sind Plunder und können bedenkenlos an jeden Händler verkauft werden. Taschen füllen sich schnell, also verkauf oft.",
	["Grey items are junk. Selling them is safe."] = "Graue Gegenstände sind Plunder. Du kannst sie bedenkenlos verkaufen.",
	["Grey items sell to any vendor. Keep what you can use."] = "Graue Gegenstände kauft jeder Händler. Behalte, was du nutzen kannst.",
	["Group"] = "Gruppe",
	["Grouping"] = "Gruppenspiel",
	["Groups"] = "Gruppen",
	["Guide"] = "Ratgeber",
	["Hammer of Justice stuns an enemy that is hitting your friend."] = "Hammer der Gerechtigkeit betäubt einen Gegner, der deinen Verbündeten angreift.",
	["Hammer of Justice, a stun, is ready again sooner."] = "Hammer der Gerechtigkeit, eine Betäubung, ist früher wieder bereit.",
	["Handle the skeletons he calls."] = "Kümmert euch um die Skelette, die er ruft.",
	["Hands"] = "Hände",
	["Hardcore"] = "Hardcore",
	["Hated"] = "Hasserfüllt",
	["He burns anyone close."] = "Er verbrennt alle in seiner Nähe.",
	["He calls a stone monster. Kill the seer helper first, and mark the targets."] = "Er ruft ein Steinmonster. Töte zuerst den Seher-Helfer und markiere die Ziele.",
	["He calls four wolves at 80% health. Be ready to pick them up, then kill them."] = "Sobald seine Gesundheit auf 80% herabsinkt, ruft er vier Wölfe. Sei bereit, sie abzufangen, und töte sie dann.",
	["He calls helpers, and again at half health. Focus him, not the helpers. He is the last boss."] = "Er ruft Helfer, und bei halber Gesundheit noch einmal. Konzentriert euch auf ihn, nicht auf die Helfer. Er ist der letzte Boss.",
	["He can put people to sleep. Have someone ready to remove it, especially from the tank."] = "Er kann Spieler einschlafen lassen. Jemand sollte bereit sein, das zu entfernen, besonders beim Tank.",
	["He can take over a player's mind. Be ready to swap tank or healer."] = "Er kann den Geist eines Spielers übernehmen. Seid bereit, Tank oder Heiler zu wechseln.",
	["He casts a big blast. Step away when he starts. A chest behind him holds the Scarlet Key."] = "Er wirkt eine große Explosion. Geh weg, wenn er damit beginnt. Eine Truhe hinter ihm enthält den Scarlet Key.",
	["He casts fire. Kill him quickly. Rare bosses can also show up in this wing."] = "Er wirkt Feuer. Töte ihn schnell. In diesem Flügel können auch rare Bosse auftauchen.",
	["He drops a wand that casters like. Interrupt his cooking, which heals him."] = "Er lässt einen Zauberstab fallen, den Zauberwirker mögen. Unterbrich sein Kochen, es heilt ihn.",
	["He drops the Shaft of Tsol, needed for Ironaya."] = "Er lässt den Shaft of Tsol fallen, den ihr für Ironaya braucht.",
	["He gives the tank a heavy bleed. Cure it if you can."] = "Er belegt den Tank mit starker Blutung. Heile sie, wenn du kannst.",
	["He has no helpers, but he hits hard. Use defences and save mana."] = "Er hat keine Helfer, schlägt aber hart zu. Nutzt Verteidigungsfähigkeiten und spart Mana.",
	["He has two helpers and a poison. Kill the helpers first and cure the poison. He is the last boss."] = "Er hat zwei Helfer und ein Gift. Tötet zuerst die Helfer und heilt das Gift. Er ist der letzte Boss.",
	["He has two helpers. Kill them first, and fight in his room so other monsters stay away."] = "Er hat zwei Helfer. Tötet sie zuerst und kämpft in seinem Raum, damit andere Monster wegbleiben.",
	["He has two helpers. Kill them first, and interrupt his fire spell if you can."] = "Er hat zwei Helfer. Tötet sie zuerst und unterbrecht seinen Feuerzauber, wenn ihr könnt.",
	["He heals himself. Keep up the damage."] = "Er heilt sich selbst. Macht weiter Schaden.",
	["He hits everyone close to him. Kill the guards with him first."] = "Er trifft alle in seiner Nähe. Tötet zuerst die Wachen bei ihm.",
	["He is a caster. Pull him back from other monsters so the group is not hit from two sides."] = "Er ist ein Zauberwirker. Zieht ihn von anderen Monstern weg, damit die Gruppe nicht von zwei Seiten angegriffen wird.",
	["He is strong. Stay near the tank."] = "Er ist stark. Bleib in der Nähe des Tanks.",
	["He is the first boss on the East list. Ask your group about the Crescent Key."] = "Er ist der erste Boss der Liste für Ost. Frag deine Gruppe nach dem Crescent Key.",
	["He is the last boss of the dungeon."] = "Er ist der letzte Boss des Dungeons.",
	["He jumps to random players. Cure his curse."] = "Er springt zu zufälligen Spielern. Entfernt seinen Fluch.",
	["He keeps summoning spirit boars. Kill them as they come."] = "Er beschwört ständig Geistereber. Tötet sie, sobald sie kommen.",
	["He may stand off the main road, with wolves."] = "Er steht manchmal abseits der Hauptstraße, mit Wölfen.",
	["He rises from the water in the final room after the Disciple's ritual."] = "Er steigt im letzten Raum nach dem Ritual des Jüngers aus dem Wasser.",
	["He sends people to side rooms. Kill the helpers and come back."] = "Er schickt Spieler in Nebenräume. Tötet die Helfer und kommt zurück.",
	["He splits into copies. Kill the real one."] = "Er teilt sich in Kopien auf. Tötet den echten.",
	["He summons helpers and tries to control players."] = "Er beschwört Helfer und versucht, Spieler zu kontrollieren.",
	["He takes control of a player. Heal them and stop damage to them."] = "Er übernimmt die Kontrolle über einen Spieler. Heilt ihn und hört auf, ihm Schaden zuzufügen.",
	["He wakes stone helpers during the fight. They fall when he dies, so keep the damage on him."] = "Er erweckt während des Kampfes steinerne Helfer. Sie fallen, wenn er stirbt, also bleibt mit dem Schaden auf ihm.",
	["He wanders the stream and is often skipped. A plain fight if you want him."] = "Er wandert am Bach entlang und wird oft ausgelassen. Ein einfacher Kampf, wenn ihr ihn wollt.",
	["Head"] = "Kopf",
	["Head south along the left wall and turn right past the three ghost citizens."] = "Geh an der linken Wand entlang nach Süden und bieg hinter den drei Geisterbürgern rechts ab.",
	["Heal and Greater Heal cast faster, so hurt allies get help sooner."] = "Heilen und Große Heilung werden schneller gewirkt, so bekommen verletzte Verbündete früher Hilfe.",
	["Heal the tank through the curse."] = "Heilt den Tank, solange der Fluch wirkt.",
	["Heal your group with Holy Light and Flash of Light. You also wear heavy armor, so you can take a hit if an enemy gets to you."] = "Heile deine Gruppe mit Heiliges Licht und Lichtblitz. Du trägst außerdem schwere Rüstung und hältst also einen Treffer aus, wenn ein Gegner zu dir durchkommt.",
	["Heal, Greater Heal and Prayer of Mending cost less mana."] = "Heilen, Große Heilung und Gebet der Besserung kosten weniger Mana.",
	["Healer"] = "Heiler",
	["Healers should watch for raptor bleeds."] = "Heiler sollten auf Blutungen durch Raptoren achten.",
	["Healing Touch and Tranquility cost less Mana."] = "Heilende Berührung und Gelassenheit kosten weniger Mana.",
	["Healing Touch casts faster, and it opens Nature's Swiftness."] = "Heilende Berührung wird schneller gewirkt, und es schaltet Schnelligkeit der Natur frei.",
	["Healing Wave casts faster, so you can heal yourself sooner."] = "Welle der Heilung wird schneller gewirkt, so kannst du dich früher heilen.",
	["Healing Wave casts faster, so your big heal lands sooner."] = "Welle der Heilung wird schneller gewirkt, so kommt deine große Heilung früher an.",
	["Healing Wave heals more."] = "Welle der Heilung heilt mehr.",
	["Healing spells cost less mana and you miss less often."] = "Heilzauber kosten weniger Mana, und du verfehlst seltener.",
	["Healing spells cost less mana, so you can heal for longer."] = "Heilzauber kosten weniger Mana, so kannst du länger heilen.",
	["Heals the group, or casts shadow spells."] = "Heilt die Gruppe oder wirkt Schattenzauber.",
	["Heals you a little after a heavy hit."] = "Heilt dich nach einem schweren Treffer ein wenig.",
	["Heals your party from your Shadow damage, and it opens Shadowform."] = "Heilt deine Gruppe durch deinen Schattenschaden, und es schaltet Schattengestalt frei.",
	["Heals your target and the party members near them over a short time."] = "Heilt dein Ziel und Gruppenmitglieder in seiner Nähe über kurze Zeit.",
	["Health low? Cast Holy Light between fights, or Flash of Light in a pinch."] = "Wenig Gesundheit? Wirk zwischen Kämpfen Heiliges Licht, im Notfall Lichtblitz.",
	["Health low? Step back and cast Healing Wave on yourself."] = "Wenig Gesundheit? Geh zurück und wirk Welle der Heilung auf dich.",
	["Hearth"] = "Ruhestein",
	["Hearthstone"] = "Ruhestein",
	["Help and data"] = "Hilfe und Daten",
	["Helps you start strong when you change into Bear Form or Cat Form."] = "Hilft dir, stark loszulegen, wenn du die Bärengestalt oder Katzengestalt annimmst.",
	["Her bite is poison. Bring a cure if you can."] = "Ihr Biss ist giftig. Bring wenn möglich ein Gegengift mit.",
	["Her shield blocks spells. Use weapons or wait."] = "Ihr Schild blockt Zauber. Nimm Waffen oder warte ab.",
	["Heroic Strike costs less Rage."] = "Heldenhafter Stoß kostet weniger Wut.",
	["Hide behind an ice block when he casts."] = "Versteck dich hinter einem Eisblock, wenn er zaubert.",
	["Hide in combat"] = "Im Kampf ausblenden",
	["High"] = "Hoch",
	["High Alert: notice hidden enemies sooner"] = "Höchste Alarmstufe: verborgene Feinde früher bemerken",
	["His curse slows the tank. Remove it if you can."] = "Sein Fluch verlangsamt den Tank. Entferne ihn, wenn du kannst.",
	["His fire spell makes fire hit harder. Remove it if you can."] = "Sein Feuerzauber verstärkt Feuerschaden. Entferne ihn, wenn du kannst.",
	["His shield bash often stuns. Strong Defias guards nearby may join in."] = "Sein Schildhieb betäubt oft. Starke Defias-Wachen in der Nähe können dazukommen.",
	["His shout can pull people out of healing range. Stay close to the healer."] = "Sein Ruf kann Spieler aus der Heilreichweite ziehen. Bleib nah beim Heiler.",
	["His uppercut throws you back. Do not stand near the lava edge. Patrols can join in."] = "Sein Aufwärtshaken schleudert dich zurück. Stell dich nicht an den Lavarand. Patrouillen können dazukommen.",
	["His vines root everyone near him. Stand well back, and keep the tank healed."] = "Seine Ranken wurzeln alle in seiner Nähe fest. Halte viel Abstand und heile den Tank.",
	["Hits from a distance and fights beside a pet."] = "Greift aus der Ferne an und kämpft mit einem Tier an der Seite.",
	["Hitting an enemy that has your Rend on it can make Overpower usable."] = "Triffst du einen Feind mit deinem Verwunden, kann Überwältigen nutzbar werden.",
	["Hold Mind Flay between Mind Blasts. It also slows the enemy so it reaches you later."] = "Nutze Gedankenschinden zwischen den Gedankenschlägen. Es verlangsamt den Feind auch, sodass er dich später erreicht.",
	["Hold the enemies' attention in a dungeon with a shield and Righteous Fury, and take hits while your group does the damage."] = "Halte im Dungeon mit Schild und Zorn der Gerechtigkeit die Aufmerksamkeit der Feinde und steck Treffer ein, während deine Gruppe Schaden macht.",
	["Hold the enemies' attention in a dungeon with a shield, and take the hits while your group does the damage."] = "Halte im Dungeon mit einem Schild die Aufmerksamkeit der Feinde und steck die Treffer ein, während deine Gruppe Schaden macht.",
	["Holds one Humanoid enemy still until you hit it, and it opens Unsealed Wrath."] = "Hält einen humanoiden Feind fest, bis du ihn triffst, und schaltet Entfesselter Zorn frei.",
	["Holy Light and Flash of Light heal for more, so you can heal yourself."] = "Heiliges Licht und Lichtblitz heilen mehr, damit du dich selbst heilen kannst.",
	["Holy Light and Flash of Light heal you for more."] = "Heiliges Licht und Lichtblitz heilen dich stärker.",
	["Holy Light, Flash of Light and Holy Shock heal for more."] = "Heiliges Licht, Lichtblitz und Heiliger Schock heilen mehr.",
	["Holy Shield makes you block much more for a while. Use it before a hard hit."] = "Heiliger Schild lässt dich eine Weile viel öfter blocken. Nutze ihn vor einem harten Treffer.",
	["Holy Shock gets more critical heals on friends who do not have your Oath."] = "Heiliger Schock heilt Verbündete ohne deinen Oath öfter kritisch.",
	["Holy Shock heals a friend, or hurts an enemy. Use it whenever it is ready."] = "Heiliger Schock heilt einen Verbündeten oder verletzt einen Feind. Nutze ihn, sobald er bereit ist.",
	["Holy Strike hits harder and keeps your Judgements on the enemy fresh."] = "Heiliger Stoß trifft härter und frischt deine Richturteile auf dem Feind auf.",
	["Holy Strike is ready sooner, and works with your Holy Shield."] = "Heiliger Stoß ist schneller bereit und wirkt mit deinem Heiligen Schild zusammen.",
	["Holy Strike keeps more enemy attention on you, and with Righteous Fury it cuts damage you take."] = "Heiliger Stoß zieht mehr Aufmerksamkeit der Feinde auf dich und senkt mit Zorn der Gerechtigkeit deinen erlittenen Schaden.",
	["Home"] = "Zuhause",
	["Home: %s"] = "Heimatort: %s",
	["Home: %s. %s"] = "Heimatort: %s. %s",
	["Home: not set"] = "Heimatort: nicht gesetzt",
	["Honored"] = "Wohlwollend",
	["Horde players can enter too, but its quests are for the Alliance."] = "Hordespieler können auch hinein, aber die Quests dort sind für die Allianz.",
	["Hostile"] = "Feindselig",
	["How to get there"] = "So kommst du hin",
	["Hunters keep their spare pets here."] = "Jäger lassen hier ihre übrigen Tiere.",
	["Hurt after a fight? Rest and let your health and mana fill up before the next one."] = "Verletzt nach einem Kampf? Ruh dich aus und lass Gesundheit und Mana auffüllen, bevor du weiterkämpfst.",
	["Hurt badly? Swiftmend heals you at once if you have Rejuvenation or Regrowth on you."] = "Schwer verletzt? Rasche Heilung heilt dich sofort, wenn Verjüngung oder Nachwachsen auf dir liegt.",
	["Hurts an enemy or heals a friend."] = "Verletzt einen Feind oder heilt einen Verbündeten.",
	["Hyjal Summit"] = "",
	["Ice Lance hits much harder on a frozen enemy. Cast it right after Frost Nova."] = "Eislanze trifft einen eingefrorenen Feind viel härter. Wirke sie direkt nach Frostnova.",
	["If a fight goes badly, run toward a town or a guard. Your ruleset decides who can attack you: PvE only when you choose, PvP almost always."] = "Läuft ein Kampf schlecht, renn zu einer Stadt oder einer Wache. Dein Regelwerk bestimmt, wer dich angreifen kann: bei PvE nur wenn du willst, bei PvP fast immer.",
	["If he is not there, just walk on."] = "Ist er nicht da, geh einfach weiter.",
	["If the flight master does not list it, you have not found it yet. Fly as close as you can."] = "Zeigt der Flugmeister ihn nicht an, hast du ihn noch nicht entdeckt. Flieg so nah wie möglich heran.",
	["If you die you can still heal for a short time, and it opens Prayer of Mending."] = "Wenn du stirbst, kannst du noch kurz weiterheilen, und es schaltet Gebet der Besserung frei.",
	["If you die: release, run back to your body, and come back to life in a safe spot. Use the Spirit Healer only when you cannot reach your body."] = "Wenn du stirbst: Geist freilassen, zur Leiche zurücklaufen und an einer sicheren Stelle wiederbeleben. Nutze den Geistheiler nur, wenn du deine Leiche nicht erreichst.",
	["In %s"] = "In %s",
	["In Bear Form use Lacerate again and again so the bleed grows."] = "Nutze in Bärengestalt immer wieder Aufschlitzen, damit die Blutung wächst.",
	["In Feralas, in the ruins. The East door needs no key. West and North need the Crescent Key, which comes from the East part."] = "In Feralas, in den Ruinen. Die Osttür braucht keinen Schlüssel. West und Nord brauchen den Mondsichelschlüssel, den es im Ostteil gibt.",
	["In Ironforge, go to the king's hall and turn left to a web-covered passage. Follow it down. Do not fall off the edge."] = "Geh in Ironforge zur Halle des Königs und biege links in einen Gang voller Spinnweben ab. Folge ihm nach unten. Fall nicht über die Kante.",
	["In Silverpine Forest, in the mountains just north of Pyrewood Village, walk up to the big keep gate."] = "Geh im Silberwald, in den Bergen knapp nördlich von Pyrewood, zum großen Burgtor hinauf.",
	["In Stalker's Thicket, with two helper hunters. Some raptors are hidden."] = "Im Pirscherdickicht, mit zwei Jägern als Helfern. Einige Raptoren sind versteckt.",
	["In Stormwind City, go to the canals near the Mage Quarter. The gate to the Stockade is on the water's edge."] = "Geh in Sturmwind zu den Kanälen beim Magierviertel. Das Tor zum Verlies liegt direkt am Wasser.",
	["In Tirisfal Glades, at the Undercity gate. Reports say the stairs are on the left before the keep."] = "In Tirisfal, am Tor von Undercity. Berichten zufolge ist die Treppe links vor der Burg.",
	["In Westfall, in the town of Moonbrook, go into the big Defias Hideout building in the south-west corner. Follow the cave maze down to the bottom."] = "Geh in Westfall im Ort Moonbrook in das große Gebäude des Defias-Verstecks in der Südwestecke. Folge dem Höhlenlabyrinth ganz nach unten.",
	["In a cave in the hills of Dustwallow Marsh. You need an attunement quest to enter."] = "In einer Höhle in den Hügeln der Marschen von Dustwallow. Für den Zugang brauchst du eine Einstimmungsquest.",
	["In a fight"] = "Im Kampf",
	["In a frozen lair at the back of the fortress."] = "In einem gefrorenen Hort hinten in der Festung.",
	["In a party of %d"] = "In einer %der-Gruppe",
	["In a raid of %d"] = "In einem %der-Schlachtzug",
	["In a room of the keep that is packed with monsters."] = "In einem Raum der Burg voller Monster.",
	["In a room of the main keep, full of guards."] = "In einem Raum der Hauptburg voller Wachen.",
	["In a room past Theka. He looks friendly until you step in."] = "In einem Raum hinter Theka. Er wirkt freundlich, bis du eintrittst.",
	["In a side hall."] = "In einer Seitenhalle.",
	["In a small room at the end of the right-hand side path, soon after the first ramp."] = "In einem kleinen Raum am Ende des rechten Seitenwegs, kurz nach der ersten Rampe.",
	["In an emergency, Nature's Swiftness makes your next heal instant."] = "Im Notfall macht Schnelligkeit der Natur deine nächste Heilung sofort.",
	["In an inn or a city: your rest is building up"] = "Im Gasthaus oder in einer Stadt: Du sammelst Erholung",
	["In hand"] = "Vorhanden",
	["In hand, low"] = "Vorhanden, knapp",
	["In his arena to the west, past the ghost citizens."] = "In seiner Arena im Westen, hinter den geisterhaften Bürgern.",
	["In his own room. Guides call him the last boss."] = "In seinem eigenen Raum. Guides nennen ihn den letzten Boss.",
	["In his tent, the last stop in the dungeon."] = "In seinem Zelt, der letzten Station im Dungeon.",
	["In his workshop, inside a big machine called the Shredder."] = "In seiner Werkstatt, in einer großen Maschine namens Shredder.",
	["In one of the two cell wings."] = "In einem der beiden Zellenflügel.",
	["In real danger, use Lay on Hands, a big heal you can only use now and then."] = "In echter Gefahr nutze Handauflegung, eine große Heilung, die du nur ab und zu einsetzen kannst.",
	["In the Alchemy Lab."] = "Im Alchemielabor.",
	["In the Barov Family Vault, once the six rooms are cleared."] = "In der Barov Family Vault, sobald die sechs Räume geräumt sind.",
	["In the Black Vault, with his hound."] = "Im Black Vault, mit seinem Hund.",
	["In the Black Vault. Opening all twelve relic coffer doors brings out this fight."] = "Im Black Vault. Öffnest du alle zwölf Reliktschatullen-Türen, beginnt dieser Kampf.",
	["In the Capital Gardens, a walking tree."] = "In den Capital Gardens, ein wandelnder Baum.",
	["In the Cathedral wing, in the first part."] = "Im Kathedralenflügel, im ersten Teil.",
	["In the Chamber of Enchantment."] = "In der Chamber of Enchantment.",
	["In the Construct Wing."] = "Im Konstruktviertel.",
	["In the Crimson buildings of the Living part."] = "In den purpurnen Gebäuden des lebenden Teils.",
	["In the East part."] = "Im Ostteil.",
	["In the Graveyard wing, near the start."] = "Im Friedhofsflügel, nahe dem Anfang.",
	["In the Grim Guzzler, the dwarf bar. He fights if you threaten him in talk."] = "Im Grimmigen Säufer, der Zwergenkneipe. Er kämpft, wenn du ihm im Gespräch drohst.",
	["In the Imperial Seat, with the Emperor."] = "Im Imperial Seat, beim Imperator.",
	["In the Lair of the Chosen, after the six troll mini bosses are dead. Ogom the Wretched stands with him."] = "Im Lair of the Chosen, nachdem die sechs Troll-Minibosse tot sind. Ogom the Wretched steht bei ihm.",
	["In the Library wing, with his dogs."] = "Im Bibliotheksflügel, mit seinen Hunden.",
	["In the Living part. Mostly wanted for a smithing quest."] = "Im lebenden Teil. Meist für eine Schmiedequest gesucht.",
	["In the Lushwater Oasis, in the middle of The Barrens, find the cave called the Cavern of Mists. Follow the winding tunnel down to a big pool."] = "Such in der Blühenden Oase mitten im Brachland die Höhle namens Cavern of Mists. Folge dem gewundenen Tunnel hinab zu einem großen Becken.",
	["In the Manufactory, the machine hall."] = "In der Manufaktur, der Maschinenhalle.",
	["In the Military Wing."] = "Im Militärviertel.",
	["In the North part, a drunk ogre at a table."] = "Im Nordteil, ein betrunkener Oger an einem Tisch.",
	["In the North part, by the throne room."] = "Im Nordteil, beim Thronsaal.",
	["In the North part, near the throne room."] = "Im Nordteil, nahe dem Thronsaal.",
	["In the North part."] = "Im Nordteil.",
	["In the Pit of Refuse, to the right of the portal. Click the six shrines in the right order to wake him."] = "In der Pit of Refuse, rechts vom Portal. Klick die sechs Schreine in der richtigen Reihenfolge an, um ihn zu wecken.",
	["In the Plague Wing."] = "Im Seuchenviertel.",
	["In the Reliquary of Kings, the room across the north bridge."] = "Im Reliquary of Kings, dem Raum hinter der Nordbrücke.",
	["In the Riverglades, a cave to the west of the big fortress gates, near a meeting stone."] = "In den Flusslanden, eine Höhle westlich der großen Festungstore, nahe einem Versammlungsstein.",
	["In the Slaughterhouse at the end of the living part."] = "Im Schlachthof am Ende des lebenden Teils.",
	["In the Spider Wing."] = "Im Spinnenviertel.",
	["In the Summoners' Tomb: seven dwarf spirits, one after another."] = "Im Summoners' Tomb: sieben Zwergengeister, einer nach dem anderen.",
	["In the Undead part."] = "Im untoten Teil.",
	["In the Viewing Room. A party member needs a related quest to start him."] = "Im Viewing Room. Ein Gruppenmitglied braucht eine passende Quest, um ihn zu starten.",
	["In the Violet Chamber. Talk to Archmage Modera on the Violet Citadel steps to go in."] = "In der Violet Chamber. Sprich auf den Stufen der Violet Citadel mit Archmage Modera, um hineinzukommen.",
	["In the Violet Hold, to the left in the streets."] = "In der Violet Hold, links in den Straßen.",
	["In the West Garrison."] = "In der Westgarnison.",
	["In the West part."] = "Im Westteil.",
	["In the Wetlands, take the winding path left of Thelgen Rock. The entrance is a cave at the end."] = "Nimm im Sumpfland den gewundenen Pfad links vom Thelgenfelsen. Der Eingang ist eine Höhle an dessen Ende.",
	["In the air phase, spread out and do not stand together."] = "Verteilt euch in der Luftphase und steht nicht beieinander.",
	["In the area of the dragon bosses."] = "Im Bereich der Drachenbosse.",
	["In the basement of the Great Ossuary."] = "Im Keller des Great Ossuary.",
	["In the big round hall with columns, the last room."] = "In der großen runden Säulenhalle, dem letzten Raum.",
	["In the big tomb room at the end of the west corridor. He patrols the tomb."] = "In der großen Grabkammer am Ende des Westgangs. Er patrouilliert durch das Grab.",
	["In the biggest cave at the end."] = "In der größten Höhle am Ende.",
	["In the cabin at the very top of the ship, past Captain Greenskin."] = "In der Kajüte ganz oben auf dem Schiff, hinter Captain Greenskin.",
	["In the captain's area at the back of the ship."] = "Im Kapitänsbereich hinten auf dem Schiff.",
	["In the cell block, with two guards."] = "Im Zellentrakt, mit zwei Wachen.",
	["In the cell block."] = "Im Zellentrakt.",
	["In the central Runeweaver Square. Speak to Magus Fansy Goodbringer to drop the barrier."] = "Auf dem zentralen Runeweaver Square. Sprich mit Magus Fansy Goodbringer, um die Barriere zu senken.",
	["In the central cave, on a high ledge. She stands at one of several circles."] = "In der mittleren Höhle, auf einem hohen Vorsprung. Sie steht an einem von mehreren Kreisen.",
	["In the ceremonial chamber just before the last room."] = "In der Zeremonienkammer direkt vor dem letzten Raum.",
	["In the courtyard with the pool and the gong, tucked round a corner."] = "Im Hof mit dem Becken und dem Gong, versteckt um eine Ecke.",
	["In the courtyard. Touch the statue with glowing eyes to start waves."] = "Im Hof. Berühre die Statue mit leuchtenden Augen, um die Wellen zu starten.",
	["In the engineering labs."] = "In den Ingenieurslaboren.",
	["In the far south of Silithus, at the big gate to the Ahn'Qiraj temple. Ask the raid leader if the door is open."] = "Im tiefen Süden von Silithus, am großen Tor zum Tempel von Ahn'Qiraj. Frag den Schlachtzugsleiter, ob das Tor offen ist.",
	["In the far south of Silithus, outside the big gate to the Ahn'Qiraj temple. Ask the raid leader if the door is open."] = "Im tiefen Süden von Silithus, vor dem großen Tor zum Tempel von Ahn'Qiraj. Frag den Schlachtzugsleiter, ob das Tor offen ist.",
	["In the far south-west of The Barrens, push through the maze of thorns and quilboar to the portal at its end."] = "Kämpf dich im äußersten Südwesten des Brachlands durch das Labyrinth aus Dornen und Stacheleber bis zum Portal an seinem Ende.",
	["In the first big room, where a gong stands."] = "Im ersten großen Raum, in dem ein Gong steht.",
	["In the flooded tomb under the pool, reached by swimming."] = "Im überfluteten Grab unter dem Becken, schwimmend zu erreichen.",
	["In the garden next to the pylon."] = "Im Garten neben dem Pylon.",
	["In the goblin foundry room further along."] = "Weiter hinten im Raum der Goblingießerei.",
	["In the keep, with a swarm of bats."] = "In der Burg, mit einem Schwarm Fledermäuse.",
	["In the last cave. A huge sea creature."] = "In der letzten Höhle. Ein riesiges Meereswesen.",
	["In the last room at the top of the keep, with three worgen."] = "Im letzten Raum oben in der Burg, mit drei Worgen.",
	["In the last room of the Cathedral wing, with Scarlet Commander Mograine."] = "Im letzten Raum des Kathedralenflügels, mit Scarlet Commander Mograine.",
	["In the last room."] = "Im letzten Raum.",
	["In the left-hand wing: climb the winding path up to the Pit of Fangs."] = "Im linken Flügel: Steig den gewundenen Pfad hinauf zur Pit of Fangs.",
	["In the lower rooms of the first part."] = "In den unteren Räumen des ersten Teils.",
	["In the main keep, with helpers around him."] = "In der Hauptburg, mit Helfern um ihn herum.",
	["In the natural cave beyond the tombs, with Dark Iron dwarves around."] = "In der natürlichen Höhle hinter den Gräbern, umgeben von Zwergen der Dunkeleisen.",
	["In the north of Stranglethorn Vale. Walk up the path from the village into the stone gate."] = "Im Norden des Schlingendorntals. Geh den Pfad vom Dorf hinauf durch das Steintor.",
	["In the north of the Badlands, near Loch Modan, find the excavation tunnels and go in. Strong monsters wait in the tunnels."] = "Such im Norden des Ödlands, nahe Loch Modan, die Grabungstunnel und geh hinein. In den Tunneln warten starke Monster.",
	["In the north-east corner of Tirisfal Glades. The four wing portals sit in the main building. The Scarlet Key from the Library opens the Armory and Cathedral; the other two need none."] = "In der Nordostecke von Tirisfal. Die vier Flügelportale liegen im Hauptgebäude. Der Scharlachrote Schlüssel aus der Bibliothek öffnet Waffenkammer und Kathedrale; die anderen zwei brauchen keinen.",
	["In the north-west corner of Ashenvale, at the Zoram Strand, find the sunken ruins. Swim down into the pool at the bottom, then follow the narrow cave."] = "Such in der Nordwestecke von Ashenvale, am Zoram Strand, die versunkenen Ruinen. Tauch in das Becken ganz unten und folge dann der engen Höhle.",
	["In the north-west corner of Tanaris. Walk in through the big gate of the troll city."] = "In der Nordwestecke von Tanaris. Geh durch das große Tor der Trollstadt hinein.",
	["In the north-west of Dun Morogh, take the lift down to the outer tunnels, then walk to the dungeon portal."] = "Nimm im Nordwesten von Dun Morogh den Aufzug hinab zu den äußeren Tunneln und geh dann zum Dungeonportal.",
	["In the panther temple."] = "Im Panthertempel.",
	["In the pool, called out with fishing bait."] = "Im Becken, mit Angelköder hervorgelockt.",
	["In the sewer's Underbelly, past three big pipes, in a summoning circle."] = "Im Underbelly der Kanalisation, hinter drei großen Rohren, in einem Beschwörungskreis.",
	["In the snake temple."] = "Im Schlangentempel.",
	["In the south-east of The Barrens, cross the maze of thorns and quilboar to the portal at its end."] = "Durchquere im Südosten des Brachlands das Labyrinth aus Dornen und Stacheleber bis zum Portal an seinem Ende.",
	["In the southernmost room of the Detention Block. She drops the Prison Cell Key."] = "Im südlichsten Raum des Detention Block. Sie lässt den Gefängniszellenschlüssel fallen.",
	["In the spider temple."] = "Im Spinnentempel.",
	["In the streets of the Living part."] = "In den Straßen des lebenden Teils.",
	["In the tiger temple."] = "Im Tigertempel.",
	["In the water under the last boss's platform."] = "Im Wasser unter der Plattform des letzten Bosses.",
	["In this zone"] = "In diesem Gebiet",
	["Inn"] = "Gasthaus",
	["Inns and rest"] = "Gasthäuser und Erholung",
	["Inside Blackrock Mountain, on its east side. Take the door by the meeting stone and climb the path, or jump down from the balcony where the gnome Bodley stands, which skips the monsters."] = "Im Blackrock, auf seiner Ostseite. Nimm die Tür beim Versammlungsstein und steig den Pfad hinauf, oder spring vom Balkon, auf dem der Gnom Bodley steht, hinunter und überspring so die Monster.",
	["Inside the dungeon, this page ticks off each boss as it falls."] = "Im Dungeon hakt diese Seite jeden Boss ab, sobald er fällt.",
	["Intellect"] = "Intelligenz",
	["Intellect first, as it adds attack power and Mana. Then Stamina. A slow two-handed weapon, or a one-hander and shield, works well."] = "Zuerst Intelligenz, denn sie bringt Angriffskraft und Mana. Dann Ausdauer. Eine langsame Zweihandwaffe oder eine Einhandwaffe mit Schild passt gut.",
	["Intellect first, then Spirit and Stamina. Look for gear that adds healing, in cloth or leather, and a staff or a held item."] = "Zuerst Intelligenz, dann Willenskraft und Ausdauer. Such Ausrüstung mit Heilung aus Stoff oder Leder und einen Stab oder einen Gegenstand für die Schildhand.",
	["Intellect first, then Spirit and Stamina. Use a staff or a wand, and gear that adds Spell Damage."] = "Zuerst Intelligenz, dann Willenskraft und Ausdauer. Nimm einen Stab oder Zauberstab und Ausrüstung mit Zauberschaden.",
	["Intellect first, then Spirit and Stamina. Use a staff, a wand, or a held item that adds healing."] = "Zuerst Intelligenz, dann Willenskraft und Ausdauer. Nimm einen Stab, einen Zauberstab oder einen Gegenstand für die Schildhand mit Heilung.",
	["Intellect first, then Stamina and Spirit. Look for gear that adds healing, and a shield or a held item."] = "Zuerst Intelligenz, dann Ausdauer und Willenskraft. Such Ausrüstung mit Heilung und einen Schild oder einen Gegenstand für die Schildhand.",
	["Intellect first, then Stamina and Spirit. Look for items that add healing."] = "Zuerst Intelligenz, dann Ausdauer und Willenskraft. Such Gegenstände mit Heilung.",
	["Intellect first, then Stamina and Spirit. Use a staff or a wand, and cloth armor."] = "Zuerst Intelligenz, dann Ausdauer und Willenskraft. Nimm einen Stab oder Zauberstab und Stoffrüstung.",
	["Interrupt her hex."] = "Unterbrich ihre Verhexung.",
	["Interrupt her mana burn."] = "Unterbrich ihren Manabrand.",
	["Interrupt her spells."] = "Unterbrich ihre Zauber.",
	["Interrupt his big spells."] = "Unterbrich seine großen Zauber.",
	["Interrupt his healing spell."] = "Unterbrich seinen Heilzauber.",
	["Interrupt his life drain. Three waves come from both sides."] = "Unterbrich seinen Lebensentzug. Drei Wellen kommen von beiden Seiten.",
	["Interrupt his shooting."] = "Unterbrich seine Schüsse.",
	["Interrupt his spells."] = "Unterbrich seine Zauber.",
	["Ironaya wakes only when someone uses two special items. Ask your group."] = "Ironaya erwacht nur, wenn jemand zwei besondere Gegenstände benutzt. Frag deine Gruppe.",
	["Ironforge"] = "",
	["It counts when the raid is done."] = "Zählt, sobald der Schlachtzug geschafft ist.",
	["It is meant for levels %d to %d and gives little experience now."] = "Gedacht für Stufe %d bis %d, gibt dir jetzt kaum noch Erfahrung.",
	["It is meant for levels %d to %d. Monsters here are much stronger than you."] = "Gedacht für Stufe %d bis %d. Die Monster hier sind viel stärker als du.",
	["It learns an entrance the first time one of your characters walks in, and keeps it for all of them. Until then, ask your group to lead the way."] = "Ein Eingang wird gespeichert, sobald einer deiner Charaktere zum ersten Mal hineingeht, und gilt dann für alle. Bis dahin lass dich von deiner Gruppe führen.",
	["It rises as you fight with that kind of weapon."] = "Sie steigt, wenn du mit dieser Waffenart kämpfst.",
	["Items"] = "Gegenstände",
	["Items and enemies"] = "Gegenstände und Feinde",
	["Its sand storm slows and silences. Players who fight from afar and healers should stay far away."] = "Sein Sandsturm verlangsamt und bringt zum Schweigen. Wer aus der Ferne kämpft und wer heilt, sollte weit weg bleiben.",
	["Jobs and finding a group"] = "Berufe und Gruppensuche",
	["Join a party with other players"] = "Tritt einer Gruppe mit anderen Spielern bei",
	["Journal"] = "Tagebuch",
	["Judgement gives back Mana from your Seal, so fights cost you less."] = "Richturteil gibt dir Mana von deinem Siegel zurück, so kosten Kämpfe weniger.",
	["Judgement is ready again sooner, so you use it more often."] = "Richturteil ist schneller wieder bereit, so nutzt du es öfter.",
	["Judgement while Seal of Fury is on makes an enemy attack you. Use it on one hitting a friend."] = "Richturteil mit aktivem Siegel des Furors bringt einen Feind dazu, dich anzugreifen. Nutze es bei einem, der einen Verbündeten schlägt.",
	["Jump down to the cave floor, walk back to the central cave and take the much bigger side on the other hand."] = "Spring hinunter auf den Höhlenboden, geh zurück zur mittleren Höhle und nimm die viel größere Seite gegenüber.",
	["Jump into the pool behind Verdan to drop back to the start area."] = "Spring in das Becken hinter Verdan, um zurück zum Startbereich zu gelangen.",
	["Keep"] = "Behalten",
	["Keep Water Shield on between fights to win mana back."] = "Halte Wasserschild zwischen Kämpfen aktiv, um Mana zurückzugewinnen.",
	["Keep Water Shield on you. It gives mana back as you are hit."] = "Halte Wasserschild auf dir. Es gibt dir Mana zurück, wenn du getroffen wirst.",
	["Keep an eye on your Health. Rejuvenation on yourself between fights saves your healer."] = "Behalte deine Gesundheit im Blick. Verjüngung auf dich selbst zwischen Kämpfen entlastet deinen Heiler.",
	["Keep healing even after the poison hits."] = "Heile weiter, auch wenn das Gift trifft.",
	["Keep his helpers out of the fight (sleep, stun or trap them) and kill him first."] = "Halte seine Helfer aus dem Kampf heraus (einschläfern, betäuben oder in eine Falle locken) und töte ihn zuerst.",
	["Keep monsters off the escort. Only start it if you have the quest."] = "Halte die Monster von der Eskorte fern. Starte sie nur, wenn du die Quest hast.",
	["Keep moving away from an enemy while you hit it."] = "Bewege dich ständig von einem Feind weg, während du ihn triffst.",
	["Keep ranged players and healers out of his dust cloud."] = "Halte Fernkämpfer und Heiler aus seiner Staubwolke heraus.",
	["Keep the tank at full health."] = "Halte den Tank bei voller Gesundheit.",
	["Keep the tank facing him, and everyone else away from the front."] = "Der Tank soll ihn ansehen, alle anderen bleiben weg von seiner Vorderseite.",
	["Keeps a group of five alive with Healing Wave and, later, Chain Heal and Riptide. Stay back, watch health bars and spend mana wisely."] = "Hält eine Fünfergruppe mit Welle der Heilung und später Kettenheilung und Springflut am Leben. Bleib hinten, achte auf die Gesundheitsleisten und geh klug mit Mana um.",
	["Keeps everyone alive."] = "Hält alle am Leben.",
	["Keeps your group alive with healing spells that work over time. Wild Growth, late in the build, heals a whole party."] = "Hält deine Gruppe mit Heilzaubern über Zeit am Leben. Wildwuchs, spät in der Build, heilt eine ganze Gruppe.",
	["Key Bindings"] = "Tastaturbelegung",
	["Kill all but one or two so the last boss does not spawn early."] = "Töte alle bis auf ein oder zwei, damit der letzte Boss nicht zu früh erscheint.",
	["Kill all his friends within a few seconds of each other."] = "Töte alle seine Freunde innerhalb weniger Sekunden.",
	["Kill all three bugs together."] = "Töte alle drei Käfer gleichzeitig.",
	["Kill both of his healers before him."] = "Töte seine beiden Heiler vor ihm.",
	["Kill four Bloodkeepers and use their blood on four braziers to bring him out."] = "Töte vier Bloodkeeper und nutze ihr Blut an vier Kohlenbecken, um ihn herauszulocken.",
	["Kill her bats and avoid the fire."] = "Töte ihre Fledermäuse und meide das Feuer.",
	["Kill her first. Her bird helper comes with her."] = "Töte sie zuerst. Ihr Vogelgehilfe kommt mit ihr.",
	["Kill her followers first."] = "Töte zuerst ihre Anhänger.",
	["Kill her helpers on the ground."] = "Töte ihre Helfer am Boden.",
	["Kill him before his helpers."] = "Töte ihn vor seinen Helfern.",
	["Kill him before more monsters join."] = "Töte ihn, bevor weitere Monster dazukommen.",
	["Kill him fast before he enrages."] = "Töte ihn schnell, bevor er in Raserei gerät.",
	["Kill him fast."] = "Töte ihn schnell.",
	["Kill him first, then the priest. Healers stay far back."] = "Töte zuerst ihn, dann den Priester. Heiler bleiben weit hinten.",
	["Kill him first. His helpers disappear when he dies."] = "Töte ihn zuerst. Seine Helfer verschwinden, wenn er stirbt.",
	["Kill him, not the spirits around him. Killing one makes him call another."] = "Töte ihn, nicht die Geister um ihn herum. Für jeden getöteten ruft er einen neuen.",
	["Kill his fire spirits before they reach him."] = "Töte seine Feuergeister, bevor sie ihn erreichen.",
	["Kill his fire totem when it appears."] = "Zerstöre sein Feuertotem, sobald es erscheint.",
	["Kill his healers first."] = "Töte zuerst seine Heiler.",
	["Kill his helpers first and spread out."] = "Töte zuerst seine Helfer und verteilt euch.",
	["Kill his helpers first: the acolyte, then the big one. Interrupt the acolyte's mana burn."] = "Töte zuerst seine Helfer: den Akolythen, dann den großen. Unterbrich den Manabrand des Akolythen.",
	["Kill his helpers or pull them away."] = "Töte seine Helfer oder zieh sie weg.",
	["Kill his helpers when they rise."] = "Töte seine Helfer, wenn sie sich erheben.",
	["Kill his helpers with attacks that hit many at once."] = "Töte seine Helfer mit Angriffen, die viele auf einmal treffen.",
	["Kill his hound first and use no frost damage on him."] = "Töte zuerst seinen Hund und setz keinen Frostschaden gegen ihn ein.",
	["Kill his plant helpers first."] = "Töte zuerst seine Pflanzenhelfer.",
	["Kill his spiderlings first."] = "Töte zuerst seine Spinnenjungen.",
	["Kill his totem guards quickly."] = "Töte seine Totemwachen schnell.",
	["Kill his two guards first. Interrupt his lightning."] = "Töte zuerst seine zwei Wachen. Unterbrich seine Blitze.",
	["Kill his two hidden guards first. Save your defences for when he pulls out two weapons."] = "Töte zuerst seine zwei versteckten Wachen. Spar dir deine Verteidigung auf, bis er zwei Waffen zieht.",
	["Kill his waves first, then the General."] = "Töte zuerst seine Wellen, dann den General.",
	["Kill or control the guards first."] = "Töte oder kontrolliere zuerst die Wachen.",
	["Kill the bats first. He hits harder as his health drops, so save your big attacks for the end."] = "Töte zuerst die Fledermäuse. Er schlägt härter zu, je weniger Gesundheit er hat, also heb dir deine großen Angriffe fürs Ende auf.",
	["Kill the cubs that run out."] = "Töte die Jungen, die herauslaufen.",
	["Kill the dogs first."] = "Töte zuerst die Hunde.",
	["Kill the dragonkin that rush in."] = "Töte die Drachkin, die hereinstürmen.",
	["Kill the eggs, then the boss."] = "Zerstöre die Eier, dann den Boss.",
	["Kill the eyes quickly. Then fight him inside his stomach."] = "Töte die Augen schnell. Kämpf dann in seinem Magen gegen ihn.",
	["Kill the frost ghosts he calls, then go back to him. He is the last boss."] = "Töte die Frostgeister, die er ruft, und wende dich dann wieder ihm zu. Er ist der letzte Boss.",
	["Kill the guards first. Step away from them when they spin."] = "Töte zuerst die Wachen. Geh von ihnen weg, wenn sie wirbeln.",
	["Kill the guards that rise around you."] = "Töte die Wachen, die sich um dich herum erheben.",
	["Kill the helper hunters first and cure his fear."] = "Töte zuerst die helfenden Jäger und heb seine Furcht auf.",
	["Kill the helpers first."] = "Töte zuerst die Helfer.",
	["Kill the helpers he brings."] = "Töte die Helfer, die er mitbringt.",
	["Kill the high priests first to make him weaker."] = "Töte zuerst die Hohepriester, um ihn zu schwächen.",
	["Kill the hounds around him first."] = "Töte zuerst die Hunde um ihn herum.",
	["Kill the pet first, then Grubbis."] = "Töte zuerst das Tier, dann Grubbis.",
	["Kill the real one, not the copies. Guides call her optional."] = "Töte die echte, nicht die Kopien. Guides nennen sie optional.",
	["Kill the shooters first or they keep hurting you from behind him."] = "Töte zuerst die Schützen, sonst verletzen sie dich weiter von hinter ihm.",
	["Kill the skeletons first, then him. Interrupt his fireball."] = "Töte zuerst die Skelette, dann ihn. Unterbrich seinen Feuerball.",
	["Kill the skeletons he calls."] = "Töte die Skelette, die er ruft.",
	["Kill the small imp first."] = "Töte zuerst den kleinen Wichtel.",
	["Kill the small monsters first, then the boss comes out of the water. Keep the Disciple safe."] = "Töte zuerst die kleinen Monster, dann kommt der Boss aus dem Wasser. Beschütze den Jünger.",
	["Kill the small water spirits as they appear."] = "Töte die kleinen Wassergeister, sobald sie erscheinen.",
	["Kill the spiders first."] = "Töte zuerst die Spinnen.",
	["Kill the spiders that rush out."] = "Töte die Spinnen, die herausstürmen.",
	["Kill the stone helpers fast."] = "Töte die Steinhelfer schnell.",
	["Kill the summoner dwarf first and keep ranged players away from him."] = "Töte zuerst den beschwörenden Zwerg und halte Fernkämpfer von ihm fern.",
	["Kill the three snakes around him first, then him."] = "Töte zuerst die drei Schlangen um ihn herum, dann ihn.",
	["Kill the three worgen with him first. He teleports, takes over minds and casts a shadow bolt. He is the last boss."] = "Töte zuerst die drei Worgen bei ihm. Er teleportiert sich, übernimmt die Kontrolle über Geister und wirkt Schattenblitze. Er ist der letzte Boss.",
	["Kill the totems at once."] = "Zerstöre die Totems sofort.",
	["Kill the two golems beside him first."] = "Töte zuerst die zwei Golems neben ihm.",
	["Kill the water snakes around him first."] = "Töte zuerst die Wasserschlangen um ihn herum.",
	["Kill the waves from both sides."] = "Töte die Wellen von beiden Seiten.",
	["Kill the worms as they appear."] = "Töte die Würmer, sobald sie erscheinen.",
	["Kill the zombies he calls."] = "Töte die Zombies, die er ruft.",
	["Kill them together. The chest behind has a medallion for Ironaya."] = "Töte sie gleichzeitig. In der Truhe dahinter liegt ein Medaillon für Ironaya.",
	["Killing her gives loot. Saving her is for a quest. Ask your group."] = "Tötest du sie, gibt es Beute. Rettest du sie, ist das für eine Quest. Frag deine Gruppe.",
	["Killing the other ogre bosses first earns a tribute buff. Ask your group."] = "Tötet ihr zuerst die anderen Ogerbosse, gibt es einen Tribut-Stärkungszauber. Frag deine Gruppe.",
	["Kills the enemy. Most groups have several."] = "Tötet den Feind. Die meisten Gruppen haben mehrere.",
	["Kite"] = "Kiten",
	["Kneeling before the monument in the Shrine of Thaurissan."] = "Kniend vor dem Denkmal im Shrine of Thaurissan.",
	["Lacerate costs less Rage, so you can use it more often."] = "Aufschlitzen kostet weniger Wut, so kannst du es öfter nutzen.",
	["Lady Anacondra can wait at any of several spots, so look around the first cave."] = "Lady Anacondra kann an mehreren Stellen warten, also sieh dich in der ersten Höhle um.",
	["Last Stand gives you extra Health for a short time. Use it when you are in danger."] = "Letztes Gefecht gibt dir kurz zusätzliche Gesundheit. Nutze es, wenn du in Gefahr bist.",
	["Last come the frost dragon and the lich."] = "Zuletzt kommen der Frostdrache und der Lich.",
	["Last run: %s. Reload the interface afterwards so it is saved."] = "Letzter Lauf: %s. Lade danach das Interface neu, damit es gespeichert wird.",
	["Later"] = "Später",
	["Lay on Hands saves a friend about to die. You can use it only now and then."] = "Handauflegung rettet einen Verbündeten kurz vor dem Tod. Du kannst sie nur ab und zu nutzen.",
	["Learn a profession from its trainer"] = "Lerne einen Beruf bei seinem Lehrer",
	["Learn where to level and which dungeons fit you"] = "Erfahre, wo du leveln kannst und welche Dungeons zu dir passen",
	["Learn which floor tiles are safe."] = "Merk dir, welche Bodenplatten sicher sind.",
	["Learn which side to stand on."] = "Merk dir, auf welcher Seite du stehen musst.",
	["Learning everything ready now costs about %s."] = "Alles jetzt Verfügbare zu lernen kostet etwa %s.",
	["Leave his dogs alone until he is nearly dead."] = "Lass seine Hunde in Ruhe, bis er fast tot ist.",
	["Leave through the south-east corridor, past Dark Iron dwarves, toward a natural cave."] = "Geh durch den Südostgang hinaus, an Zwergen der Dunkeleisen vorbei, zu einer natürlichen Höhle.",
	["Legacy"] = "Vermächtnis",
	["Legacy challenges do not reset. Each one counts once for your whole account."] = "Vermächtnis-Herausforderungen werden nicht zurückgesetzt. Jede zählt einmal für deinen ganzen Account.",
	["Legacy is open: use the Legacy button on the game's menu bar."] = "Vermächtnis ist offen: Nutze die Vermächtnis-Schaltfläche in der Menüleiste des Spiels.",
	["Legacy opens once one of your characters reaches level %d. You are level %d."] = "Vermächtnis öffnet sich, sobald einer deiner Charaktere Stufe %d erreicht. Du bist Stufe %d.",
	["Legacy points"] = "Vermächtnispunkte",
	["Legacy trees"] = "Vermächtnisbäume",
	["Legs"] = "Beine",
	["Lesser Healing Wave (level 20) is a fast heal for someone in trouble."] = "Geringe Welle der Heilung (Stufe 20) ist eine schnelle Heilung für jemanden in Not.",
	["Lets you zoom the camera out further, so you see enemies before they see you."] = "Lässt dich die Kamera weiter herauszoomen, damit du Feinde siehst, bevor sie dich sehen.",
	["Level %d"] = "Stufe %d",
	["Level %d and up: 5 or more above. Very risky."] = "Ab Stufe %d: 5 oder mehr über dir. Sehr riskant.",
	["Level %d or %d: 3 or 4 above you. Hard."] = "Stufe %d oder %d: 3 oder 4 über dir. Schwer.",
	["Level %d: first dungeon"] = "Stufe %d: erster Dungeon",
	["Level 10: first talent point"] = "Stufe 10: erster Talentpunkt",
	["Level 40: first mount"] = "Stufe 40: erstes Reittier",
	["Level 60"] = "Stufe 60",
	["Level 60. The whole world is open to you now."] = "Stufe 60. Jetzt steht dir die ganze Welt offen.",
	["Level 60: the top"] = "Stufe 60: ganz oben",
	["Levels %d to %d"] = "Stufe %d bis %d",
	["Levels %d to %d. Dungeons need a group of five."] = "Stufe %d bis %d. Dungeons brauchen eine Fünfergruppe.",
	["Library wing, levels 33 to 41. No key needed: the Scarlet Key is in the chest behind its last boss."] = "Bibliotheksflügel, Stufe 33 bis 41. Kein Schlüssel nötig: Der Scharlachrote Schlüssel liegt in der Truhe hinter dem letzten Boss.",
	["Light a campfire and sit by it for bonuses from camp items."] = "Entzünde ein Lagerfeuer und setz dich daneben, um Boni von Lagergegenständen zu erhalten.",
	["Lightning Shield hurts attackers more when they hit you."] = "Blitzschlagschild verletzt Angreifer stärker, wenn sie dich treffen.",
	["Little at first. Some blessings need Symbols later."] = "Anfangs wenig. Manche Segen brauchen später Symbole.",
	["Log in once on each of your other characters and they show up here too."] = "Logg dich einmal mit jedem deiner anderen Charaktere ein, dann erscheinen sie auch hier.",
	["Logging out inside an inn or a capital city builds rested experience, which gives extra experience from kills."] = "Ausloggen in einem Gasthaus oder einer Hauptstadt baut Erholungsbonus auf, der dir zusätzliche Erfahrung für Kills gibt.",
	["Look"] = "Aussehen",
	["Looking for group. A player who wants to join one."] = "Suche Gruppe. Ein Spieler, der einer Gruppe beitreten will.",
	["Looking for more. A group that needs another player."] = "Suche weitere. Eine Gruppe, die noch einen Spieler braucht.",
	["LookingForGroup: ask for a group (the number can differ)."] = "LookingForGroup (SucheNachGruppe): nach einer Gruppe fragen (die Nummer kann abweichen).",
	["Loot rolls"] = "Beuteverteilung",
	["Loot rolls: need if you will use it, greed to sell it."] = "Beuteverteilung: Bedarf, wenn du es benutzt, Gier, wenn du es verkaufen willst.",
	["Looting"] = "Plündern",
	["Losing a fight? Cast Fear on the enemy, then step away and recover."] = "Verlierst du einen Kampf? Wirke Furcht auf den Feind, dann geh weg und erhol dich.",
	["Losing a fight? Change into Bear Form, and heal yourself with Rejuvenation."] = "Verlierst du einen Kampf? Nimm Bärengestalt an und heile dich mit Verjüngung.",
	["Losing a fight? Piercing Howl slows them all; then run."] = "Verlierst du einen Kampf? Durchdringendes Heulen verlangsamt alle; dann lauf weg.",
	["Losing a fight? Press Evasion, or get away with Sprint."] = "Verlierst du einen Kampf? Drück Entrinnen oder flieh mit Sprinten.",
	["Losing a fight? Put Power Word: Shield on yourself and back away."] = "Verlierst du einen Kampf? Leg Machtwort: Schild auf dich und zieh dich zurück.",
	["Losing a fight? Use Concussive Shot to slow the enemy, then run."] = "Verlierst du einen Kampf? Verlangsame den Feind mit Erschütternder Schuss, dann lauf weg.",
	["Losing a fight? Use Ice Block to be safe, then recover and try again."] = "Verlierst du einen Kampf? Nutze Eisblock, um sicher zu sein, dann erhol dich und versuch es erneut.",
	["Lost in a city? Ask a guard. Trailhead remembers the directions for next time."] = "Verlaufen in einer Stadt? Frag eine Wache. Trailhead merkt sich den Weg fürs nächste Mal.",
	["Low"] = "Niedrig",
	["Low on Mana? Stop healing those who are fine, and drink between fights."] = "Wenig Mana? Heile niemanden, dem es gut geht, und trink zwischen den Kämpfen.",
	["Lower Spire first. The game lists its bosses in the order below, but groups often take another path. Follow your group's lead."] = "Zuerst die Untere Spitze. Das Spiel listet die Bosse in der Reihenfolge unten, aber Gruppen gehen oft einen anderen Weg. Folge deiner Gruppe.",
	["Lower Spire, among the orcs."] = "Untere Spitze, zwischen den Orcs.",
	["Lower Spire, in the cave with the baby dragons."] = "Untere Spitze, in der Höhle mit den Drachenjungen.",
	["Lower Spire, in the dragonkin area."] = "Untere Spitze, im Bereich der Drachkin.",
	["Lower Spire, in the ogre area. He must be called out with a special item."] = "Untere Spitze, im Ogerbereich. Er muss mit einem besonderen Gegenstand herbeigerufen werden.",
	["Lower Spire, in the spider area."] = "Untere Spitze, im Spinnenbereich.",
	["Lower Spire, near the end, with his guards."] = "Untere Spitze, nahe dem Ende, mit seinen Wachen.",
	["Lower Spire, with Halycon in the same cave."] = "Untere Spitze, mit Halycon in derselben Höhle.",
	["Lower Spire. He is first in the game's boss list."] = "Untere Spitze. Er steht als Erster in der Bossliste des Spiels.",
	["Lower deck of the ship, near the gangplank. Most groups fight him on the way out."] = "Unterdeck des Schiffs, nahe der Laufplanke. Die meisten Gruppen bekämpfen ihn auf dem Rückweg.",
	["Lower left room."] = "Unterer linker Raum.",
	["Lower middle room."] = "Unterer mittlerer Raum.",
	["Lower right room."] = "Raum unten rechts.",
	["Lowest: %s, at %d%%"] = "Am niedrigsten: %s, bei %d%%",
	["Luremaster: extra fish with a lure"] = "Ködermeister: mehr Fisch mit einem Köder",
	["Mailbox"] = "Briefkasten",
	["Main Hand"] = "Waffenhand",
	["Make an inn your home at its innkeeper"] = "Mach ein Gasthaus beim Gastwirt zu deinem Zuhause",
	["Make the whole window larger or smaller."] = "Macht das ganze Fenster größer oder kleiner.",
	["Makes you harder to hit"] = "Du wirst seltener getroffen",
	["Makes your next heal a critical heal, which is an extra-big one."] = "Deine nächste Heilung wird kritisch, also besonders groß.",
	["Makes your other Frost spells ready again, and it opens Ice Barrier."] = "Macht deine anderen Frostzauber wieder bereit und schaltet Eisbarriere frei.",
	["Mana comes back when you mix different heals."] = "Du bekommst Mana zurück, wenn du verschiedene Heilungen abwechselst.",
	["Mana low in a long fight? Drop Mana Tide Totem."] = "Wenig Mana in einem langen Kampf? Stell das Totem der Manaflut auf.",
	["Mana low? Stop and drink, or ask the party to wait for you."] = "Wenig Mana? Halt an und trink etwas oder bitte die Gruppe, auf dich zu warten.",
	["Mana low? Use Life Tap to turn health into Mana, but only when you are healthy."] = "Wenig Mana? Nutze Aderlass, um Gesundheit in Mana umzuwandeln, aber nur, wenn du gesund bist.",
	["Mana, plus rage or energy in animal forms."] = "Mana, dazu Wut oder Energie in Tiergestalten.",
	["Mana, which refills when you rest or drink."] = "Mana, das sich beim Ausruhen oder Trinken wieder auffüllt.",
	["Many Defias fighters stand in the halls. Pull one group at a time."] = "In den Gängen stehen viele Kämpfer der Defias. Zieh eine Gruppe nach der anderen.",
	["Many groups offer rewards once they like you enough. The Legacy reward track is a reputation of its own that fills as you earn Legacy points."] = "Viele Fraktionen bieten Belohnungen, sobald sie dich genug mögen. Die Vermächtnis-Belohnungsleiste ist ein eigener Ruf, der sich füllt, während du Vermächtnispunkte sammelst.",
	["Marker removed."] = "Markierung entfernt.",
	["Marker set. Press %s to open your map."] = "Markierung gesetzt. Drücke %s, um deine Karte zu öffnen.",
	["Marker set: %s. Follow the arrow on your screen."] = "Markierung gesetzt: %s. Folge dem Pfeil auf deinem Bildschirm.",
	["Marks where your quest objectives are on the map and the minimap."] = "Zeigt auf der Karte und der Minikarte, wo deine Questziele sind.",
	["Master Chef: cooking can make an extra dish"] = "Meisterkoch: Kochkunst kann ein zusätzliches Gericht ergeben",
	["Maul, Swipe and Claw hit harder, and it opens Lacerate."] = "Zermalmen, Prankenhieb und Klaue treffen härter und Aufschlitzen wird freigeschaltet.",
	["Maul, and later Claw and Rake, cost less Rage or Energy, so you can use them more."] = "Zermalmen und später Klaue und Krallenhieb kosten weniger Wut oder Energie, also kannst du sie öfter nutzen.",
	["Maul, and later Claw and Rake, cost less Rage or Energy."] = "Zermalmen und später Klaue und Krallenhieb kosten weniger Wut oder Energie.",
	["Maximum level"] = "Höchststufe",
	["Melee should stand behind him, away from his frontal cone."] = "Nahkämpfer sollten hinter ihm stehen, weg von seinem Frontalkegel.",
	["Mend Pet (level 12) heals your pet after a fight. Feed Pet when your pet is hungry."] = "Tier heilen (Stufe 12) heilt dein Tier nach einem Kampf. Nutze Tier füttern, wenn dein Tier hungrig ist.",
	["Middle"] = "Mitte",
	["Mind Blast and a full Mind Flay raise your and your party's Spirit for a while."] = "Gedankenschlag und ein volles Gedankenschinden erhöhen eine Weile deine Willenskraft und die deiner Gruppe.",
	["Mind Blast is ready again much sooner, so you can use it more."] = "Gedankenschlag ist viel schneller wieder bereit, also kannst du ihn öfter nutzen.",
	["Minimap button"] = "Minikartenknopf",
	["Mob"] = "Mob",
	["Money"] = "Geld",
	["Moonfire from a distance starts a fight, then change into Bear Form as it arrives."] = "Beginne den Kampf mit Mondfeuer aus der Ferne und wechsle in Bärengestalt, wenn der Gegner ankommt.",
	["More Armor from your gear, so you take less damage."] = "Mehr Rüstung durch deine Ausrüstung, also nimmst du weniger Schaden.",
	["More Armor in your animal forms, so you take less damage."] = "Mehr Rüstung in deinen Tiergestalten, also nimmst du weniger Schaden.",
	["More Defense, so enemies hit you less often."] = "Mehr Verteidigung, also treffen dich Gegner seltener.",
	["More Health and Mana for your demon, and more Mana for you."] = "Mehr Gesundheit und Mana für deinen Dämon und mehr Mana für dich.",
	["More Intellect, more Stamina in Bear Form, more Strength in Cat Form."] = "Mehr Intelligenz, mehr Ausdauer in Bärengestalt, mehr Stärke in Katzengestalt.",
	["More Intellect, which means a bigger pool of mana."] = "Mehr Intelligenz, also ein größerer Manavorrat.",
	["More Intellect, which means more Mana for healing yourself."] = "Mehr Intelligenz, also mehr Mana, um dich selbst zu heilen.",
	["More Intellect, which means more Mana for healing."] = "Mehr Intelligenz, also mehr Mana zum Heilen.",
	["More Intellect, which means more mana and, with Mental Dexterity, more attack power."] = "Mehr Intelligenz, also mehr Mana und mit Geistige Gewandtheit mehr Angriffskraft.",
	["More Intellect, which means more mana."] = "Mehr Intelligenz, also mehr Mana.",
	["More Spirit, and it opens Wild Growth."] = "Mehr Willenskraft und Wildwuchs wird freigeschaltet.",
	["More Stamina, so you have more health to survive with."] = "Mehr Ausdauer, also mehr Gesundheit zum Überleben.",
	["More Strength, so your attacks hit harder."] = "Mehr Stärke, also treffen deine Angriffe härter.",
	["More Strength, so your weapon hits harder."] = "Mehr Stärke, also trifft deine Waffe härter.",
	["More armor in your animal forms, so you take less damage."] = "Mehr Rüstung in deinen Tiergestalten, also nimmst du weniger Schaden.",
	["More critical strikes in Bear Form, and it opens Blood Frenzy."] = "Mehr kritische Treffer in Bärengestalt und Blutrausch wird freigeschaltet.",
	["More critical strikes while in Bear Form or Cat Form."] = "Mehr kritische Treffer in Bären- oder Katzengestalt.",
	["More critical strikes with all spells and attacks, healing included."] = "Mehr kritische Treffer mit allen Zaubern und Angriffen, auch beim Heilen.",
	["More critical strikes with all your attacks, and it opens the next row."] = "Mehr kritische Treffer mit all deinen Angriffen und die nächste Reihe wird freigeschaltet.",
	["More critical strikes with every attack and spell."] = "Mehr kritische Treffer mit jedem Angriff und Zauber.",
	["More critical strikes with every attack."] = "Mehr kritische Treffer mit jedem Angriff.",
	["More critical strikes with every spell and attack."] = "Mehr kritische Treffer mit jedem Zauber und Angriff.",
	["More critical strikes with everything."] = "Mehr kritische Treffer mit allem.",
	["More damage every time you shoot with your bow or gun."] = "Mehr Schaden bei jedem Schuss mit Bogen oder Schusswaffe.",
	["More damage with a two-handed weapon, but enemies notice you less."] = "Mehr Schaden mit einer Zweihandwaffe, aber Gegner bemerken dich weniger.",
	["More damage with a two-handed weapon."] = "Mehr Schaden mit einer Zweihandwaffe.",
	["More of your attacks land."] = "Mehr deiner Angriffe treffen.",
	["Most of the temple is dry, but a few ruins can only be reached by swimming."] = "Der Großteil des Tempels ist trocken, aber einige Ruinen erreichst du nur schwimmend.",
	["Most patrons in the bar are neutral. Do not use area attacks near them."] = "Die meisten Gäste in der Bar sind neutral. Nutze in ihrer Nähe keine Flächenangriffe.",
	["Most worn piece at %d%%"] = "Am meisten abgenutzt: %d%%",
	["Mostly Shadow spells: you hurt enemies from a distance with damage that keeps ticking while you cast the next spell. Shadowform comes in your 40s."] = "Vor allem Schattenzauber: Du verletzt Gegner aus der Ferne mit Schaden, der weiter tickt, während du den nächsten Zauber wirkst. Schattengestalt kommt mit Stufe 40 und mehr.",
	["Mount"] = "Reittier",
	["Mount vendor"] = "Reittierhändler",
	["Move and resize the bars, the minimap and the chat window. Press Escape and choose Edit Mode; Trailhead cannot do this for you."] = "Verschiebe Leisten, Minikarte und Chatfenster und ändere ihre Größe. Drück Escape und wähle Bearbeitungsmodus; Trailhead kann das nicht für dich tun.",
	["Move between the four riders on a plan."] = "Wechselt nach einem Plan zwischen den vier Reitern.",
	["Move out of his poison cloud. Save stuns for his frenzy. He is the last boss."] = "Geh aus seiner Giftwolke. Spar Betäubungen für seine Raserei auf. Er ist der letzte Boss.",
	["Mr. Smite and Edwin VanCleef each bring two hidden guards. Expect a surprise attack."] = "Mr. Smite und Edwin VanCleef bringen je zwei versteckte Wachen mit. Rechne mit einem Überraschungsangriff.",
	["Much more Stamina in Bear Form, so you have more Health."] = "Viel mehr Ausdauer in Bärengestalt, also mehr Gesundheit.",
	["Navy and gold, soft and rounded"] = "Marineblau und Gold, weich und abgerundet",
	["Near its limit"] = "Fast am Limit",
	["Near the end, with his guards."] = "Gegen Ende, mit seinen Wachen.",
	["Near the end."] = "Gegen Ende.",
	["Near the entrance, past the bridge."] = "Nahe dem Eingang, hinter der Brücke.",
	["Near the start, a giant hound."] = "Gleich am Anfang, ein riesiger Hund.",
	["Near the start, with two worgen at his side."] = "Gleich am Anfang, mit zwei Worgen an seiner Seite.",
	["Near the waterfall past Lord Serpentis."] = "Am Wasserfall hinter Lord Serpentis.",
	["Neck"] = "Hals",
	["Need if you will use it. Greed to sell it. Pass to skip."] = "Bedarf, wenn du es nutzt. Gier, um es zu verkaufen. Passen, um auszusetzen.",
	["Need, greed"] = "Bedarf, Gier",
	["Needs"] = "Braucht",
	["Needs a special quest item to appear."] = "Erscheint nur mit einem besonderen Questgegenstand.",
	["Needs the coffer keys, so most groups skip it."] = "Braucht die Truhenschlüssel, daher lassen ihn die meisten Gruppen aus.",
	["Neutral"] = "Neutral",
	["New player companion"] = "Begleiter für neue Spieler",
	["New spells and new ranks are bought from your class trainer."] = "Neue Zauber und neue Ränge kaufst du bei deinem Klassenlehrer.",
	["Next"] = "Weiter",
	["Next boss: %s  (%d of %d down)"] = "Nächster Boss: %s  (%d von %d besiegt)",
	["Next boss: %s. Open the route to see the way and where each boss stands."] = "Nächster Boss: %s. Öffne die Route, um den Weg und den Standort jedes Bosses zu sehen.",
	["Next in your build: %s (%d of %d)."] = "Als Nächstes in deinem Build: %s (%d von %d).",
	["Next is the Plague Wing."] = "Als Nächstes kommt das Seuchenviertel.",
	["Next milestone"] = "Nächstes Ziel",
	["Next point"] = "Nächster Punkt",
	["Next reset"] = "Nächster Reset",
	["Next talent point"] = "Nächster Talentpunkt",
	["Next tip"] = "Nächster Tipp",
	["Next: %s"] = "Als Nächstes: %s",
	["Next: %s."] = "Als Nächstes: %s.",
	["Night"] = "Nacht",
	["No Legacy Points yet"] = "Noch keine Vermächtnispunkte",
	["No automatic queue. Ask in chat or use Looking For Group."] = "Keine automatische Warteschlange. Frag im Chat oder nutze Suche nach Gruppe.",
	["No build for your class yet"] = "Noch kein Build für deine Klasse",
	["No dungeon yet: the first opens at level %d"] = "Noch kein Dungeon: der erste öffnet sich ab Stufe %d",
	["No flight point for your side"] = "Kein Flugpunkt für deine Fraktion",
	["No flight points listed"] = "Keine Flugpunkte aufgeführt",
	["No home yet. Ask an innkeeper to set one."] = "Noch kein Zuhause. Bitte einen Gastwirt, eins festzulegen.",
	["No professions"] = "Keine Berufe",
	["No quest hub listed for your side"] = "Kein Questgebiet für deine Fraktion aufgeführt",
	["No zone is listed for your level. Look at All zones."] = "Für deine Stufe ist kein Gebiet aufgeführt. Schau unter Alle Gebiete.",
	["None"] = "Nichts",
	["None found yet"] = "Noch nichts gefunden",
	["None of your flight points gets you closer. Every flight master you talk to on the way makes later trips quicker."] = "Keiner deiner Flugpunkte bringt dich näher. Jeder Flugmeister, mit dem du unterwegs sprichst, macht spätere Reisen schneller.",
	["None yet"] = "Noch keine",
	["North of the Lost Dig Site, ringed by oil slimes."] = "Nördlich der Vergessenen Ausgrabungsstätte, umringt von Ölschlammen.",
	["North part, the ogre keep (Gordok Commons). The Crescent Key opens its door."] = "Nordteil, die Ogerfestung (Gordok Commons). Der Crescent Key öffnet ihre Tür.",
	["North-west corner of the Eastern Plaguelands, across the long stone bridge, into the Living part. The Eastwall Gate, a cave a little east, leads to the Undead part and needs a key."] = "Nordwestecke der Östlichen Pestländer, über die lange Steinbrücke, in den lebenden Teil. Das Ostwalltor, eine Höhle etwas weiter östlich, führt zum untoten Teil und braucht einen Schlüssel.",
	["North-west section. From the courtyard, go through the narrow stairs, turn right, then jump through the big window."] = "Nordwestteil. Geh vom Hof aus durch die schmale Treppe, bieg rechts ab und spring dann durch das große Fenster.",
	["Not a boss you walk to. It is the progress for the whole raid."] = "Kein Boss, zu dem du hingehst. Es ist der Fortschritt für den ganzen Schlachtzug.",
	["Not better than what you wear: %s"] = "Nicht besser als deine Ausrüstung: %s",
	["Not during a fight. Try again when it is over."] = "Nicht während eines Kampfes. Versuch es danach noch einmal.",
	["Not in your bags"] = "Nicht in deinen Taschen",
	["Not known here"] = "Hier unbekannt",
	["Not listed"] = "Nicht aufgeführt",
	["Not on your action bars"] = "Nicht auf deinen Aktionsleisten",
	["Not open yet: it needs more points in its tree first."] = "Noch nicht frei: Dafür brauchst du erst mehr Punkte in diesem Baum.",
	["Not sure where talent points go?"] = "Unsicher, wohin die Talentpunkte gehören?",
	["Nothing else joins him, so put everything on him."] = "Niemand sonst greift mit ein, also konzentriert euch ganz auf ihn.",
	["Nothing found"] = "Nichts gefunden",
	["Nothing known yet."] = "Noch nichts bekannt.",
	["Nothing needs doing. Your skills rise as you gather and make things."] = "Nichts zu tun. Deine Fertigkeiten steigen, wenn du sammelst und herstellst.",
	["Nothing needs repair yet. %s is the most worn, at %d%% durability."] = "Noch muss nichts repariert werden. %s ist am meisten abgenutzt, bei %d%% Haltbarkeit.",
	["Nothing needs your attention right now. Trailhead will speak up when something does."] = "Gerade braucht nichts deine Aufmerksamkeit. Trailhead meldet sich, wenn etwas ansteht.",
	["Nothing to sell right now."] = "Gerade nichts zu verkaufen.",
	["Nothing to set here"] = "Hier gibt es nichts einzustellen",
	["Nothing urgent"] = "Nichts Dringendes",
	["Nothing you wear can break"] = "Nichts, was du trägst, kann kaputtgehen",
	["Nothing you wear has a durability yet, so there is nothing to repair."] = "Nichts, was du trägst, hat bisher Haltbarkeit, also gibt es nichts zu reparieren.",
	["Nothing your abilities use up"] = "Nichts, was deine Fähigkeiten verbrauchen",
	["Now"] = "Jetzt",
	["Off"] = "Aus",
	["Often skipped. He is immune to nature damage and hits hard. Keep the one in front healed."] = "Wird oft ausgelassen. Er ist immun gegen Naturschaden und schlägt hart zu. Haltet den vorne geheilt.",
	["On"] = "An",
	["On Alcaz Island, off the shore of Dustwallow Marsh. The entrance is in the basement of the large building."] = "Auf der Insel Alcaz vor der Küste der Marschen von Dustwallow. Der Eingang ist im Keller des großen Gebäudes.",
	["On Caer Darrow, the island in the Western Plaguelands. The door to the portal needs the Skeleton Key, from a long quest chain."] = "Auf Caer Darrow, der Insel in den Westlichen Pestländern. Die Tür zum Portal braucht den Skelettschlüssel aus einer langen Questreihe.",
	["On a hill over Marshal's Refuge in Un'Goro Crater."] = "Auf einem Hügel über Marshals Zuflucht im Un'Goro-Krater.",
	["On a pile of bones, among skeletons."] = "Auf einem Knochenhaufen, zwischen Skeletten.",
	["On an island in the lake."] = "Auf einer Insel im See.",
	["On the PvE ruleset you fight other players only when you choose (type /pvp). On the PvP ruleset you can be attacked almost anywhere. Dying to a player does not wear your gear."] = "Auf PvE-Realms kämpfst du nur gegen andere Spieler, wenn du es willst (tippe /pvp). Auf PvP-Realms kannst du fast überall angegriffen werden. Ein Tod durch einen Spieler nutzt deine Ausrüstung nicht ab.",
	["On the central bridge of Shadowforge City."] = "Auf der mittleren Brücke von Shadowforge City.",
	["On the high ledge in the gardens."] = "Auf dem hohen Felsvorsprung in den Gärten.",
	["On the middle platform of the big cave."] = "Auf der mittleren Plattform der großen Höhle.",
	["On the pirate ship, on the main deck."] = "Auf dem Piratenschiff, auf dem Hauptdeck.",
	["On the platform at the top of the Launch Bay."] = "Auf der Plattform ganz oben in der Launch Bay.",
	["On the platform at the very bottom."] = "Auf der Plattform ganz unten.",
	["On the streets of the Living part."] = "In den Straßen des lebenden Teils.",
	["On the throne at the back of the keep. He is the last boss."] = "Auf dem Thron hinten in der Festung. Er ist der letzte Boss.",
	["On the throne in the Imperial Seat. He is the last boss."] = "Auf dem Thron im Imperial Seat. Er ist der letzte Boss.",
	["On the way to level %d, with %d%% of a level rested."] = "Auf dem Weg zu Stufe %d, mit %d%% einer Stufe erholt.",
	["Once one player opens the West or North door, a torch just inside lets the others in."] = "Sobald ein Spieler die West- oder Nordtür öffnet, lässt eine Fackel gleich dahinter die anderen herein.",
	["Once there, fly to %s"] = "Flieg von dort nach %s",
	["Once they are open, the raids you are saved to show here."] = "Sobald sie geöffnet sind, erscheinen hier die Schlachtzüge, für die du gespeichert bist.",
	["One click on a defeated enemy picks up everything, so you never miss loot."] = "Ein Klick auf einen besiegten Gegner nimmt alles mit, so verpasst du keine Beute.",
	["One doorway leads into two dungeons: Lower Blackrock Spire for five players and Upper Blackrock Spire for ten. Lower is the best first target."] = "Ein Eingang führt in zwei Dungeons: Untere Blackrockspitze für fünf Spieler und Obere Blackrockspitze für zehn. Die Untere ist das beste erste Ziel.",
	["One of four trolls appears. Kill it and its friends."] = "Einer von vier Trollen erscheint. Töte ihn und seine Freunde.",
	["One of the Mana Elemental and Mana Wraith is the boss in the Path of Renewal. It is not clear which."] = "Entweder Mana Elemental oder Mana Wraith ist der Boss im Path of Renewal. Es ist nicht klar, welcher.",
	["One of the first bosses inside."] = "Einer der ersten Bosse drinnen.",
	["Only appears after you use the item. Ask your group."] = "Erscheint erst, wenn du den Gegenstand benutzt. Frag deine Gruppe.",
	["Only appears for a warlock quest."] = "Erscheint nur für eine Hexenmeister-Quest.",
	["Only fight him if the group is ready for the whole bar."] = "Kämpf nur gegen ihn, wenn die Gruppe bereit für die ganze Bar ist.",
	["Only go for him if the whole group is happy to swim. Watch your breath."] = "Geht nur auf ihn los, wenn die ganze Gruppe gern schwimmt. Achte auf deinen Atem.",
	["Only in the 20-player version, in Jammal'an's room."] = "Nur in der Version für 20 Spieler, in Jammal'ans Raum.",
	["Only in the 20-player version. Where it stands is not known."] = "Nur in der Version für 20 Spieler. Wo er steht, ist unbekannt.",
	["Only in the 20-player version. Where they stand is not known."] = "Nur in der Version für 20 Spieler. Wo sie stehen, ist unbekannt.",
	["Only in the 20-player version: the two dragons as one fight."] = "Nur in der Version für 20 Spieler: die beiden Drachen als ein Kampf.",
	["Only needed for quests."] = "Nur für Quests nötig.",
	["Onyxia's Lair"] = "Onyxias Hort",
	["Open"] = "Öffnen",
	["Open Armor Proficiencies in the game's skills window to see"] = "Öffne im Fertigkeitenfenster des Spiels die Rüstungsfertigkeiten, um es zu sehen",
	["Open Legacy window"] = "Vermächtnisfenster öffnen",
	["Open Screen setup"] = "Bildschirm einrichten",
	["Open Spells"] = "Zauber öffnen",
	["Open This week"] = "Diese Woche öffnen",
	["Open guide"] = "Ratgeber öffnen",
	["Open map"] = "Karte öffnen",
	["Open on 9 December, in %d days"] = "Öffnet am 9. Dezember, in %d Tagen",
	["Open or close Trailhead"] = "Trailhead öffnen oder schließen",
	["Open spellbook"] = "Zauberbuch öffnen",
	["Open talents"] = "Talente öffnen",
	["Open the Legacy page"] = "Vermächtnisseite öffnen",
	["Open the Legacy window to spend them."] = "Öffne das Vermächtnisfenster, um sie auszugeben.",
	["Open the route"] = "Route öffnen",
	["Open the route to see the way and where each boss stands."] = "Öffne die Route, um den Weg und den Standort jedes Bosses zu sehen.",
	["Open today"] = "Heute offen",
	["Open your spellbook from the game's menu bar."] = "Öffne dein Zauberbuch über die Menüleiste des Spiels.",
	["Open your talents from the game's menu bar."] = "Öffne deine Talente über die Menüleiste des Spiels.",
	["Open your talents from the game's menu bar. The Builds page says where each point goes."] = "Öffne deine Talente über die Menüleiste des Spiels. Die Seite Builds zeigt, wohin jeder Punkt gehört.",
	["Optional"] = "Optional",
	["Options"] = "Optionen",
	["Options, Key Bindings: choose which key does what"] = "Optionen, Tastaturbelegung: Leg fest, welche Taste was macht",
	["Options, System, Preset: Classic or Enhanced starting settings"] = "Optionen, System, Voreinstellung: Klassische oder erweiterte Starteinstellungen",
	["Orange"] = "Orange",
	["Orgrimmar"] = "Orgrimmar",
	["Orgrimmar's own dungeon: a hot cave of troggs and cultists under the city. Four bosses."] = "Orgrimmars eigener Dungeon: eine heiße Höhle voller Troggs und Kultisten unter der Stadt. Vier Bosse.",
	["Other"] = "Sonstige",
	["Other places"] = "Andere Orte",
	["Out in the world"] = "Draußen in der Welt",
	["Out of mana in a long fight? Press Inner Focus so your next spell is free."] = "Kein Mana in einem langen Kampf? Drück Innerer Fokus, damit dein nächster Zauber nichts kostet.",
	["Out of mana? Sit down and drink water. Conjure Water makes more."] = "Kein Mana? Setz dich hin und trink Wasser. Wasser herbeizaubern macht mehr davon.",
	["Outgrown"] = "Entwachsen",
	["Overpower (level 12) works only right after an enemy dodges. Press it then: it is cheap and strong."] = "Überwältigen (Stufe 12) geht nur direkt nachdem ein Gegner ausweicht. Drück es dann: Es ist billig und stark.",
	["Overpower crits far more often."] = "Überwältigen trifft viel öfter kritisch.",
	["Page %d of %d: %s"] = "Seite %d von %d: %s",
	["Parchment and leather, classic Warcraft"] = "Pergament und Leder, klassisches Warcraft",
	["Part of your Mana comes back while you cast, so healing costs less downtime."] = "Ein Teil deines Manas kommt beim Wirken zurück, also weniger Pausen beim Heilen.",
	["Part of your Mana comes back while you cast, so you can heal for longer."] = "Ein Teil deines Manas kommt beim Wirken zurück, also kannst du länger heilen.",
	["Part of your Mana comes back while you cast, so you can heal yourself."] = "Ein Teil deines Manas kommt beim Wirken zurück, also kannst du dich selbst heilen.",
	["Part of your Mana comes back while you cast."] = "Ein Teil deines Manas kommt beim Wirken zurück.",
	["Part of your mana regeneration keeps going while you cast."] = "Ein Teil deiner Manaregeneration läuft beim Wirken weiter.",
	["Party members nearby get more ranged Attack Power, and it opens Sniper Shot."] = "Gruppenmitglieder in der Nähe erhalten mehr Distanzangriffskraft und Heckenschützenschuss wird freigeschaltet.",
	["Past Mandokir."] = "Hinter Mandokir.",
	["Past that door, on the left side of the next junction. He is not always there."] = "Hinter dieser Tür, links an der nächsten Kreuzung. Er ist nicht immer da.",
	["Past the guards in the passages beyond the big cave."] = "Hinter den Wachen in den Gängen jenseits der großen Höhle.",
	["Patrols the first area with small spiders. Jump through the right window to skip the web gate."] = "Patrouilliert im ersten Bereich mit kleinen Spinnen. Spring durch das rechte Fenster, um das Netztor zu umgehen.",
	["Patrols the main hall. Pull him away from other enemies."] = "Patrouilliert in der Haupthalle. Zieh ihn weg von anderen Gegnern.",
	["Patrols the northern ring of the Detention Block."] = "Patrouilliert im nördlichen Ring des Detention Block.",
	["Patrols the winding ramp in the Hall of Crafting."] = "Patrouilliert auf der gewundenen Rampe in der Hall of Crafting.",
	["Performance Bonus: better crate hand-ins"] = "Leistungsbonus: bessere Kisten-Abgaben",
	["Perks in three trees, spent by each character on its own, up to 16 points at launch. Your total also unlocks rewards: a toy, a bear cub, a tabard and a bear mount."] = "Vorteile in drei Bäumen, die jeder Charakter selbst verteilt, zum Start bis zu 16 Punkte. Deine Gesamtzahl schaltet auch Belohnungen frei: ein Spielzeug, ein Bärenjunges, einen Wappenrock und ein Bärenreittier.",
	["Permanence: long buffs last longer"] = "Beständigkeit: lange Stärkungszauber halten länger",
	["Pick a look. You can change it later in Settings."] = "Wähle ein Aussehen. Du kannst es später in den Einstellungen ändern.",
	["Pick a side first. Both sides lead down to the deeper part."] = "Wähle zuerst eine Seite. Beide führen hinunter in den tieferen Teil.",
	["Pick a spot to fall back to. Worgen run fast. A rare boss, the Deathsworn Captain, shows up only sometimes."] = "Such dir einen Rückzugsort. Worgen sind schnell. Ein rarer Boss, der Deathsworn Captain, taucht nur manchmal auf.",
	["Pick one wing and finish it. The Graveyard (levels 30 to 38) is the easiest start and needs no key."] = "Wähle einen Flügel und schließ ihn ab. Der Friedhof (Stufe 30 bis 38) ist der leichteste Einstieg und braucht keinen Schlüssel.",
	["Pick what you need, or type it in the search box above."] = "Wähle, was du brauchst, oder gib es oben ins Suchfeld ein.",
	["Pirates and goblins in a mine under Westfall that ends on a ship. Eight bosses. A good first group dungeon."] = "Piraten und Goblins in einer Mine unter Westfall, die auf einem Schiff endet. Acht Bosse. Ein guter erster Gruppendungeon.",
	["Places to know"] = "Wichtige Orte",
	["Players buy and sell here. Your side's big cities share one."] = "Hier kaufen und verkaufen Spieler. Die großen Städte deiner Fraktion teilen sich eins.",
	["Players who fight from afar should keep their distance."] = "Wer aus der Ferne kämpft, sollte Abstand halten.",
	["Players who fight from afar should stay out of his aura."] = "Wer aus der Ferne kämpft, sollte außerhalb seiner Aura bleiben.",
	["Players who fight up close should stand behind him."] = "Wer nah dran kämpft, sollte hinter ihm stehen.",
	["Players write in short forms. Here is what they mean, and the chat channels and commands you will use. Press the button below for the next page."] = "Spieler schreiben in Kurzformen. Hier steht, was sie bedeuten, dazu die Chatkanäle und Befehle, die du nutzen wirst. Drück den Knopf unten für die nächste Seite.",
	["Playing now"] = "Gerade aktiv",
	["Potions"] = "Tränke",
	["Powders for some abilities. Poisons are brewed from vendor reagents."] = "Pulver für manche Fähigkeiten. Gifte werden aus Reagenzien vom Händler gebraut.",
	["Power"] = "Ressource",
	["Preset"] = "Voreinstellung",
	["Press %s to open your map."] = "Drücke %s, um deine Karte zu öffnen.",
	["Press Sniper Shot to hit from far away when you pull an enemy."] = "Drück Heckenschützenschuss, um aus großer Entfernung zu treffen, wenn du einen Gegner ziehst.",
	["Proc"] = "Proc",
	["Profession"] = "Beruf",
	["Profession trainer"] = "Berufslehrer",
	["Profession trainers in towns and cities teach them. Cooking, First Aid and Fishing are open to everyone."] = "Berufslehrer in Orten und Städten bringen sie dir bei. Kochkunst, Erste Hilfe und Angeln stehen allen offen.",
	["Professions"] = "Berufe",
	["Professions let you gather materials and make things. Each one has a skill that rises as you use it, up to a limit."] = "Mit Berufen sammelst du Materialien und stellst Dinge her. Jeder hat eine Fertigkeit, die beim Benutzen bis zu einer Grenze steigt.",
	["Pull"] = "Pull",
	["Pull each one back to the middle and manage mana."] = "Zieh jeden zurück in die Mitte und behalte dein Mana im Blick.",
	["Pull him away from other monsters."] = "Zieh ihn weg von anderen Monstern.",
	["Pull him out of the cave. Kill his totems and interrupt his heals."] = "Zieh ihn aus der Höhle. Zerstört seine Totems und unterbrecht seine Heilungen.",
	["Pull his guards away first."] = "Zieh zuerst seine Wachen weg.",
	["Pull it alone and interrupt its healing. It drops almost nothing."] = "Zieh ihn allein und unterbrich seine Heilung. Er lässt fast nichts fallen.",
	["Pull one dragon at a time and tank it against a wall."] = "Zieh einen Drachen nach dem anderen und tanke ihn an einer Wand.",
	["Pull one group at a time and kill the casters first."] = "Zieh eine Gruppe nach der anderen und tötet zuerst die Zauberwirker.",
	["Pull one ogre guard at a time."] = "Zieh eine Ogerwache nach der anderen.",
	["Pull only one helper at a time. He drops the Viewing Room key."] = "Zieh immer nur einen Helfer. Er lässt den Schlüssel zum Viewing Room fallen.",
	["Pull small groups. Do not try to take the whole room."] = "Zieh kleine Gruppen. Versuch nicht, den ganzen Raum auf einmal zu nehmen.",
	["Put Prayer of Mending on the tank. It jumps by itself as they take damage."] = "Wirk Gebet der Besserung auf den Tank. Es springt von allein weiter, wenn Schaden genommen wird.",
	["Put Rejuvenation on whoever is being hit. It heals them over time."] = "Wirk Verjüngung auf jeden, der getroffen wird. Sie heilt ihn über Zeit.",
	["Put Renew on anyone who keeps taking damage. Power Word: Shield stops a hit before it lands."] = "Wirk Erneuerung auf jeden, der ständig Schaden nimmt. Machtwort: Schild fängt einen Treffer ab, bevor er landet.",
	["Put Riptide on the one taking damage, then use Chain Heal on that same target."] = "Wirk Springflut auf den, der Schaden nimmt, dann Kettenheilung auf dasselbe Ziel.",
	["Put Rockbiter Weapon on your weapon, and keep Lightning Shield on you."] = "Leg Waffe des Felsbeißers auf deine Waffe und halte Blitzschlagschild aktiv.",
	["Put Shadow Word: Pain on the enemy first, then use Mind Blast whenever it is ready."] = "Wirk zuerst Schattenwort: Schmerz auf den Gegner, dann Gedankenschlag, sobald er bereit ist.",
	["Put Siphon Life on the enemy early. It slowly gives health to you."] = "Wirk früh Lebensentzug auf den Gegner. Er gibt dir langsam Gesundheit.",
	["Put a bag in one of your empty bag slots"] = "Leg eine Tasche in einen deiner leeren Taschenplätze",
	["Puts a small health bar over each enemy, so you can see how a fight is going."] = "Zeigt über jedem Gegner eine kleine Gesundheitsleiste, damit du siehst, wie ein Kampf läuft.",
	["Puts the game's map marker on this place"] = "Setzt die Kartenmarkierung des Spiels auf diesen Ort",
	["PvP journey"] = "PvP-Weg",
	["PvP rank"] = "PvP-Rang",
	["PvP season journey"] = "PvP-Saisonweg",
	["Quest hub in %s"] = "Questgebiet in %s",
	["Quest hubs"] = "Questgebiete",
	["Quest hubs here, none clearly the place to start"] = "Questgebiete hier, keins eindeutig der Startpunkt",
	["Quest text appears all at once instead of letter by letter, so you can read at your own speed."] = "Questtext erscheint auf einmal statt Buchstabe für Buchstabe, damit du in deinem Tempo lesen kannst.",
	["Quests"] = "Quests",
	["Quests for %s"] = "Quests für %s",
	["Rage. It builds as you fight and fades after."] = "Wut. Sie baut sich im Kampf auf und schwindet danach.",
	["Raid"] = "Schlachtzug",
	["Raid for a large group"] = "Schlachtzug für eine große Gruppe",
	["Raid lockouts"] = "Schlachtzugsperren",
	["Raid, levels %d to %d"] = "Schlachtzug, Stufe %d bis %d",
	["Raids"] = "Schlachtzüge",
	["Raids and the hardest dungeons open up."] = "Schlachtzüge und die schwersten Dungeons öffnen sich.",
	["Raids and the levels they are meant for. You are level %d."] = "Schlachtzüge und die Stufen, für die sie gedacht sind. Du bist Stufe %d.",
	["Raids are for large groups. Join a guild run."] = "Schlachtzüge sind für große Gruppen. Mach bei einem Gildenschlachtzug mit.",
	["Raids are for level 60 characters: Barrow Deeps for 10 players, Hyjal Summit for 20 and Onyxia's Lair for 40."] = "Schlachtzüge sind für Charaktere der Stufe 60: Barrow Deeps für 10 Spieler, Hyjal Summit für 20 und Onyxias Hort für 40.",
	["Raids open on 9 December, in %d days"] = "Schlachtzüge öffnen am 9. Dezember, in %d Tagen",
	["Raids open today, 9 December"] = "Schlachtzüge öffnen heute, am 9. Dezember",
	["Raids open tomorrow, 9 December"] = "Schlachtzüge öffnen morgen, am 9. Dezember",
	["Rank Points have a weekly cap"] = "Rangpunkte haben eine Wochengrenze",
	["Rank Points have a weekly cap that goes up each reset"] = "Rangpunkte haben eine Wochengrenze, die mit jedem Reset steigt",
	["Rank Points have a weekly cap. The game shows no cap for you yet."] = "Rangpunkte haben eine Wochengrenze. Das Spiel zeigt dir noch keine Grenze an.",
	["Rapid Fire is ready again sooner, and kills make your next shot hit harder."] = "Schnellfeuer ist schneller wieder bereit und Kills lassen deinen nächsten Schuss härter treffen.",
	["Rare bosses here do not always show up. Do not wait for them."] = "Rare Bosse tauchen hier nicht immer auf. Wartet nicht auf sie.",
	["Rattlegore drops the Viewing Room key you need to go deeper. Marduk and Vectus need a quest first."] = "Rattlegore lässt den Schlüssel zum Viewing Room fallen, den du für den tieferen Teil brauchst. Für Marduk und Vectus brauchst du zuerst eine Quest.",
	["Read"] = "Lesen",
	["Read how the game works, one topic at a time"] = "Lies Thema für Thema, wie das Spiel funktioniert",
	["Reading enemy levels"] = "Gegnerstufen lesen",
	["Ready"] = "Bereit",
	["Ready for"] = "Bereit für",
	["Ready for %s"] = "Bereit für %s",
	["Ready in %d minutes"] = "Bereit in %d Minuten",
	["Ready in 1 minute"] = "Bereit in 1 Minute",
	["Ready to learn now"] = "Jetzt erlernbar",
	["Reagent Economy: no reagents to buy"] = "Reagenzienersparnis: keine Reagenzien kaufen",
	["Really forget?"] = "Wirklich vergessen?",
	["Records what this version of the game can tell Trailhead. Not run yet."] = "Hält fest, was diese Spielversion Trailhead verraten kann. Noch nicht ausgeführt.",
	["Red"] = "Rot",
	["Regrowth critical heals happen more often."] = "Nachwachsen heilt öfter kritisch.",
	["Reincarnation is ready sooner, and your health is a little higher."] = "Reinkarnation ist schneller bereit und deine Gesundheit etwas höher.",
	["Reinforce: less gear wear when you die"] = "Verstärken: weniger Verschleiß beim Tod",
	["Rejuvenation heals more, and it opens Improved Regrowth."] = "Verjüngung heilt mehr und Verbessertes Nachwachsen wird freigeschaltet.",
	["Rejuvenation heals more, so you recover faster after a fight."] = "Verjüngung heilt mehr, also erholst du dich nach einem Kampf schneller.",
	["Release your spirit to go to the nearest graveyard, then run back to your body. A healer in your group may be able to bring you back where you lie."] = "Lass deinen Geist frei, um zum nächsten Friedhof zu gelangen, und lauf dann zu deinem Körper zurück. Ein Heiler in deiner Gruppe kann dich vielleicht dort wiederbeleben, wo du liegst.",
	["Reload now"] = "Jetzt neu laden",
	["Reload the interface once so the results are saved."] = "Lade das Interface einmal neu, damit die Ergebnisse gespeichert werden.",
	["Remove her curse from the tank quickly."] = "Entfernt ihren Fluch schnell vom Tank.",
	["Remove marker"] = "Markierung entfernen",
	["Rend's bleed does more damage, and it opens Deep Wounds."] = "Die Blutung von Verwunden macht mehr Schaden und Tiefe Wunden wird freigeschaltet.",
	["Renew and your other instant spells cost less mana."] = "Erneuerung und deine anderen Spontanzauber kosten weniger Mana.",
	["Renew heals more on every target."] = "Erneuerung heilt auf jedem Ziel mehr.",
	["Reopen this from Settings any time."] = "Du kannst das jederzeit in den Einstellungen wieder öffnen.",
	["Repair"] = "Reparieren",
	["Repair all"] = "Alles reparieren",
	["Repair all: %s"] = "Alles reparieren: %s",
	["Repair by itself"] = "Selbst reparieren",
	["Repaired all your gear for %s."] = "Deine ganze Ausrüstung für %s repariert.",
	["Repairs"] = "Reparaturen",
	["Repairs all gear at a vendor that can, if you can afford it. Off unless you turn it on."] = "Repariert bei einem passenden Händler die ganze Ausrüstung, wenn du es dir leisten kannst. Aus, bis du es einschaltest.",
	["Repentance, a late talent, holds one Humanoid still. Two at once? Hold one, kill the other."] = "Buße, ein spätes Talent, hält einen Humanoiden fest. Zwei auf einmal? Halte einen fest, töte den anderen.",
	["Reply to the last player who whispered you."] = "Antworte dem letzten Spieler, der dir geflüstert hat.",
	["Reported to be in Ashenvale. We have not seen the entrance ourselves."] = "Soll in Ashenvale liegen. Den Eingang haben wir selbst noch nicht gesehen.",
	["Reported to be in Deadwind Pass. We have not seen the entrance ourselves."] = "Soll im Gebirgspass der Totenwinde liegen. Den Eingang haben wir selbst noch nicht gesehen.",
	["Reported to be in the Eastern Plaguelands. We have not seen the entrance ourselves."] = "Soll in den Östlichen Pestländern liegen. Den Eingang haben wir selbst noch nicht gesehen.",
	["Reputation"] = "Ruf",
	["Reputation is how much a group in the world likes you. Quests and kills for a group raise it. Open your character window and its Reputation tab to see where you stand."] = "Ruf zeigt, wie sehr dich eine Fraktion in der Welt mag. Quests und Kills für eine Fraktion erhöhen ihn. Öffne dein Charakterfenster und den Reiter Ruf, um deinen Stand zu sehen.",
	["Res"] = "Res",
	["Reset position"] = "Position zurücksetzen",
	["Resourcefulness"] = "Einfallsreichtum",
	["Rest"] = "Erholung",
	["Rest here. The innkeeper can make it your hearthstone's home."] = "Ruh dich hier aus. Der Gastwirt kann es zum Zuhause deines Ruhesteins machen.",
	["Rested: double experience from kills"] = "Erholt: doppelte Erfahrung für Kills",
	["Resting here builds rested experience"] = "Ausruhen hier sammelt Erholungsbonus",
	["Resurrect: bring a dead player back to life."] = "Wiederbeleben: einen toten Spieler ins Leben zurückholen.",
	["Revenge (level 14) hits back after you block, dodge or parry. Use it when it lights up."] = "Rache (Stufe 14) schlägt zurück, nachdem du blockst, ausweichst oder parierst. Nutze sie, wenn sie aufleuchtet.",
	["Revenge hits much harder."] = "Rache trifft viel härter.",
	["Revered"] = "Respektvoll",
	["Ride a mount"] = "Reite ein Reittier",
	["Ride a mount (from level %d)"] = "Reite ein Reittier (ab Stufe %d)",
	["Riding"] = "Reiten",
	["Riding costs"] = "Kosten fürs Reiten",
	["Riding costs %s and you have %s. Sell what you do not need and put the rest aside."] = "Reiten kostet %s und du hast %s. Verkauf, was du nicht brauchst, und leg den Rest zur Seite.",
	["Riding is expensive. Start saving gold now."] = "Reiten ist teuer. Fang jetzt an, Gold zu sparen.",
	["Riding is the big cost of levelling: %s at level %d."] = "Reiten ist der größte Kostenpunkt beim Leveln: %s auf Stufe %d.",
	["Riding opens at level %d. Start putting gold aside for it now."] = "Reiten gibt es ab Stufe %d. Leg schon jetzt Gold dafür zurück.",
	["Riding trainer"] = "Reitlehrer",
	["Right for you"] = "Passt zu dir",
	["Right now"] = "Gerade jetzt",
	["Right of the Violet Hold, in the old landing area."] = "Rechts von der Violetten Festung, im alten Landebereich.",
	["Ring the gong in the first big room only when the group is ready."] = "Schlag den Gong im ersten großen Raum erst, wenn die Gruppe bereit ist.",
	["Riposte lights up after you parry. Press it: a strong hit that disarms."] = "Riposte leuchtet auf, nachdem du pariert hast. Drück sie: ein starker Treffer, der entwaffnet.",
	["Roles"] = "Rollen",
	["Rooms are full of monsters. Pull small groups, never the whole room."] = "Die Räume sind voller Monster. Zieh kleine Gruppen, nie den ganzen Raum.",
	["Route"] = "",
	["Rulesets"] = "Realm-Typen",
	["Run away from the player who becomes a bomb."] = "Lauf weg von dem Spieler, der zur Bombe wird.",
	["Run away when he burrows."] = "Lauf weg, wenn er sich eingräbt.",
	["Run check"] = "Prüfung starten",
	["Run low on Mana? Stop healing those who are fine and drink between fights."] = "Wenig Mana? Heile niemanden, dem es gut geht, und trink zwischen den Kämpfen.",
	["Run out of the way when he knocks players back."] = "Geh aus dem Weg, wenn er Spieler zurückstößt.",
	["Runes for teleports and portals later, and a feather for Slow Fall."] = "Runen für spätere Teleporte und Portale, und eine Feder für Langsamer Fall.",
	["Same as Hazzas: they come together."] = "Wie bei Hazzas: Sie kommen zusammen.",
	["Save Adrenaline Rush for the hard fights."] = "Heb dir Adrenalinrausch für die schweren Kämpfe auf.",
	["Save a big heal for his freezing water spell."] = "Heb dir eine große Heilung für seinen eisigen Wasserzauber auf.",
	["Saved %s ago"] = "Gespeichert, %s her",
	["Saved just now"] = "Gerade gespeichert",
	["Say to people nearby, or yell to people further away."] = "Sag etwas zu Leuten in der Nähe oder schrei es Leuten weiter weg zu.",
	["Scarlet Commander Mograine and High Inquisitor Whitemane share the last room. Mograine is fought with her, not on his own."] = "Scarlet Commander Mograine und High Inquisitor Whitemane teilen sich den letzten Raum. Mograine wird mit ihr bekämpft, nicht allein.",
	["Scarlet monsters hit hard and heal. Interrupt healers when you can."] = "Die Scharlachroten schlagen hart zu und heilen. Unterbrich Heiler, wenn du kannst.",
	["Screen setup"] = "Bildschirm einrichten",
	["Screen setup turns on Action Bar 2 with one click, and turns it off again."] = "„Bildschirm einrichten“ schaltet Aktionsleiste 2 mit einem Klick ein und auch wieder aus.",
	["Seal of Command (level 20) adds more Holy damage. Use it instead of Seal of Righteousness."] = "Siegel des Befehls (Stufe 20) fügt mehr Heiligschaden hinzu. Nutze es statt Siegel der Rechtschaffenheit.",
	["Seals and other instant spells cost less Mana, so you can fight longer."] = "Siegel und andere Spontanzauber kosten weniger Mana, so kannst du länger kämpfen.",
	["Search for players online by name, level or zone."] = "Suche nach Spielern, die online sind, nach Name, Stufe oder Gebiet.",
	["Search results"] = "Suchergebnisse",
	["Secret boss in the sewers. Needs the Tome of Dalaran to call her."] = "Geheimer Boss in der Kanalisation. Man braucht den Tome of Dalaran, um sie zu rufen.",
	["See builds"] = "Builds ansehen",
	["See dungeons"] = "Dungeons ansehen",
	["See the %s topic"] = "Siehe Thema %s",
	["See which spells you can learn and which are not on your bars"] = "Sieh, welche Zauber du lernen kannst und welche nicht auf deinen Leisten sind",
	["See zones"] = "Gebiete ansehen",
	["Seeds and berries for a few spells later."] = "Samen und Beeren für ein paar spätere Zauber.",
	["Sell"] = "Verkaufen",
	["Sell %d junk"] = "%d Plunder verkaufen",
	["Sell %d junk: %s"] = "%d Plunder verkaufen: %s",
	["Sell grey items by itself"] = "Graues selbst verkaufen",
	["Sell grey items to any vendor: they are junk."] = "Verkauf graue Gegenstände an jeden Händler: Das ist Plunder.",
	["Sell junk"] = "Plunder verkaufen",
	["Sells grey junk the moment a vendor window opens. Off unless you turn it on."] = "Verkauft grauen Plunder, sobald ein Händlerfenster aufgeht. Aus, bis du es einschaltest.",
	["Sen'jin Village, Durotar"] = "Sen'jin, Durotar",
	["Send items and gold to anyone, even your other characters."] = "Schick Gegenstände und Gold an jeden, auch an deine anderen Charaktere.",
	["Set a few game options that make the first hours easier"] = "Ein paar Spieloptionen setzen, die die ersten Stunden leichter machen",
	["Set marker"] = "Markierung setzen",
	["Set so far"] = "Bisher gesetzt",
	["Set up my screen"] = "Bildschirm einrichten",
	["Set up your screen"] = "Richte deinen Bildschirm ein",
	["Set your hearthstone at an innkeeper close to where you are questing. It saves a lot of walking."] = "Setz deinen Ruhestein bei einem Gastwirt nahe deinem Questgebiet. Das spart viel Lauferei.",
	["Settings"] = "Einstellungen",
	["Several bosses cast spells that need interrupting. Agree who interrupts whom before you start."] = "Mehrere Bosse wirken Zauber, die unterbrochen werden müssen. Klärt vorher, wer wen unterbricht.",
	["Several enemies? Swipe hits them all. At level 28, Challenging Roar makes all of them attack you."] = "Mehrere Gegner? Prankenhieb trifft sie alle. Ab Stufe 28 lässt Herausforderndes Gebrüll alle dich angreifen.",
	["Shadow Word: Pain lasts longer, so you cast it less often."] = "Schattenwort: Schmerz hält länger, also wirkst du es seltener.",
	["She disappears and hits from behind. Be ready."] = "Sie verschwindet und schlägt von hinten zu. Sei bereit.",
	["She has lots of health and a knockback. Stand away from edges."] = "Sie hat viel Gesundheit und einen Rückstoß. Halt dich von Kanten fern.",
	["She puts people to sleep. Keep the group close and finish her quickly."] = "Sie schläfert Leute ein. Bleibt nah beieinander und erledigt sie schnell.",
	["Shield Bash also stops the enemy from casting spells for a while."] = "Schildhieb hindert den Gegner auch eine Weile am Zaubern.",
	["Shield Slam hits hard and keeps the enemy on you. Use it every time it is ready."] = "Schildschlag trifft hart und hält den Gegner bei dir. Nutze ihn, sobald er bereit ist.",
	["Shield Wall, a big cut in damage you take, is ready again sooner."] = "Schildwall, der deinen erlittenen Schaden stark senkt, ist früher wieder bereit.",
	["Shocks and Lightning Shield cost much less Mana."] = "Schocks und Blitzschlagschild kosten viel weniger Mana.",
	["Shoot the powder kegs from range to hurt groups of dwarves."] = "Schieß aus der Ferne auf die Pulverfässer, um Gruppen von Zwergen zu treffen.",
	["Shots and Stings cost less Mana, so you can shoot for longer."] = "Schüsse und Stiche kosten weniger Mana, so kannst du länger schießen.",
	["Shoulders"] = "Schultern",
	["Show"] = "Anzeigen",
	["Show me"] = "Zeig's mir",
	["Show on the minimap"] = "Auf der Minikarte anzeigen",
	["Show the welcome panel again, with its doors into the main pages."] = "Das Willkommensfenster mit seinen Wegen zu den Hauptseiten erneut anzeigen.",
	["Show welcome"] = "Willkommen anzeigen",
	["Shown on the minimap"] = "Auf der Minikarte angezeigt",
	["Shows all your bags as one window, so there is only one place to look."] = "Zeigt alle Taschen als ein Fenster, damit du nur an einer Stelle suchen musst.",
	["Shows how many bag slots are left on the backpack button, so you know when to sell."] = "Zeigt freie Taschenplätze auf dem Rucksack-Knopf, damit du weißt, wann du verkaufen solltest.",
	["Shows who your enemy is attacking, so you can tell if it is coming for you."] = "Zeigt, wen dein Gegner angreift, damit du siehst, ob er auf dich losgeht.",
	["Shred costs less Energy, so your Cat Form attacks come faster."] = "Schreddern kostet weniger Energie, so kommen deine Angriffe in Katzengestalt schneller.",
	["Sinister Strike and Eviscerate hit harder."] = "Finsterer Stoß und Ausweiden treffen härter.",
	["Sinister Strike and Eviscerate with any one-handed weapons. Steady damage, little to learn, and a few tools for the fight that goes wrong."] = "Finsterer Stoß und Ausweiden mit beliebigen Einhandwaffen. Stetiger Schaden, wenig zu lernen und ein paar Werkzeuge für den Kampf, der schiefgeht.",
	["Sinister Strike is your main attack. Cheaper means more of them."] = "Finsterer Stoß ist dein Hauptangriff. Billiger heißt mehr davon.",
	["Skip"] = "Überspringen",
	["Skip him if you are in a hurry."] = "Lass ihn aus, wenn du es eilig hast.",
	["Skip him if you cannot reach him."] = "Lass ihn aus, wenn du ihn nicht erreichst.",
	["Skip him if you have no quest for him."] = "Lass ihn aus, wenn du keine Quest für ihn hast.",
	["Skip him if your group is weak."] = "Lass ihn aus, wenn deine Gruppe schwach ist.",
	["Skip him unless you have the quest."] = "Lass ihn aus, außer du hast die Quest.",
	["Skip him unless you want his buff drinks."] = "Lass ihn aus, außer du willst seine Stärkungsgetränke.",
	["Skip him unless you want his drops."] = "Lass ihn aus, außer du willst seine Beute.",
	["Skull"] = "Totenschädel",
	["Slice and Dice lasts longer."] = "Zerhäckseln hält länger.",
	["Slows every enemy near you, so you can get away."] = "Verlangsamt alle Gegner in deiner Nähe, damit du entkommen kannst.",
	["Sneaks up with Stealth and hits hard up close."] = "Schleicht sich mit Verstohlenheit an und trifft aus der Nähe hart.",
	["Sold %d grey items for %s."] = "%d graue Gegenstände für %s verkauft.",
	["Sold %d grey items."] = "%d graue Gegenstände verkauft.",
	["Some fights and dungeons are too hard alone. Up to five players make a party, and each one has a job: tank, healer or damage."] = "Manche Kämpfe und Dungeons sind allein zu schwer. Bis zu fünf Spieler bilden eine Gruppe, und jeder hat eine Aufgabe: Tank, Heiler oder Schaden.",
	["Some gear is broken."] = "Manche Ausrüstung ist kaputt.",
	["Some of your gear is broken"] = "Ein Teil deiner Ausrüstung ist kaputt",
	["Some quests and every dungeon are made for a group. Ask in chat or use Looking For Group."] = "Manche Quests und jeder Dungeon sind für Gruppen gemacht. Frag im Chat oder nutze Suche nach Gruppe.",
	["Someone about to die? Press Nature's Swiftness, then Healing Wave."] = "Jemand kurz vor dem Tod? Drück Schnelligkeit der Natur, dann Welle der Heilung.",
	["Sometimes your next Shadow Bolt casts much faster."] = "Manchmal wirkst du deinen nächsten Schattenblitz viel schneller.",
	["Soon"] = "Bald",
	["Soul Shards in your bags: summoning demons and some spells use one."] = "Seelensplitter in deinen Taschen: Dämonen beschwören und manche Zauber verbrauchen einen.",
	["South, in the fenced graveyard. This is the last boss."] = "Im Süden, auf dem umzäunten Friedhof. Das ist der letzte Boss.",
	["Spells"] = "Zauber",
	["Spells are less likely to be slowed down when you get hit."] = "Zauber werden seltener verzögert, wenn du getroffen wirst.",
	["Spells that are not on an action bar are listed on the Spells page. Trailhead never moves your spells."] = "Zauber, die auf keiner Aktionsleiste liegen, stehen auf der Seite Zauber. Trailhead verschiebt nie deine Zauber.",
	["Spells you know but have not put on a bar."] = "Zauber, die du kennst, aber auf keine Leiste gelegt hast.",
	["Spend them in three trees: Professions, Adventure, Resourcefulness."] = "Verteile sie auf drei Bäume: Berufe, Abenteuer, Findigkeit.",
	["Spend time in an inn or a city"] = "Verbring Zeit in einem Gasthaus oder einer Stadt",
	["Spend your first talent point"] = "Verteile deinen ersten Talentpunkt",
	["Spend your first talent point (level %d)"] = "Verteile deinen ersten Talentpunkt (Stufe %d)",
	["Spirit"] = "Willenskraft",
	["Spread out a little. Ask your group for the plan."] = "Verteilt euch etwas. Frag deine Gruppe nach dem Plan.",
	["Spread out and kill her guards."] = "Verteilt euch und tötet ihre Wachen.",
	["Spread out because he roots people."] = "Verteilt euch, denn er wurzelt Leute fest.",
	["Spread out for his fire spells."] = "Verteilt euch wegen seiner Feuerzauber.",
	["Spread out when he calls locusts."] = "Verteilt euch, wenn er Heuschrecken ruft.",
	["Spread out when he sprays. Do not stand close together."] = "Verteilt euch, wenn er sprüht. Steht nicht dicht beisammen.",
	["Spread out, because her lightning jumps between people. Kill the helpers first."] = "Verteilt euch, denn ihr Blitz springt zwischen Leuten hin und her. Tötet zuerst die Helfer.",
	["Spread out."] = "Verteilt euch.",
	["Spread out. He drops the Workshop Key, which opens a back door."] = "Verteilt euch. Er lässt den Workshop Key fallen, der eine Hintertür öffnet.",
	["Spread out. His hex turns a player into a berserker, so keep your distance."] = "Verteilt euch. Sein Fluch macht einen Spieler zum Berserker, also haltet Abstand.",
	["Spread out. Melee should step away from his big blast."] = "Verteilt euch. Nahkämpfer sollten seiner großen Explosion ausweichen.",
	["Spread out. Save a defensive for when he is nearly dead."] = "Verteilt euch. Spart eine Verteidigung auf, bis er fast tot ist.",
	["Spread out. When he runs out of mana he turns the group into sheep."] = "Verteilt euch. Wenn ihm das Mana ausgeht, verwandelt er die Gruppe in Schafe.",
	["Stable"] = "Stall",
	["Stable master"] = "Stallmeister",
	["Stamina"] = "Ausdauer",
	["Stamina and Armor first, then Strength and Agility. Leather armor, and a staff or other two-handed weapon."] = "Zuerst Ausdauer und Rüstung, dann Stärke und Beweglichkeit. Lederrüstung und ein Stab oder eine andere Zweihandwaffe.",
	["Stamina and Armor first, then Strength. A shield and a one-handed weapon, and the heaviest armor you can wear."] = "Zuerst Ausdauer und Rüstung, dann Stärke. Ein Schild, eine Einhandwaffe und die schwerste Rüstung, die du tragen kannst.",
	["Stamina and Intellect first, then gear that adds Spell Damage. A staff, or a one-handed weapon with an item for your other hand, and a wand."] = "Zuerst Ausdauer und Intelligenz, dann Ausrüstung mit Zauberschaden. Ein Stab oder eine Einhandwaffe mit einem Gegenstand für die andere Hand, und ein Zauberstab.",
	["Stamina first, then Strength and Armor. A shield and a one-handed weapon, and the heaviest armor you can wear."] = "Zuerst Ausdauer, dann Stärke und Rüstung. Ein Schild, eine Einhandwaffe und die schwerste Rüstung, die du tragen kannst.",
	["Stances change what you can do: Defensive comes at level 10."] = "Haltungen ändern, was du tun kannst: Verteidigungshaltung kommt auf Stufe 10.",
	["Stand behind him, away from his bombs."] = "Stell dich hinter ihn, weg von seinen Bomben.",
	["Stand behind the boss to avoid his sweeping beam."] = "Stell dich hinter den Boss, um seinem schwenkenden Strahl zu entgehen.",
	["Start a fight by drawing enemies to you."] = "Beginne einen Kampf, indem du Gegner zu dir lockst.",
	["Start at %s, %s"] = "Beginne bei %s, %s",
	["Start at the first one, %s."] = "Beginne beim ersten: %s.",
	["Start here"] = "Hier anfangen",
	["Start in the bar in the sewers. Cross the bridge and turn right, not to the locked door."] = "Beginne in der Kneipe in der Kanalisation. Überquer die Brücke und bieg rechts ab, nicht zur verschlossenen Tür.",
	["Start using Trailhead"] = "Trailhead nutzen",
	["Start with Frostbolt from far away. Keep casting it until the enemy is dead."] = "Beginne mit Frostblitz aus der Ferne. Wirk ihn weiter, bis der Gegner tot ist.",
	["Start with Lightning Bolt as the enemy runs to you, then hit it in melee."] = "Beginne mit Blitzschlag, während der Gegner auf dich zuläuft, und schlag ihn dann im Nahkampf.",
	["Start with full mana. Five waves arrive before he does."] = "Beginnt mit vollem Mana. Fünf Wellen kommen, bevor er erscheint.",
	["Stay away from his blasts."] = "Bleib weg von seinen Explosionen.",
	["Stay away from his sweeping hits."] = "Bleib weg von seinen schwungvollen Schlägen.",
	["Stay away from the edges. His heavy blow can throw you off, and there is no short way back up."] = "Bleib weg von den Kanten. Sein schwerer Schlag kann dich hinunterwerfen, und es gibt keinen kurzen Weg zurück nach oben.",
	["Stay far away when she kicks up dust."] = "Bleib weit weg, wenn sie Staub aufwirbelt.",
	["Stay near the inner rail. The crowd watching the arena wakes up easily."] = "Bleib nah am inneren Geländer. Die Zuschauer der Arena wachen leicht auf.",
	["Stay on the upper path on the purple side. The ramps down lead to strong monsters."] = "Bleib auf dem oberen Weg auf der lila Seite. Die Rampen nach unten führen zu starken Monstern.",
	["Stay out of his leaps."] = "Bleib aus seinen Sprüngen raus.",
	["Stay out of the cloud of disease. Heal the tank when he goes wild."] = "Bleib aus der Krankheitswolke raus. Heil den Tank, wenn er durchdreht.",
	["Stay out of the poison cloud."] = "Bleib aus der Giftwolke raus.",
	["Stay together. Big packs come from every side."] = "Bleibt zusammen. Große Gruppen kommen von allen Seiten.",
	["Steelgrill's Depot, Dun Morogh"] = "Steelgrills Depot, Dun Morogh",
	["Step away when he shakes the ground."] = "Geh zur Seite, wenn er den Boden erschüttert.",
	["Stoneclaw Totem is tougher and Earthbind Totem reaches further."] = "Totem der Steinklaue hält mehr aus und Totem der Erdbindung reicht weiter.",
	["Stoneskin Totem blocks more damage, which helps the whole group."] = "Totem der Steinhaut blockt mehr Schaden, was der ganzen Gruppe hilft.",
	["Stop following"] = "Nicht mehr folgen",
	["Stop the helpers where you can. If not, kill the basilisk first. Then put all your damage on him."] = "Halte die Helfer auf, wo du kannst. Sonst töte zuerst den Basilisken. Dann greift alle nur noch ihn an.",
	["Stops you from dragging spells off your bars by accident. Hold the pick up key (Shift unless you changed it) to move one."] = "Verhindert, dass du Zauber versehentlich von deinen Leisten ziehst. Halte die Aufnehmen-Taste (Umschalt, falls nicht geändert), um einen zu verschieben.",
	["Storm Cliffs, home of the dragon Azuregos. We know little more."] = "Sturmklippen, Heimat des Drachen Azuregos. Mehr wissen wir kaum.",
	["Stormwind"] = "Sturmwind",
	["Stormwind's prison, under the canals: a small jail full of Defias and prisoners. Five bosses."] = "Sturmwinds Gefängnis unter den Kanälen: ein kleiner Kerker voller Defias und Gefangener. Fünf Bosse.",
	["Strength"] = "Stärke",
	["Strength first, then Stamina. A two-handed sword, axe or mace, and the heaviest armor you can wear."] = "Zuerst Stärke, dann Ausdauer. Ein Zweihandschwert, eine Zweihandaxt oder ein Zweihandstreitkolben und die schwerste Rüstung, die du tragen kannst.",
	["Strength first, then Stamina. A two-handed weapon is best, and wear the heaviest armor you can."] = "Zuerst Stärke, dann Ausdauer. Eine Zweihandwaffe ist am besten, und trag die schwerste Rüstung, die du kannst.",
	["Strength, Agility and Stamina. Leather armor, and a staff or other two-handed weapon. A little Intellect helps your healing."] = "Stärke, Beweglichkeit und Ausdauer. Lederrüstung und ein Stab oder eine andere Zweihandwaffe. Etwas Intelligenz hilft deiner Heilung.",
	["Strong Defias guards nearby often join in. Pull carefully."] = "Starke Defias-Wachen in der Nähe mischen oft mit. Zieh vorsichtig.",
	["Stun him at low health so he cannot turn into his stronger form."] = "Betäube ihn bei wenig Gesundheit, damit er sich nicht in seine stärkere Gestalt verwandeln kann.",
	["Stuns an enemy for a short time, and it opens Shield Slam."] = "Betäubt einen Gegner kurz und ermöglicht Schildschlag.",
	["Stuns and Fear effects on you wear off a little sooner."] = "Betäubungen und Furchteffekte auf dir enden etwas früher.",
	["Summon Voidwalker first. It stands in front and takes the hits."] = "Beschwöre zuerst den Leerwandler. Er steht vorn und steckt die Treffer ein.",
	["Summoning a demon is quicker and costs less Mana."] = "Einen Dämon zu beschwören geht schneller und kostet weniger Mana.",
	["Sunder Armor costs less Rage, so you can use it more."] = "Rüstung zerreißen kostet weniger Wut, so kannst du es öfter nutzen.",
	["Sunken night elf ruins above and below the water, full of naga and murlocs. Seven bosses. Some parts are under water."] = "Versunkene Nachtelfenruinen über und unter Wasser, voller Naga und Murlocs. Sieben Bosse. Manche Teile liegen unter Wasser.",
	["Supplies"] = "Vorräte",
	["Swear an Oath to one friend, and your heals on that friend heal more."] = "Leiste einem Freund einen Eid, und deine Heilungen auf ihn heilen mehr.",
	["Swiftmend heals at once when Rejuvenation or Regrowth is on that friend."] = "Rasche Heilung heilt sofort, wenn Verjüngung oder Nachwachsen auf diesem Freund liegt.",
	["Swim down through the pool and follow the narrow winding cave. The path is mostly one way."] = "Tauch durch das Becken nach unten und folge der engen, gewundenen Höhle. Der Weg geht meist nur in eine Richtung.",
	["Swim or walk to the temple island in the middle of the lake in the Swamp of Sorrows. The door is on the island. Strong monsters patrol the wet passages."] = "Schwimm oder lauf zur Tempelinsel mitten im See in den Sümpfen des Elends. Der Eingang ist auf der Insel. Starke Monster patrouillieren in den nassen Gängen.",
	["Swim past The Vile Reef to the Sunken Hollow. A cave with a large tablet beside it is the entrance, underwater."] = "Schwimm am Finsteren Riff vorbei zur Versunkenen Höhle. Eine Höhle mit einer großen Steintafel daneben ist der Eingang, unter Wasser.",
	["Swipe, your attack that hits several enemies, does more damage."] = "Prankenhieb, dein Angriff gegen mehrere Gegner, macht mehr Schaden.",
	["Switch on Action Bars 3 to 8 here when you have more spells than room."] = "Schalte hier die Aktionsleisten 3 bis 8 ein, wenn du mehr Zauber als Platz hast.",
	["System"] = "",
	["Take the Undead part next, through the Eastwall Gate (needs the Key to the City), or from inside the city, since the parts are joined."] = "Nimm danach den Untoten-Teil, durch das Ostwalltor (braucht den Key to the City) oder von innen aus der Stadt, da die Teile verbunden sind.",
	["Take the narrow passages beyond the big cave and clear the guards in the way."] = "Nimm die engen Gänge hinter der großen Höhle und räum die Wachen im Weg aus.",
	["Take the right path with orange crystals. This is the orange side."] = "Nimm den rechten Weg mit den orangen Kristallen. Das ist die orange Seite.",
	["Takes the hits and keeps the enemy's attention."] = "Steckt die Treffer ein und hält die Aufmerksamkeit des Gegners.",
	["Talent points make your abilities stronger. Your class has three trees to put them in, and the deeper rows of a tree open as you put more points into it."] = "Talentpunkte machen deine Fähigkeiten stärker. Deine Klasse hat drei Bäume dafür, und tiefere Reihen eines Baums öffnen sich, je mehr Punkte du hineinsteckst.",
	["Talent points to spend"] = "Talentpunkte zu verteilen",
	["Talented: talent points start before level 10"] = "Talented: Talentpunkte schon vor Stufe 10",
	["Talents"] = "Talente",
	["Talents cannot be read in combat. This page fills in after the fight."] = "Talente sind im Kampf nicht lesbar. Diese Seite füllt sich nach dem Kampf.",
	["Talents let you shape your class."] = "Mit Talenten formst du deine Klasse.",
	["Talents make your character stronger. Unspent points do nothing."] = "Talente machen deinen Charakter stärker. Unverteilte Punkte bringen nichts.",
	["Talk before you invite someone, and be polite: it gets you invited back. To invite a player, right-click their portrait and choose Invite."] = "Sprich mit jemandem, bevor du ihn einlädst, und sei höflich: Dann wirst du wieder eingeladen. Um einen Spieler einzuladen, klick mit rechts auf sein Porträt und wähle Einladen.",
	["Talk to Emi Shortfuse. Her event ends with the fight against Grubbis and his pet."] = "Sprich mit Emi Shortfuse. Ihr Ereignis endet mit dem Kampf gegen Grubbis und sein Tier.",
	["Talk to Weegli Blastfuse first, so he sets charges on the far door. Then free Sergeant Bly at the stairs. This starts a long wave of fighters."] = "Sprich zuerst mit Weegli Blastfuse, damit er Sprengladungen an der hinteren Tür anbringt. Befrei dann Sergeant Bly an der Treppe. Das startet eine lange Welle von Kämpfern.",
	["Talk to each new one you pass. You can fly to those you met."] = "Sprich mit jedem neuen, an dem du vorbeikommst. Du kannst zu denen fliegen, die du getroffen hast.",
	["Talk to him after his guards are dead."] = "Sprich mit ihm, wenn seine Wachen tot sind.",
	["Talk to the Disciple of Naralax and walk with him to the final room. Keep him alive: he calls the last boss."] = "Sprich mit dem Disciple of Naralax und geh mit ihm zum letzten Raum. Halt ihn am Leben: Er ruft den letzten Boss.",
	["Talk to the flight master in %s"] = "Sprich mit dem Flugmeister in %s",
	["Talk to your guild."] = "Sprich mit deiner Gilde.",
	["Talk to your party."] = "Sprich mit deiner Gruppe.",
	["Tank"] = "",
	["Tank her on the ramp. Do not put damage-over-time spells on her: she cleanses them."] = "Tankt sie auf der Rampe. Keine Schaden-über-Zeit-Zauber auf sie: Sie reinigt sich davon.",
	["Tank him against a wall."] = "Tankt ihn an einer Wand.",
	["Tank him against the wall and kill his helpers first."] = "Tankt ihn an der Wand und tötet zuerst seine Helfer.",
	["Tank him in a corner and stand together behind him, out of the fire."] = "Tankt ihn in einer Ecke und stellt euch gemeinsam hinter ihn, raus aus dem Feuer.",
	["Tank him in the middle of the room. Someone presses the pillar buttons to stop his bombs for a while."] = "Tankt ihn in der Mitte des Raums. Jemand drückt die Säulenknöpfe, um seine Bomben eine Weile zu stoppen.",
	["Tank him with his back to a wall."] = "Tankt ihn mit dem Rücken zu einer Wand.",
	["Tank him with your back to a wall so his knock-back does not throw you."] = "Tank ihn mit dem Rücken zur Wand, damit dich sein Rückstoß nicht wegschleudert.",
	["Taunt makes an enemy attack you. Use it on one that is hitting your friends."] = "Spott lässt einen Gegner dich angreifen. Nutze es bei einem, der deine Freunde schlägt.",
	["Teach Trailhead about your game"] = "Bring Trailhead dein Spiel bei",
	["Teaches new abilities for gold. Yours is in your start area."] = "Bringt dir für Gold neue Fähigkeiten bei. Deiner ist in deinem Startgebiet.",
	["Templar's Bulwark gives you a big shield. Save it for an emergency."] = "Bollwerk des Templers gibt dir einen großen Schild. Heb ihn für Notfälle auf.",
	["That is this season's cap so far. It goes up at the weekly reset."] = "Das ist bisher die Obergrenze dieser Saison. Sie steigt beim wöchentlichen Zurücksetzen.",
	["The Crystal Vale, home of Prince Thunderaan. We know little more."] = "Das Kristalltal, Heimat von Prinz Thunderaan. Mehr wissen wir kaum.",
	["The Dark Iron Highway gates need a Shadowforge Key or a rogue with high lockpicking."] = "Die Tore des Dark Iron Highway brauchen einen Shadowforge Key oder einen Schurken mit hohem Schlossknacken.",
	["The Deeprun Tram joins Stormwind and Ironforge."] = "Die Tiefenbahn verbindet Sturmwind und Ironforge.",
	["The Key to the City comes from the Living part. It opens many locked gates and the Eastwall Gate."] = "Der Key to the City kommt aus dem lebenden Teil. Er öffnet viele verschlossene Tore und das Ostwalltor.",
	["The Legacy window is locked for now. The game opens it with your first Legacy Point."] = "Das Vermächtnisfenster ist noch gesperrt. Das Spiel schaltet es mit deinem ersten Vermächtnispunkt frei.",
	["The Quick and the Dead: faster as a ghost"] = "Schneller als der Tod: schneller als Geist",
	["The Spells page lists spells that are not on any bar yet."] = "Die Seite Zauber listet Zauber, die noch auf keiner Leiste sind.",
	["The Spider Wing is one of the four wings."] = "Das Spinnenviertel ist eines der vier Viertel.",
	["The Supplies topic counts what your abilities use up. Coming up lists what each level brings, and the Builds page helps with talents."] = "Das Thema Vorräte zählt, was deine Fähigkeiten verbrauchen. „Demnächst“ listet, was jede Stufe bringt, und die Seite Builds hilft bei Talenten.",
	["The arena. A random fighter comes out after the first waves."] = "Die Arena. Ein zufälliger Kämpfer kommt nach den ersten Wellen heraus.",
	["The cave after the pool is full of strong naga. Take it slowly."] = "Die Höhle nach dem Becken ist voller starker Naga. Lasst euch Zeit.",
	["The door is deep in Alliance land. Horde players: ask your group about the teleporter quest."] = "Der Eingang liegt tief im Allianzgebiet. Hordespieler: Fragt eure Gruppe nach der Teleporter-Quest.",
	["The door is in %s."] = "Der Eingang ist in %s.",
	["The famous island prison off Dustwallow Marsh. We only know the boss list, not the route."] = "Die berühmte Gefängnisinsel vor den Marschen von Dustwallow. Wir kennen nur die Bossliste, nicht den Weg.",
	["The fifth boss, sealed in by a priest and two guards."] = "Der fünfte Boss, eingeschlossen von einem Priester und zwei Wachen.",
	["The final boss, on the ramp outside her hut."] = "Der letzte Boss, auf der Rampe vor ihrer Hütte.",
	["The first boss, in a cave soon after the tunnel."] = "Der erste Boss, in einer Höhle kurz nach dem Tunnel.",
	["The first boss, just up the path from the cave."] = "Der erste Boss, gleich den Weg hinauf von der Höhle.",
	["The first boss, with two helpers."] = "Der erste Boss, mit zwei Helfern.",
	["The first boss."] = "Der erste Boss.",
	["The first one usually comes when a character reaches level 25. Reaching 150 skill in a crafting profession or exploring the whole world map also counts."] = "Der erste kommt meist, wenn ein Charakter Stufe 25 erreicht. Fertigkeit 150 in einem Handwerksberuf oder die ganze Weltkarte zu erkunden zählt auch.",
	["The five fights below come from the 20-player version of this temple in the game's files. Blizzard has not announced it for Forever, so you will probably not meet them."] = "Die fünf Kämpfe unten stammen aus der 20-Spieler-Version dieses Tempels in den Spieldateien. Blizzard hat sie für Forever nicht angekündigt, du triffst sie also wohl nicht.",
	["The floating fortress hangs over the Eastern Plaguelands. The raid door is on the ground below it."] = "Die schwebende Festung hängt über den Östlichen Pestländern. Der Eingang zum Schlachtzug ist am Boden darunter.",
	["The fourth boss, with two spear guards."] = "Der vierte Boss, mit zwei Speerwachen.",
	["The game check cannot run in combat. Try again after the fight."] = "Die Spielprüfung geht nicht im Kampf. Versuch es nach dem Kampf noch mal.",
	["The game did not take the change."] = "Das Spiel hat die Änderung nicht übernommen.",
	["The game does not allow a marker on that map. Open your map to find it instead."] = "Das Spiel erlaubt auf dieser Karte keine Markierung. Öffne stattdessen deine Karte, um es zu finden.",
	["The game has its own Sell All Junk and Repair buttons. This adds a second pair that shows the price first."] = "Das Spiel hat eigene Knöpfe für Plunder verkaufen und Reparieren. Hier kommt ein zweites Paar dazu, das zuerst den Preis zeigt.",
	["The game has no flight points to show for where you are standing. Try again outside."] = "Das Spiel hat für deinen Standort keine Flugpunkte zum Anzeigen. Versuch es draußen noch mal.",
	["The game has not listed any dungeons yet. Try again in a moment."] = "Das Spiel hat noch keine Dungeons gelistet. Versuch es gleich noch mal.",
	["The game has not listed its zones yet. Try again in a moment."] = "Das Spiel hat seine Gebiete noch nicht gelistet. Versuch es gleich noch mal.",
	["The game has not listed what you wear yet. Try again in a moment."] = "Das Spiel hat noch nicht gelistet, was du trägst. Versuch es gleich noch mal.",
	["The game has not listed your bags yet. Try again in a moment."] = "Das Spiel hat deine Taschen noch nicht gelistet. Versuch es gleich noch mal.",
	["The game has not listed your skills yet. Open your character window once, or try again in a moment."] = "Das Spiel hat deine Fertigkeiten noch nicht gelistet. Öffne einmal dein Charakterfenster oder versuch es gleich noch mal.",
	["The game has not listed your talents yet. Try again in a moment."] = "Das Spiel hat deine Talente noch nicht gelistet. Versuch es gleich noch mal.",
	["The game has not told Trailhead your class yet. Try again in a moment."] = "Das Spiel hat Trailhead deine Klasse noch nicht verraten. Versuch es gleich noch mal.",
	["The game has options that make the first hours easier: picking up loot with one click, a health bar over enemies, a second row of spell buttons. Trailhead can switch a few of them on for you and put each one back."] = "Das Spiel hat Optionen, die die ersten Stunden leichter machen: Beute mit einem Klick aufheben, eine Gesundheitsleiste über Gegnern, eine zweite Reihe Zauberknöpfe. Trailhead kann ein paar davon für dich einschalten und jede wieder zurückstellen.",
	["The game lists no raids for your character yet.\nRaids are for large groups at the highest levels. They will appear here, with how to get to each, as soon as the game lists them."] = "Das Spiel listet noch keine Schlachtzüge für deinen Charakter.\nSchlachtzüge sind für große Gruppen auf den höchsten Stufen. Sie erscheinen hier mit dem Weg zu jedem, sobald das Spiel sie listet.",
	["The game lists no weapon skills for this character."] = "Das Spiel listet keine Waffenfertigkeiten für diesen Charakter.",
	["The game lists nothing new for the levels you have left."] = "Das Spiel listet nichts Neues für deine restlichen Stufen.",
	["The game says: %s"] = "Das Spiel sagt: %s",
	["The game's talents have changed since this build was written, so Trailhead will not suggest points from it. An update will bring it back."] = "Die Talente im Spiel haben sich geändert, seit dieser Build geschrieben wurde, daher schlägt Trailhead daraus keine Punkte vor. Ein Update bringt ihn zurück.",
	["The last boss needs a quest chain that starts in Tanaris. The Shade of Eranikus needs none."] = "Der letzte Boss braucht eine Questreihe, die in Tanaris beginnt. Der Shade of Eranikus braucht keine.",
	["The last boss of the East part."] = "Der letzte Boss des Ostteils.",
	["The last boss of the West part."] = "Der letzte Boss des Westteils.",
	["The last boss, at the center of the fortress."] = "Der letzte Boss, in der Mitte der Festung.",
	["The last boss, at the top."] = "Der letzte Boss, ganz oben.",
	["The last boss, in a large room at the top. Cross the big bridge first."] = "Der letzte Boss, in einem großen Raum ganz oben. Überquer zuerst die große Brücke.",
	["The last boss, in the Undead part."] = "Der letzte Boss, im Untoten-Teil.",
	["The last boss, in the big temple at the end."] = "Der letzte Boss, im großen Tempel am Ende.",
	["The last boss, in the deepest chamber."] = "Der letzte Boss, in der tiefsten Kammer.",
	["The last boss, in the lava."] = "Der letzte Boss, in der Lava.",
	["The last boss."] = "Der letzte Boss.",
	["The last room is a big round hall with columns. Archaedas is here."] = "Der letzte Raum ist eine große runde Halle mit Säulen. Hier ist Archaedas.",
	["The ogre patrols before him are the real danger."] = "Die Oger-Patrouillen vor ihm sind die eigentliche Gefahr.",
	["The old dwarf burial halls under Ironforge, now overrun by ghosts and Dark Iron dwarves. Four bosses."] = "Die alten Grabhallen der Zwerge unter Ironforge, jetzt überrannt von Geistern und Dunkeleisenzwergen. Vier Bosse.",
	["The old wizard city of Dalaran, now a dungeon below and in its streets, with strange magic bosses. Nine bosses, some are secret."] = "Die alte Magierstadt Dalaran, jetzt ein Dungeon darunter und in ihren Straßen, mit seltsamen magischen Bossen. Neun Bosse, manche sind geheim.",
	["The paths cross over and under each other. Stay together."] = "Die Wege kreuzen sich über- und untereinander. Bleibt zusammen.",
	["The player who takes the hits."] = "Der Spieler, der die Treffer einsteckt.",
	["The raids are for level 60 characters, and each one resets once a week."] = "Die Schlachtzüge sind für Charaktere der Stufe 60, und jeder wird einmal pro Woche zurückgesetzt.",
	["The round Trailhead button on the edge of the minimap."] = "Der runde Trailhead-Knopf am Rand der Minikarte.",
	["The ruined old city of Lordaeron under the Undercity, with wave fights and a graveyard. Seven bosses, one is rare. Early reports say it suits the Horde best."] = "Die zerstörte alte Stadt Lordaeron unter Undercity, mit Wellenkämpfen und einem Friedhof. Sieben Bosse, einer ist rar. Erste Berichte sagen, es passt am besten zur Horde.",
	["The second boss, further in."] = "Der zweite Boss, weiter drinnen.",
	["The second boss, with two helpers."] = "Der zweite Boss, mit zwei Helfern.",
	["The standings"] = "Der Stand",
	["The tank must pick up the skeletons he calls."] = "Der Tank muss die Skelette übernehmen, die er ruft.",
	["The tank needs the best healer."] = "Der Tank braucht den besten Heiler.",
	["The things nobody tells you, checked against your own character."] = "Was dir niemand sagt, geprüft an deinem eigenen Charakter.",
	["The things you use up between and during fights: food and drink, bandages and potions, and what your class abilities need. Trailhead counts what is in your bags, and each item says what it does in its own tooltip."] = "Was du zwischen und in Kämpfen verbrauchst: Essen und Trinken, Verbände und Tränke und was deine Klassenfähigkeiten brauchen. Trailhead zählt, was in deinen Taschen ist, und jeder Gegenstand sagt in seinem Tooltip, was er tut.",
	["The third boss, with two helpers."] = "Der dritte Boss, mit zwei Helfern.",
	["The weapons in your hands are in good shape. When you pick up a new kind of weapon, look here first: a skill far under its limit means you will hit and crit a little less often until you have used it for a while."] = "Die Waffen in deinen Händen sind in gutem Zustand. Wenn du eine neue Waffenart aufnimmst, schau zuerst hier: Eine Fertigkeit weit unter ihrem Maximum heißt, dass du etwas seltener triffst und kritisch triffst, bis du sie eine Weile benutzt hast.",
	["The whole group dies."] = "Die ganze Gruppe stirbt.",
	["The world"] = "Die Welt",
	["Themes: night, journal, ember"] = "Designs: night, journal, ember",
	["Then raid lockouts start over and the cap on PvP Rank Points goes up."] = "Dann werden Schlachtzugssperren zurückgesetzt und die Obergrenze für PvP-Rangpunkte steigt.",
	["Then the Construct Wing."] = "Dann das Konstruktviertel.",
	["Then the Military Wing."] = "Dann das Militärviertel.",
	["There is also a back door in Dustwind Gulch, inside a cave of strong troggs."] = "Es gibt auch eine Hintertür in der Staubwindschlucht, in einer Höhle voller starker Troggs.",
	["This character can spend up to %d in total."] = "Dieser Charakter kann insgesamt bis zu %d ausgeben.",
	["This pair cannot be pulled apart. Tank them against a wall."] = "Dieses Paar lässt sich nicht trennen. Tankt sie an einer Wand.",
	["This version can learn more. Run the quick check once more."] = "Diese Version kann mehr lernen. Führ die Schnellprüfung noch einmal aus.",
	["This week"] = "Diese Woche",
	["This week it went up by %d."] = "Diese Woche stieg sie um %d.",
	["Three dwarf bosses together. The dwarves are friendly to Alliance players, so this fight is for Horde."] = "Drei Zwergenbosse zusammen. Die Zwerge sind Allianzspielern freundlich gesinnt, also ist dieser Kampf für die Horde.",
	["Three looks for the same window. Changes at once."] = "Drei Looks für dasselbe Fenster. Ändert sich sofort.",
	["Three raids open for level 60 characters, and each one resets once a week."] = "Drei Schlachtzüge sind für Charaktere der Stufe 60 offen, und jeder wird einmal pro Woche zurückgesetzt.",
	["Thrill of Adventure: health and mana on kills"] = "Abenteuerlust: Gesundheit und Mana bei Kills",
	["Through the cracked wall on the right of Theka's room, in a cave guarded by elite patrols."] = "Durch die rissige Wand rechts in Thekas Raum, in einer Höhle, die Elite-Patrouillen bewachen.",
	["Through the sewers under the Cantrips and Crows bar in Silverpine Forest. Reports say you need a key from a quest chain. We have not confirmed it."] = "Durch die Kanalisation unter der Kneipe Cantrips and Crows im Silberwald. Berichten zufolge brauchst du einen Schlüssel aus einer Questreihe. Bestätigt haben wir das nicht.",
	["Thunder Bluff"] = "",
	["Thunder Clap costs less Rage."] = "Donnerknall kostet weniger Wut.",
	["Thunder Clap hits all enemies near you and makes them attack more slowly."] = "Donnerknall trifft alle Gegner in deiner Nähe und lässt sie langsamer angreifen.",
	["Time in an inn or a city, even logged out, makes you rested: monsters then give extra experience."] = "Zeit in einem Gasthaus oder einer Stadt, auch ausgeloggt, macht dich erholt: Monster geben dann extra Erfahrung.",
	["Tip for the group"] = "Tipp für die Gruppe",
	["Tip: %s"] = "Tipp: %s",
	["To see later levels here, tick Unavailable in the trainer window's filter."] = "Um spätere Stufen hier zu sehen, hak „Nicht verfügbar“ im Filter des Lehrerfensters an.",
	["To the %s"] = "Richtung %s",
	["Too dangerous"] = "Zu gefährlich",
	["Top of the bat tower."] = "Oben im Fledermausturm.",
	["Totems cost less mana, so you can drop one every fight."] = "Totems kosten weniger Mana, so kannst du in jedem Kampf eins setzen.",
	["Tougher enemies. Gold dragon: elite. Silver: rare."] = "Härtere Gegner. Goldener Drache: Elite. Silberner: Rar.",
	["Towns and camps where several quests start, for your side."] = "Städte und Lager, in denen mehrere Quests beginnen, für deine Seite.",
	["Towns and cities have people who do things for you. Each row below is one of them. Click a row to find the nearest one on your map."] = "In Städten und Dörfern gibt es Leute, die Dinge für dich erledigen. Jede Zeile unten ist einer davon. Klick auf eine Zeile, um den nächsten auf deiner Karte zu finden.",
	["Towns and services"] = "Orte und Dienste",
	["Trade: buying and selling items."] = "Handel: Gegenstände kaufen und verkaufen.",
	["Trailhead at this vendor"] = "Trailhead bei diesem Händler",
	["Trailhead cannot read these options in your game. The Options menu in the game menu has them all."] = "Trailhead kann diese Optionen in deinem Spiel nicht lesen. Das Optionsmenü im Spielmenü hat sie alle.",
	["Trailhead cannot read your points here. Open the Legacy window to see them. It unlocks with your first point, usually when a character reaches level 25."] = "Trailhead kann deine Punkte hier nicht lesen. Öffne das Vermächtnisfenster, um sie zu sehen. Es wird mit deinem ersten Punkt freigeschaltet, meist wenn ein Charakter Stufe 25 erreicht.",
	["Trailhead cannot read your rank here. The PvP tab of your character window shows it."] = "Trailhead kann deinen Rang hier nicht lesen. Der PvP-Reiter deines Charakterfensters zeigt ihn.",
	["Trailhead cannot tell where you are standing right now, so it cannot break the trip into steps."] = "Trailhead weiß gerade nicht, wo du stehst, und kann die Reise daher nicht in Schritte teilen.",
	["Trailhead cannot tell who this character is yet. Try again in a moment."] = "Trailhead weiß noch nicht, wer dieser Charakter ist. Versuch es gleich noch mal.",
	["Trailhead does not know the sea crossings yet. Open this again once you have landed for the rest of the way."] = "Trailhead kennt die Seewege noch nicht. Öffne das hier nach der Landung erneut für den Rest des Wegs.",
	["Trailhead does not know where %s is entered yet."] = "Trailhead weiß noch nicht, wo man %s betritt.",
	["Trailhead does not know where the door is yet. It learns it the first time one of your characters walks in."] = "Trailhead weiß noch nicht, wo der Eingang ist. Es lernt ihn, wenn einer deiner Charaktere zum ersten Mal hineingeht.",
	["Trailhead does not know where this is yet."] = "Trailhead weiß noch nicht, wo das ist.",
	["Trailhead does not know which flight points you have yet. Talk to any flight master once and it will."] = "Trailhead weiß noch nicht, welche Flugpunkte du hast. Sprich einmal mit einem Flugmeister, dann weiß es das.",
	["Trailhead has a ready-made build for your class.\nFollow it and every point has a place."] = "Trailhead hat einen fertigen Build für deine Klasse.\nFolge ihm, und jeder Punkt hat seinen Platz.",
	["Trailhead has new questions"] = "Trailhead hat neue Fragen",
	["Trailhead has no quest hubs listed for your side in this zone."] = "Trailhead kennt in diesem Gebiet keine Questzentren für deine Seite.",
	["Trailhead has no written route for this place yet. The bosses are listed below, in the order the game lists them."] = "Trailhead hat für diesen Ort noch keine Wegbeschreibung. Die Bosse stehen unten, in der Reihenfolge des Spiels.",
	["Trailhead knows nothing called \"%s\" yet. It searches places you have found, flight points, zones and dungeons."] = "Trailhead kennt noch nichts namens \"%s\". Es durchsucht Orte, die du gefunden hast, Flugpunkte, Gebiete und Dungeons.",
	["Trailhead knows where the door is."] = "Trailhead weiß, wo der Eingang ist.",
	["Trailhead never moves your spells. The Spells page lists any that are not on a bar."] = "Trailhead verschiebt nie deine Zauber. Die Seite Zauber listet alle, die auf keiner Leiste sind.",
	["Trailhead remembers %d places you have found."] = "Trailhead kennt %d Orte, die du gefunden hast.",
	["Trailhead remembers 1 place you have found."] = "Trailhead kennt 1 Ort, den du gefunden hast.",
	["Trailhead remembers every one you use, for all your characters. In a city, ask a guard for directions: Trailhead keeps those too."] = "Trailhead merkt sich jeden, den du nutzt, für alle deine Charaktere. Frag in einer Stadt eine Wache nach dem Weg: Trailhead merkt sich auch das.",
	["Trailhead tells you what to do next, shows you where things are, and explains the parts of the game nobody tells you about. It only reads what your game already knows, and it never sends anything anywhere."] = "Trailhead sagt dir, was als Nächstes zu tun ist, zeigt dir, wo Dinge sind, und erklärt die Teile des Spiels, die dir niemand erklärt. Es liest nur, was dein Spiel schon weiß, und sendet nie etwas irgendwohin.",
	["Trainer"] = "Lehrer",
	["Trainer: %s"] = "Lehrer: %s",
	["Trainers sell your new spells as you level."] = "Lehrer verkaufen dir neue Zauber, während du aufsteigst.",
	["Tram"] = "Bahn",
	["Travel"] = "Reisen",
	["Trinket"] = "Schmuck",
	["Turn on"] = "Einschalten",
	["Turn on Aspect of the Hawk before you fight and leave it on."] = "Schalte Aspekt des Falken vor dem Kampf ein und lass ihn an.",
	["Turn on Righteous Fury before a fight. It makes enemies pay more attention to you."] = "Schalte Zorn der Gerechtigkeit vor einem Kampf ein. Gegner achten dann mehr auf dich.",
	["Turn on Shadowform before you pull, so every Shadow spell costs less mana."] = "Schalte Schattengestalt vor dem Pull ein, damit jeder Schattenzauber weniger Mana kostet.",
	["Turn on a second row of action buttons"] = "Eine zweite Reihe Aktionsknöpfe einschalten",
	["Two enemies on you? Blade Flurry makes your attacks hit both."] = "Zwei Gegner an dir? Klingenwirbel lässt deine Angriffe beide treffen.",
	["Two enemies on you? Sweeping Strikes makes your attacks hit both."] = "Zwei Gegner an dir? Weitreichende Stöße lässt deine Angriffe beide treffen.",
	["Type /join and a channel name to join a channel."] = "Gib /join und einen Kanalnamen ein, um einem Kanal beizutreten.",
	["Under a minute on foot"] = "Unter einer Minute zu Fuß",
	["Undercity"] = "",
	["Undo"] = "Rückgängig",
	["Undo all"] = "Alles rückgängig",
	["Unfriendly"] = "Unfreundlich",
	["Unspent points do nothing."] = "Nicht verteilte Punkte bringen nichts.",
	["Until then, press \"Show on the minimap\" and the game marks any that are close to you."] = "Bis dahin drück auf „Auf der Minikarte zeigen“, dann markiert das Spiel alle, die in deiner Nähe sind.",
	["Until then, the Guide's Talents topic shows where your points are."] = "Bis dahin zeigt das Thema Talente im Ratgeber, wohin deine Punkte gehen.",
	["Upgrade for you: %s"] = "Verbesserung für dich: %s",
	["Upgrade for you: that slot is empty"] = "Verbesserung für dich: der Platz ist leer",
	["Upgrade hints"] = "Upgrade-Tipps",
	["Upper Spire must be unlocked. We could not confirm how in Forever, so ask your group."] = "Die Obere Spitze muss freigeschaltet werden. Wie das in Forever geht, konnten wir nicht bestätigen, frag also deine Gruppe.",
	["Upper Spire starts past the Pyroguard's door. It is for ten players and must be unlocked. Ask your group what it needs."] = "Die Obere Spitze beginnt hinter der Tür des Pyroguard. Sie ist für zehn Spieler und muss freigeschaltet werden. Frag deine Gruppe, was dafür nötig ist.",
	["Upper Spire, in a cave off the arena."] = "Obere Spitze, in einer Höhle neben der Arena.",
	["Upper Spire, in a cell room right inside the door."] = "Obere Spitze, in einem Zellenraum gleich hinter der Tür.",
	["Upper Spire, in the arena."] = "Obere Spitze, in der Arena.",
	["Upper Spire, the throne room. He is the last boss."] = "Obere Spitze, im Thronsaal. Er ist der letzte Boss.",
	["Upper left room."] = "Raum oben links.",
	["Upper middle room."] = "Raum oben in der Mitte.",
	["Upper right room."] = "Raum oben rechts.",
	["Use Defensive Stance (level 10) and a shield. You take less damage, and enemies notice you more."] = "Nutze Verteidigungshaltung (Stufe 10) und einen Schild. Du erleidest weniger Schaden, und Gegner achten mehr auf dich.",
	["Use Earth Shock whenever it is ready for extra damage."] = "Nutze Erdschock immer, wenn er bereit ist, für zusätzlichen Schaden.",
	["Use Flash of Light for quick small heals, and Holy Light for slow, big ones."] = "Nutze Lichtblitz für schnelle kleine Heilungen und Heiliges Licht für langsame, große.",
	["Use Heal on the player taking hits. It is quicker to cast now."] = "Wirk Heilen auf den Spieler, der Treffer einsteckt. Es wirkt jetzt schneller.",
	["Use Healing Touch for a big heal. From level 12, Regrowth helps when someone is in trouble."] = "Nutze Heilende Berührung für eine große Heilung. Ab Stufe 12 hilft Nachwachsen, wenn jemand in Not ist.",
	["Use Holy Strike for extra damage when you have Mana to spare."] = "Nutze Heiliger Stoß für zusätzlichen Schaden, wenn du Mana übrig hast.",
	["Use Judgement and Holy Strike every time they are ready. Hitting keeps their attention."] = "Nutze Richturteil und Heiliger Stoß, sobald sie bereit sind. Treffer halten die Aufmerksamkeit der Gegner bei dir.",
	["Use Judgement every time it is ready."] = "Nutze Richturteil, sobald es bereit ist.",
	["Use Lacerate again and again on the main enemy. The bleed grows and keeps its attention on you."] = "Nutze Aufschlitzen immer wieder auf den Hauptgegner. Die Blutung wächst und hält seine Aufmerksamkeit bei dir.",
	["Use Lesser Heal to top people up, and Heal (level 16) for bigger heals. Skip it if no one is hurt."] = "Nutze Geringes Heilen, um andere aufzufüllen, und Heilen (Stufe 16) für größere Heilungen. Lass es, wenn niemand verletzt ist.",
	["Use Maul as your main attack, and Demoralizing Roar to make enemies hit softer."] = "Nutze Zermalmen als Hauptangriff und Demoralisierendes Gebrüll, damit Gegner schwächer zuschlagen.",
	["Use Mortal Strike every time it is ready."] = "Nutze Tödlicher Stoß, sobald er bereit ist.",
	["Use Sinister Strike to build combo points, then Eviscerate to spend them."] = "Nutze Finsterer Stoß, um Combopunkte aufzubauen, und dann Ausweiden, um sie zu verbrauchen.",
	["Use Smite to fill the gaps. Put Power Word: Shield on yourself before a hard fight."] = "Füll die Lücken mit Göttliche Pein. Leg dir vor einem harten Kampf Machtwort: Schild auf.",
	["Use Stormstrike every time it is ready, then follow it with Lightning Bolt."] = "Nutze Sturmschlag, sobald er bereit ist, und danach Blitzschlag.",
	["Use Sunder Armor up to five times on the main enemy. It cuts its armor and keeps its attention."] = "Nutze Rüstung zerreißen bis zu fünfmal auf den Hauptgegner. Das senkt seine Rüstung und hält seine Aufmerksamkeit bei dir.",
	["Use all suggested settings"] = "Alle Vorschläge übernehmen",
	["Use the crystals to weaken him."] = "Nutze die Kristalle, um ihn zu schwächen.",
	["Use the trainee soldiers to hold him."] = "Nutze die Rekruten, um ihn aufzuhalten.",
	["Use your hearthstone to go back to your inn."] = "Nutze deinen Ruhestein, um zu deinem Gasthaus zurückzukehren.",
	["Uses totems, spells and melee. Can heal or deal damage."] = "Nutzt Totems, Zauber und Nahkampf. Kann heilen oder Schaden machen.",
	["Uses up"] = "Verbraucht",
	["Vendor"] = "Händler",
	["Vendors sell food, drink and gear, and some of them repair what you wear. Ask a guard if you cannot find a place in a city."] = "Händler verkaufen Essen, Getränke und Ausrüstung, und manche reparieren, was du trägst. Frag eine Wache, wenn du in einer Stadt etwas nicht findest.",
	["Visit your class trainer"] = "Besuch deinen Klassenlehrer",
	["Visit your class trainer for new spells"] = "Besuch deinen Klassenlehrer für neue Zauber",
	["Visit your class trainer once. From then on Trailhead lists what you can learn, what it costs and what is coming at later levels."] = "Besuch einmal deinen Klassenlehrer. Danach zeigt Trailhead, was du lernen kannst, was es kostet und was auf späteren Stufen kommt.",
	["Visit your class trainer once: Trailhead then knows every ability that is coming and what it costs."] = "Besuch einmal deinen Klassenlehrer: Dann kennt Trailhead jede kommende Fähigkeit und ihre Kosten.",
	["Waist"] = "Taille",
	["Wait for the whole group before you start the stairs event."] = "Warte auf die ganze Gruppe, bevor du das Treppen-Ereignis startest.",
	["Wakes in the big hall once someone uses the medallion and the shaft."] = "Erwacht in der großen Halle, sobald jemand das Medaillon und den Schacht benutzt.",
	["Walk down the long ramp into the lava cave. The path soon splits into side tunnels."] = "Geh die lange Rampe hinunter in die Lavahöhle. Der Weg teilt sich bald in Seitentunnel.",
	["Walk in from the portal. The first part is the Detention Block, a prison."] = "Geh vom Portal aus hinein. Der erste Teil ist der Detention Block, ein Gefängnis.",
	["Walk in past the guards to the first room."] = "Geh an den Wachen vorbei in den ersten Raum.",
	["Walk in through the cave and past the whelps to the big cave at the end."] = "Geh durch die Höhle, an den Welpen vorbei, bis zur großen Höhle am Ende.",
	["Walk in to the first boss."] = "Geh hinein bis zum ersten Boss.",
	["Walk in. The priests stand in different parts of the city. Pick them in any order."] = "Geh hinein. Die Priester stehen in verschiedenen Teilen der Stadt. Die Reihenfolge ist egal.",
	["Walk into the Stone Door on the west side of the Valley of Spears in Desolace. At the fork, right is orange, left is purple and the middle gate leads to Earth Song Falls."] = "Geh durch die Steintür an der Westseite vom Tal der Speere in Desolace. An der Gabelung führt rechts zu Orange, links zu Lila, und das mittlere Tor führt zu den Earth Song Falls.",
	["Walk into the last chamber. It has a low floor and a raised ledge behind it. Go up to the ledge."] = "Geh in die letzte Kammer. Sie hat einen tiefen Boden und dahinter einen erhöhten Sims. Geh hinauf auf den Sims.",
	["Walk to %s"] = "Geh nach %s",
	["Walk to the flight master in %s"] = "Geh zum Flugmeister in %s",
	["Walks among the shallow graves near the start."] = "Wandelt zwischen den flachen Gräbern nahe dem Eingang.",
	["Watch your party's health bars. Heal whoever is lowest."] = "Behalte die Gesundheitsleisten deiner Gruppe im Blick. Heil den, der am niedrigsten ist.",
	["Ways to travel"] = "Reisemöglichkeiten",
	["We do not know yet where this boss stands."] = "Wir wissen noch nicht, wo dieser Boss steht.",
	["Weapon hits can make your next Lightning Bolt faster and cheaper."] = "Waffentreffer können deinen nächsten Blitzschlag schneller und billiger machen.",
	["Weapon master"] = "Waffenmeister",
	["Weapon skills"] = "Waffenfertigkeiten",
	["Weapons"] = "Waffen",
	["Weegli must set the door charges before the stairs event, or this door stays shut. If you fight up close, avoid his sweeping hits."] = "Weegli muss vor dem Treppen-Ereignis die Türladungen anbringen, sonst bleibt diese Tür zu. Wer nah dran kämpft, weicht seinen Schwungangriffen aus.",
	["Weekly reset"] = "Wöchentlicher Reset",
	["Weekly tasks that give Honor and Rank Points"] = "Wöchentliche Aufgaben für Ehre und Rangpunkte",
	["Welcome"] = "Willkommen",
	["Welcome back after %s"] = "Willkommen zurück nach %s",
	["Welcome to Trailhead"] = "Willkommen bei Trailhead",
	["Welcome! Click the minimap button or type /th to open Trailhead."] = "Willkommen! Klick auf den Minikartenknopf oder gib /th ein, um Trailhead zu öffnen.",
	["Well Rested: rested experience builds faster"] = "Gut ausgeruht: Erholung baut sich schneller auf",
	["West part now. The Crescent Key opens the door. Walk through the Capital Gardens."] = "Jetzt der Westteil. Der Mondsichelschlüssel öffnet die Tür. Geh durch die Capital Gardens.",
	["What earns a point"] = "Was einen Punkt bringt",
	["What is new"] = "Was ist neu",
	["What it is"] = "Was es ist",
	["What now?"] = "Was jetzt?",
	["What points unlock"] = "Was Punkte freischalten",
	["What starts over once a week in Forever, read from your game where it can be."] = "Was in Forever einmal pro Woche neu beginnt, wo möglich aus deinem Spiel gelesen.",
	["What to do next"] = "Was als Nächstes",
	["What to look for on gear"] = "Worauf du bei Ausrüstung achten solltest",
	["What you can use, what you can learn, and what comes next."] = "Was du nutzen kannst, was du lernen kannst und was als Nächstes kommt.",
	["What your next levels bring: new abilities at your class trainer, and the dungeons and zones that open up. Levels with nothing new are left out."] = "Was deine nächsten Stufen bringen: neue Fähigkeiten bei deinem Klassenlehrer und die Dungeons und Zonen, die sich öffnen. Stufen ohne Neues sind ausgelassen.",
	["When Lightning Bolt gets cheap and fast after weapon hits, cast it."] = "Wenn Blitzschlag nach Waffentreffern billig und schnell wird, wirk ihn.",
	["When Mograine falls, she brings him back. Kill them in turn."] = "Wenn Mograine fällt, holt sie ihn zurück. Tötet sie abwechselnd.",
	["When Rejuvenation or Regrowth runs out, the friend gets a final heal."] = "Wenn Verjüngung oder Nachwachsen ausläuft, bekommt der Verbündete eine letzte Heilung.",
	["When Trailhead opens your spellbook, talents or map, it moves next to them."] = "Wenn Trailhead dein Zauberbuch, deine Talente oder die Karte öffnet, rückt es daneben.",
	["When he calls skeletons, kill them quickly."] = "Wenn er Skelette ruft, töte sie schnell.",
	["When he dies, the door to the courtyard opens."] = "Wenn er stirbt, öffnet sich die Tür zum Hof.",
	["When he splits into copies, kill them one at a time."] = "Wenn er sich in Kopien teilt, töte sie eine nach der anderen.",
	["When she takes off, run away from the fire."] = "Wenn sie abhebt, lauf weg vom Feuer.",
	["When the whole group is hurt, use Wild Growth on the one who is hit most."] = "Wenn die ganze Gruppe verletzt ist, wirk Wildwuchs auf den, der am meisten getroffen wird.",
	["When you die you can release your spirit to the nearest graveyard and run back to your body as a ghost: coming back to life there has no penalty. The Spirit Healer at the graveyard can bring you back on the spot instead, but that damages your gear and can leave you with Resurrection Sickness, which makes you much weaker for a while."] = "Wenn du stirbst, kannst du deinen Geist zum nächsten Friedhof freilassen und als Geist zu deiner Leiche zurücklaufen: Dort wiederbelebt zu werden hat keine Nachteile. Der Geistheiler am Friedhof kann dich stattdessen sofort zurückholen, aber das beschädigt deine Ausrüstung und kann dir Wiederbelebungsnachwirkungen geben, die dich eine Weile deutlich schwächer machen.",
	["When you pick up a new kind of weapon, look here first: a skill far under its limit means you will hit and crit a little less often until you have used it for a while."] = "Wenn du eine neue Waffenart aufnimmst, schau zuerst hier: Eine Fertigkeit weit unter ihrem Maximum heißt, dass du etwas seltener triffst und kritisch triffst, bis du sie eine Weile benutzt hast.",
	["Where"] = "Wo",
	["Where to start in %s"] = "Wo du in %s anfängst",
	["Where to start. Quests for %s"] = "Wo du anfängst. Quests für %s",
	["Where you stand"] = "Wo du stehst",
	["Where your talent points go, one point at a time."] = "Wohin deine Talentpunkte gehen, Punkt für Punkt.",
	["Whisper: a private message to one player."] = "Flüstern: eine private Nachricht an einen Spieler.",
	["Window"] = "Fenster",
	["Window position"] = "Fensterposition",
	["Window size"] = "Fenstergröße",
	["Wing Clip (level 12) slows an enemy that reaches you. Step back, then shoot."] = "Zurechtstutzen (Stufe 12) verlangsamt einen Gegner, der dich erreicht. Geh zurück und schieß dann.",
	["Wipe"] = "Wipe",
	["With Righteous Fury on, you take less damage."] = "Mit Zorn der Gerechtigkeit erleidest du weniger Schaden.",
	["With a shield in Defensive Stance, enemies pay even more attention to you."] = "Mit einem Schild in Verteidigungshaltung achten Gegner noch mehr auf dich.",
	["With others"] = "Mit anderen",
	["Words and chat"] = "Begriffe und Chat",
	["Working Overtime: skill rises faster"] = "Überstunden machen: Fertigkeit steigt schneller",
	["World of Warcraft: Forever adds a few systems of its own: Legacy, which carries rewards between your characters, camping, and rulesets that decide who you play with."] = "World of Warcraft: Forever bringt ein paar eigene Systeme mit: Vermächtnis, das Belohnungen zwischen deinen Charakteren überträgt, Camping und Regelwerke, die bestimmen, mit wem du spielst.",
	["Wrist"] = "Handgelenke",
	["Writes your health and mana as numbers and percentages on the bars."] = "Zeigt deine Gesundheit und dein Mana als Zahlen und Prozente auf den Leisten.",
	["Yellow"] = "Gelb",
	["Yes, forget"] = "Ja, vergessen",
	["You already have the %s for riding. Keep it aside until level %d."] = "Du hast schon %s fürs Reiten. Leg es bis Stufe %d beiseite.",
	["You are %d%% of the way to level %d."] = "Du hast %d%% des Wegs zu Stufe %d geschafft.",
	["You are %s short of the fee."] = "Dir fehlen %s für die Gebühr.",
	["You are a ghost"] = "Du bist ein Geist",
	["You are all set"] = "Alles erledigt",
	["You are at the cap for now. It goes up at the weekly reset."] = "Du bist vorerst am Limit. Es steigt beim wöchentlichen Reset.",
	["You are at the top level. Nothing more unlocks by levelling."] = "Du bist auf der Höchststufe. Durch Stufenaufstiege wird nichts mehr freigeschaltet.",
	["You are dead"] = "Du bist tot",
	["You are here"] = "Du bist hier",
	["You are in %s"] = "Du bist in %s",
	["You are in an inn or a city, so your rest is building up right now. Log out here when you stop playing and it keeps building while you are away."] = "Du bist in einem Gasthaus oder einer Stadt, also baut sich deine Erholung gerade auf. Logg dich hier aus, wenn du aufhörst, dann baut sie sich weiter auf, während du weg bist.",
	["You are inside."] = "Du bist drin.",
	["You are not in a group"] = "Du bist in keiner Gruppe",
	["You are not rested. When you stop playing, log out in an inn or a city: your rest builds up while you are away, and a rested character earns extra experience from monsters."] = "Du bist nicht erholt. Wenn du aufhörst zu spielen, logg dich in einem Gasthaus oder einer Stadt aus: Deine Erholung baut sich auf, während du weg bist, und ein erholter Charakter bekommt mehr Erfahrung von Monstern.",
	["You are not saved to any raid"] = "Du bist in keinem Schlachtzug gespeichert",
	["You are rested, so monsters give more experience until the bonus runs out. When you stop playing, log out in an inn or a city to build it up again."] = "Du bist erholt, also geben Monster mehr Erfahrung, bis der Bonus aufgebraucht ist. Wenn du aufhörst, logg dich in einem Gasthaus oder einer Stadt aus, um ihn wieder aufzubauen.",
	["You are standing next to them."] = "Du stehst direkt neben ihnen.",
	["You block more often, and each block gives you Rage."] = "Du blockst öfter, und jeder Block gibt dir Wut.",
	["You block much more for a while, and enemies that you block take damage."] = "Du blockst eine Weile viel öfter, und Gegner, die du blockst, erleiden Schaden.",
	["You can afford riding now. See the Mount topic."] = "Du kannst dir jetzt das Reiten leisten. Siehe Thema Reittier.",
	["You can kill the troll priests in many orders. Ask your raid leader for the plan."] = "Ihr könnt die Trollpriester in vielen Reihenfolgen töten. Frag deinen Schlachtzugsleiter nach dem Plan.",
	["You can learn to ride at level 40. It is expensive, so start saving gold early."] = "Reiten kannst du ab Stufe 40 lernen. Es ist teuer, also fang früh an, Gold zu sparen.",
	["You can learn to ride now. Go to %s in %s."] = "Du kannst jetzt reiten lernen. Geh zu %s in %s.",
	["You can learn to ride now. Go to your race's riding trainer."] = "Du kannst jetzt reiten lernen. Geh zum Reitlehrer deines Volkes.",
	["You can learn to ride now. See the Mount topic."] = "Du kannst jetzt reiten lernen. Siehe Thema Reittier.",
	["You can ride"] = "Du kannst reiten",
	["You can ride, use your hearthstone, fly with a flight master, or take a boat, a zeppelin or the tram between far places."] = "Du kannst reiten, deinen Ruhestein nutzen, mit einem Flugmeister fliegen oder zwischen fernen Orten ein Schiff, einen Zeppelin oder die Tiefenbahn nehmen.",
	["You can wear"] = "Tragbar",
	["You can wear it from level %d."] = "Tragbar ab Stufe %d.",
	["You can't use this: %s"] = "Nicht nutzbar: %s",
	["You carry no food or drink. Buy some before you leave town."] = "Du hast weder Essen noch Getränke dabei. Kauf welche, bevor du die Stadt verlässt.",
	["You deal more damage while you hold a shield."] = "Du machst mehr Schaden, solange du einen Schild trägst.",
	["You dodge more, so you take less damage."] = "Du weichst öfter aus und erleidest so weniger Schaden.",
	["You fight this one in the water. Guides disagree on whether he comes before or after Kelris."] = "Diesen Kampf führst du im Wasser. Guides sind sich uneinig, ob er vor oder nach Kelris kommt.",
	["You have"] = "Du hast",
	["You have %d talent points to spend. Unspent points do nothing."] = "Du hast %d Talentpunkte zu verteilen. Nicht verteilte Punkte bringen nichts.",
	["You have %s so far."] = "Du hast bisher %s.",
	["You have %s, so keep some aside."] = "Du hast %s, also leg etwas beiseite.",
	["You have 1 talent point to spend. Unspent points do nothing."] = "Du hast 1 Talentpunkt zu verteilen. Nicht verteilte Punkte bringen nichts.",
	["You have Resurrection Sickness. Stay out of fights until it wears off, and have your gear repaired."] = "Du hast Wiederbelebungsnachwirkungen. Halte dich aus Kämpfen raus, bis sie abklingen, und lass deine Ausrüstung reparieren.",
	["You have a mount. The faster lesson comes at level %d, for %s."] = "Du hast ein Reittier. Die schnellere Lektion kommt auf Stufe %d, für %s.",
	["You have a mount. The faster lesson is open to you now, for %s."] = "Du hast ein Reittier. Die schnellere Lektion steht dir jetzt offen, für %s.",
	["You have been here"] = "Du warst schon hier",
	["You have done every first step. Well done."] = "Du hast alle ersten Schritte erledigt. Gut gemacht.",
	["You have enough for that already."] = "Dafür hast du schon genug.",
	["You have food and drink with you. Look here again before you leave a town."] = "Du hast Essen und Getränke dabei. Schau wieder hier, bevor du eine Stadt verlässt.",
	["You have learned everything your trainer offers for now."] = "Du hast vorerst alles gelernt, was dein Lehrer anbietet.",
	["You have no professions yet. Profession trainers in towns and cities teach them."] = "Du hast noch keine Berufe. Berufslehrer in Städten bringen sie dir bei.",
	["You have no talent points yet. They come as you level up."] = "Du hast noch keine Talentpunkte. Sie kommen mit deinen Stufenaufstiegen.",
	["You have not found this flight point yet, so you cannot fly to it. Walk there once and talk to the flight master."] = "Du hast diesen Flugpunkt noch nicht entdeckt, also kannst du nicht dorthin fliegen. Geh einmal hin und sprich mit dem Flugmeister.",
	["You have outgrown %s"] = "Du bist %s entwachsen",
	["You have talent points to spend"] = "Du hast Talentpunkte zu verteilen",
	["You have talent points to spend. Unspent points do nothing."] = "Du hast Talentpunkte zu verteilen. Nicht verteilte Punkte bringen nichts.",
	["You hit harder with every attack in Bear Form."] = "Du triffst in Bärengestalt mit jedem Angriff härter.",
	["You keep more Rage when you change stance."] = "Du behältst mehr Wut, wenn du die Haltung wechselst.",
	["You keep some Mana regeneration while casting, handy when you heal."] = "Du behältst beim Zaubern etwas Manaregeneration, praktisch beim Heilen.",
	["You keep your party alive in a dungeon, mostly with Holy healing. Renew heals over time, and Power Word: Shield stops a hit before it lands."] = "Du hältst deine Gruppe im Dungeon am Leben, meist mit Heilig-Heilung. Erneuerung heilt über Zeit, und Machtwort: Schild fängt einen Treffer ab, bevor er landet.",
	["You know these but cannot use them yet. Open your spellbook and drag each one to an empty bar slot."] = "Du kennst diese, kannst sie aber noch nicht benutzen. Öffne dein Zauberbuch und zieh jede auf einen freien Leistenplatz.",
	["You miss a little less often with attacks."] = "Du verfehlst mit Angriffen etwas seltener.",
	["You parry a little more often."] = "Du parierst etwas öfter.",
	["You parry more, and at 3 of 3 it opens Riposte."] = "Du parierst öfter, und bei 3 von 3 schaltet es Riposte frei.",
	["You reached the top"] = "Du hast den Gipfel erreicht",
	["You run faster in Cat Form (level 20), and you dodge more."] = "Du läufst in Katzengestalt (Stufe 20) schneller und weichst öfter aus.",
	["You run faster, on foot and on a mount."] = "Du läufst schneller, zu Fuß und auf einem Reittier.",
	["You spend the points yourself in the game's talent window. Trailhead shows where each one goes."] = "Die Punkte verteilst du selbst im Talentfenster des Spiels. Trailhead zeigt, wohin jeder gehört.",
	["You take less damage from enemy spells."] = "Du erleidest weniger Schaden durch gegnerische Zauber.",
	["You wear"] = "Du trägst",
	["You were %d%% of the way to level %d."] = "Du hattest %d%% des Wegs zu Stufe %d geschafft.",
	["Your %s skill is behind: %d of %d. By the game's own figures that costs about %.1f%% of your chance to hit and to crit an enemy of your level. Keep using it on enemies you beat easily until it catches up."] = "Deine Fertigkeit %s hinkt hinterher: %d von %d. Nach den Werten des Spiels kostet dich das etwa %.1f%% deiner Chance, einen Gegner deiner Stufe zu treffen und kritisch zu treffen. Nutze sie weiter an leichten Gegnern, bis sie aufholt.",
	["Your %s skill is low"] = "Deine Fertigkeit %s ist niedrig",
	["Your Affliction spells reach 20% further, so you can start fights from safer ground."] = "Deine Gebrechenszauber reichen 20% weiter, so kannst du Kämpfe aus sichererer Entfernung beginnen.",
	["Your Aspect of the Hawk can make your shots come faster for a short time."] = "Dein Aspekt des Falken kann deine Schüsse kurz schneller machen.",
	["Your Drain spells do more, and Drain Life heals you more."] = "Deine Entzugszauber wirken stärker, und Blutsauger heilt dich mehr.",
	["Your Energy comes back twice as fast for a while: your big button."] = "Deine Energie kommt eine Weile doppelt so schnell zurück: dein großer Knopf.",
	["Your Frost Armor protects you more, and so will Ice Barrier when you learn it."] = "Deine Frostrüstung schützt dich besser, und Eisbarriere ebenso, wenn du sie lernst.",
	["Your Frost spells hit harder when they critically strike."] = "Deine Frostzauber treffen härter, wenn sie kritisch treffen.",
	["Your Frostbolt reaches a little further, so you start fights from safer ground."] = "Dein Frostblitz reicht etwas weiter, so beginnst du Kämpfe aus sichererer Entfernung.",
	["Your Holy spells miss less, and Silence effects on you end sooner."] = "Deine Heilig-Zauber verfehlen seltener, und Stille-Effekte auf dir enden früher.",
