	["Your class"] = "Deine Klasse",
	["Your class can be: %s."] = "Deine Klasse kann sein: %s.",
	["Your class can wear only some kinds of armor, and the game lists them among your skills. Most pieces also have a durability that runs down, and a vendor who does repairs restores it for a fee."] = "Deine Klasse kann nur bestimmte Rüstungsarten tragen, und das Spiel führt sie unter deinen Fertigkeiten auf. Die meisten Teile haben außerdem eine Haltbarkeit, die abnimmt, und ein Händler mit Reparaturdienst stellt sie gegen eine Gebühr wieder her.",
	["Your class gets a mount of its own at level %d, through your class trainer or a class quest, so you need not save for riding."] = "Deine Klasse bekommt auf Stufe %d ein eigenes Reittier, über deinen Klassenlehrer oder eine Klassenquest, also musst du nicht fürs Reiten sparen.",
	["Your class gets a mount of its own from level %d, through your class trainer or a class quest, without the riding fee. Ask your class trainer."] = "Deine Klasse bekommt ab Stufe %d ein eigenes Reittier, über deinen Klassenlehrer oder eine Klassenquest, ohne Reitgebühr. Frag deinen Klassenlehrer.",
	["Your class gets its own mount. Ask your class trainer."] = "Deine Klasse bekommt ein eigenes Reittier. Frag deinen Klassenlehrer.",
	["Your class has its own way to fight and some needs other classes do not have. This is the short version. Your trainer has the rest."] = "Deine Klasse kämpft auf ihre eigene Art und hat Bedürfnisse, die andere Klassen nicht haben. Das hier ist die Kurzfassung. Den Rest weiß dein Lehrer.",
	["Your class trainer teaches them."] = "Dein Klassenlehrer bringt sie dir bei.",
	["Your companion on the road to level 60."] = "Dein Begleiter auf dem Weg zu Stufe 60.",
